  @@index([shopping_mall_seller_id, fulfillment_status], map: "shopping_mall_order_items_shopping_mall_seller_id_fulf_4d8e6433")
  // spellchecker: ignore-next-line
  @@index([variant_sku, shopping_mall_seller_id], map: "shopping_mall_order_items_variant_sku_shopping_mall_se_30ae2751")
  @@index([product_name_snapshot(ops: raw("gin_trgm_ops"))], type: Gin)
