import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IBackupCodes } from "@ORGANIZATION/PROJECT-api/lib/structures/IBackupCodes";
import type { IQrCodeData } from "@ORGANIZATION/PROJECT-api/lib/structures/IQrCodeData";
import type { ISecurityContext } from "@ORGANIZATION/PROJECT-api/lib/structures/ISecurityContext";
import type { IShoppingMallAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAuthentication";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";

/**
 * Test email-based multi-factor authentication enablement with backup email
 * address provision. Validates email format requirements, backup authentication
 * method configuration, and proper security context establishment for enhanced
 * account security.
 *
 * 1. Create a new customer account through registration
 * 2. Enable email-based MFA with backup email configuration
 * 3. Validate that the MFA setup response includes required components
 * 4. Verify backup codes are generated for account recovery
 * 5. Confirm security context is properly established
 */
export async function test_api_customer_mfa_enable_email_with_backup_email(
  connection: api.IConnection,
): Promise<void> {
  // Create new customer account first
  const primaryEmail = `customer.${RandomGenerator.alphaNumeric(8)}@example.com`;
  const backupEmail = `backup.${RandomGenerator.alphaNumeric(8)}@different-domain.com`;

  // Customer registration with comprehensive profile data
  const registrationData = {
    email: primaryEmail,
    password: "TestPassword123!",
    first_name: RandomGenerator.name(1),
    last_name: RandomGenerator.name(1),
    phone: RandomGenerator.mobile("010"),
    href: "https://shoppingmall.com/register",
    referrer: "https://shoppingmall.com/login",
  } satisfies IShoppingMallCustomer.IRegister;

  const customer = await api.functional.auth.customer.join(connection, {
    body: registrationData,
  });
  typia.assert(customer);

  TestValidator.predicate(
    "Customer account created successfully",
    customer.id !== null,
  );
  TestValidator.predicate(
    "Email verification required for new accounts",
    !customer.is_email_verified,
  );
  TestValidator.predicate("Account is active", customer.status === true);

  // Enable email-based MFA with backup email configuration
  const mfaSetupRequest = {
    mfa_type: "email" as const,
    backup_email: backupEmail,
    ip: "203.0.113.1",
    href: "https://shoppingmall.com/security/mfa/enable",
    referrer: "https://shoppingmall.com/account/security",
  } satisfies IShoppingMallAuthentication.IEnableMfa;

  const mfaSetupResponse =
    await api.functional.shoppingMall.customer.auth.mfa.enable.enableMfa(
      connection,
      {
        body: mfaSetupRequest,
      },
    );
  typia.assert(mfaSetupResponse);

  // Validate MFA setup response structure
  TestValidator.equals(
    "Email MFA type correctly configured",
    mfaSetupResponse.mfa_type,
    "email",
  );
  TestValidator.predicate(
    "MFA setup requires verification",
    mfaSetupResponse.verification_required === true,
  );

  // Validate backup codes generation for account recovery
  TestValidator.predicate(
    "Backup codes array has minimum required codes",
    mfaSetupResponse.backup_codes.length >= 8,
  );
  TestValidator.predicate(
    "Backup codes array does not exceed maximum",
    mfaSetupResponse.backup_codes.length <= 10,
  );

  // Validate individual backup code format
  TestValidator.predicate(
    "Each backup code has correct length format",
    mfaSetupResponse.backup_codes.every(
      (code) => code.length === 8 && /^[A-Za-z0-9]{8}$/.test(code),
    ),
  );

  TestValidator.predicate(
    "Setup instructions provided for user guidance",
    mfaSetupResponse.setup_instructions.length > 0,
  );

  // Validate security context establishment
  TestValidator.predicate(
    "Security context properly established",
    mfaSetupResponse.verification_required === true,
  );

  TestValidator.predicate(
    "MFA enablement successful with backup email",
    customer !== null && mfaSetupResponse !== null,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallGuest";

/**
 * Test successful guest session refresh with valid session ID.
 *
 * This test validates the guest authentication refresh functionality within the
 * shopping mall platform. The scenario establishes a complete guest
 * authentication flow:
 *
 * 1. Create a new guest session with realistic browsing context
 * 2. Validate the initial guest authentication response
 * 3. Refresh the guest session to obtain updated tokens
 * 4. Verify session continuity and token updates
 * 5. Validate that browsing capabilities persist across token refresh
 *
 * The test ensures that anonymous users can maintain their shopping experience
 * without interruption while preserving session security and token lifecycle
 * management. This is essential for e-commerce platforms where guest users need
 * seamless access to product browsing, cart management, and basic platform
 * features.
 */
export async function test_api_guest_refresh_successful(
  connection: api.IConnection,
) {
  // Step 1: Create initial guest session with realistic browsing context
  const currentTime = new Date().toISOString();
  const sessionId = RandomGenerator.alphaNumeric(32);

  const guestCreateRequest = {
    href: "https://shopping-mall.example.com/products/electronics",
    referrer: "https://search-engine.example.com/search?q=smartphones",
    session_id: sessionId,
    user_agent: "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
    last_activity_at: currentTime,
    created_at: currentTime,
    updated_at: currentTime,
  } satisfies IShoppingMallGuest.ICreate;

  // Establish guest authentication
  const initialGuestAuth = await api.functional.auth.guest.join(connection, {
    body: guestCreateRequest,
  });
  typia.assert(initialGuestAuth);

  // Step 2: Validate initial guest authentication response
  TestValidator.predicate(
    "initial guest auth has valid UUID",
    initialGuestAuth.id.length > 0,
  );
  TestValidator.equals(
    "session ID matches request",
    initialGuestAuth.session_id,
    sessionId,
  );

  // Validate token structure
  typia.assert<IAuthorizationToken>(initialGuestAuth.token);

  // Step 3: Refresh the guest session to obtain updated tokens
  const refreshRequest = {
    session_id: sessionId,
  } satisfies IShoppingMallGuest.IRefresh;

  const refreshedGuestAuth = await api.functional.auth.guest.refresh(
    connection,
    { body: refreshRequest },
  );
  typia.assert(refreshedGuestAuth);

  // Step 4: Verify session continuity and token updates
  TestValidator.equals(
    "session ID remains constant after refresh",
    refreshedGuestAuth.session_id,
    sessionId,
  );
  TestValidator.equals(
    "guest ID remains constant after refresh",
    refreshedGuestAuth.id,
    initialGuestAuth.id,
  );

  // Validate new token is different from original
  TestValidator.notEquals(
    "access token is updated after refresh",
    refreshedGuestAuth.token.access,
    initialGuestAuth.token.access,
  );
  TestValidator.notEquals(
    "refresh token is updated after refresh",
    refreshedGuestAuth.token.refresh,
    initialGuestAuth.token.refresh,
  );

  // Step 5: Validate that browsing capabilities persist across token refresh
  TestValidator.predicate(
    "new token has valid expiration date",
    new Date(refreshedGuestAuth.token.expired_at) > new Date(),
  );
  TestValidator.predicate(
    "new token has valid refreshable period",
    new Date(refreshedGuestAuth.token.refreshable_until) > new Date(),
  );

  // Verify IP address and user agent consistency
  TestValidator.equals(
    "IP address remains consistent",
    refreshedGuestAuth.ip_address,
    initialGuestAuth.ip_address,
  );
  TestValidator.equals(
    "user agent remains consistent",
    refreshedGuestAuth.user_agent,
    initialGuestAuth.user_agent,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallGuest";

export async function test_api_guest_refresh_extended_activity(
  connection: api.IConnection,
) {
  // Simulate extended guest browsing session starting 30 minutes ago
  const sessionStartTime = new Date(Date.now() - 1000 * 60 * 30); // 30 minutes ago

  // Create initial guest session with realistic browsing metadata
  const initialGuestData = {
    session_id: RandomGenerator.alphaNumeric(24),
    ip: "192.168.1.100" satisfies string & tags.Format<"ipv4">,
    href: "https://shopping-mall.example.com/products/electronics",
    referrer: "https://google.com/search",
    user_agent: "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
    last_activity_at: sessionStartTime.toISOString(),
    created_at: sessionStartTime.toISOString(),
    updated_at: sessionStartTime.toISOString(),
  } satisfies IShoppingMallGuest.ICreate;

  // Join as guest user to establish session
  const guestSession = await api.functional.auth.guest.join(connection, {
    body: initialGuestData,
  });
  typia.assert(guestSession);

  // Simulate realistic extended browsing patterns
  // 1. Initial product search and browsing
  const searchTimestamp = new Date(Date.now() - 1000 * 60 * 20).toISOString();

  // 2. Product page views with navigation
  const productViews = [
    "https://shopping-mall.example.com/products/smartphones/iphone-15",
    "https://shopping-mall.example.com/products/laptops/macbook-pro-14",
    "https://shopping-mall.example.com/products/tablets/ipad-air",
  ];

  // 3. Cart interactions
  const cartTimestamp = new Date(Date.now() - 1000 * 60 * 10).toISOString();

  // 4. Checkout process simulation
  const checkoutTimestamp = new Date(Date.now() - 1000 * 60 * 5).toISOString();

