  TestValidator.predicate(
    "extended session tokens remain valid",
    () => finalSession.token.access.length > 0,
  );

  TestValidator.predicate(
    "refresh tokens remain usable after extended activity",
    () => finalSession.token.refresh.length > 0,
  );
