    "admin ID is valid UUID format",
    typeof superAdminResponse.id,
    "string",
  );
  TestValidator.predicate(
    "admin ID follows UUID format",
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
