    registeredSeller.id,
  );
  TestValidator.equals(
    "business name matches",
    authorizedSeller.business_name,
    registeredSeller.business_name,
  );
  TestValidator.equals(
    "business registration number matches",
    authorizedSeller.business_registration_number,
    registeredSeller.business_registration_number,
  );
  TestValidator.equals(
    "email matches",
    authorizedSeller.email,
    registeredSeller.email,
  );
  TestValidator.equals(
    "phone matches",
    authorizedSeller.phone,
    registeredSeller.phone,
  );
  TestValidator.equals(
    "tax_id matches",
    authorizedSeller.tax_id,
    registeredSeller.tax_id,
  );
  TestValidator.equals(
    "business type matches",
    authorizedSeller.business_type,
    registeredSeller.business_type,
  );

  // Step 4: Validate business information and commission rate
  TestValidator.equals(
    "commission rate matches",
    authorizedSeller.commission_rate,
    registeredSeller.commission_rate,
