    reason: "user_action",
    sessionCleanup: true,
  } satisfies IShoppingMallLogoutRequest;

  // Execute logout operation
  const logoutResponse = await api.functional.shoppingMall.auth.logout(
    connection,
    {
      body: logoutRequest,
    },
