/**
 * Test all available product catalog sorting options including price
 * directions, popularity ratings, newest arrivals, and relevance scoring.
 * Validates marketplace UX by ensuring customers can sort results according to
 * their preference for better product discovery. Covers sorting by
 * 'price_low_to_high' for budget-conscious shopping and 'rating' for
 * quality-first decisions among other options.
 */
export async function test_api_product_catalog_sorting_options(
  connection: api.IConnection,
) {
  // Create test scenario with multiple products for sorting validation
  // Step 1: Test price-based sorting with ascending order
  const priceLowToHighRequest = {
    page: 1,
    limit: 20,
    sortBy: "price_low_to_high",
    orderBy: "asc",
    minPrice: typia.random<number & tags.Minimum<10> & tags.Maximum<50>>(),
    maxPrice: typia.random<number & tags.Minimum<100> & tags.Maximum<500>>(),
    includeOutOfStock: false,
  } satisfies IShoppingMallProduct.IRequest;

  const priceLowToHighResponse =
    await api.functional.shoppingMall.products.index(connection, {
      body: priceLowToHighRequest,
    });
  typia.assert(priceLowToHighResponse);

  // Validate products are sorted by ascending price
  for (let i = 1; i < priceLowToHighResponse.data.length; i++) {
    TestValidator.predicate(
      "Price should be sorted ascending",
      priceLowToHighResponse.data[i - 1].price <=
        priceLowToHighResponse.data[i].price,
    );
  }

  // Step 2: Test price high to low sorting with descending order
  const priceHighToLowRequest = {
    page: 1,
    limit: 20,
    sortBy: "price_high_to_low",
    orderBy: "desc",
    includeOutOfStock: false,
  } satisfies IShoppingMallProduct.IRequest;

  const priceHighToLowResponse =
    await api.functional.shoppingMall.products.index(connection, {
      body: priceHighToLowRequest,
    });
  typia.assert(priceHighToLowResponse);

  // Validate products are sorted by descending price
  for (let i = 1; i < priceHighToLowResponse.data.length; i++) {
    TestValidator.predicate(
      "Price should be sorted descending",
      priceHighToLowResponse.data[i - 1].price >=
        priceHighToLowResponse.data[i].price,
    );
  }

  // Step 3: Test alphabetical sorting by name
  const nameSortingRequest = {
    page: 1,
    limit: 15,
    sortBy: "name",
    orderBy: "asc",
    includeOutOfStock: true,
  } satisfies IShoppingMallProduct.IRequest;

  const nameSortingResponse = await api.functional.shoppingMall.products.index(
    connection,
    { body: nameSortingRequest },
  );
  typia.assert(nameSortingResponse);

  // Validate alphabetical sorting
  for (let i = 1; i < nameSortingResponse.data.length; i++) {
    TestValidator.predicate(
      "Products should be sorted alphabetically by name",
      nameSortingResponse.data[i - 1].name.toLowerCase() <=
        nameSortingResponse.data[i].name.toLowerCase(),
    );
  }

  // Step 4: Test newest products sorting
  const newestRequest = {
    page: 1,
    limit: 25,
    sortBy: "newest",
    orderBy: "desc",
    includeOutOfStock: false,
  } satisfies IShoppingMallProduct.IRequest;

  const newestResponse = await api.functional.shoppingMall.products.index(
    connection,
    { body: newestRequest },
  );
  typia.assert(newestResponse);

  // Step 5: Test popularity-based sorting
  const popularityRequest = {
    page: 1,
    limit: 30,
    sortBy: "popularity",
    orderBy: "desc",
    includeOutOfStock: false,
  } satisfies IShoppingMallProduct.IRequest;

  const popularityResponse = await api.functional.shoppingMall.products.index(
    connection,
    { body: popularityRequest },
  );
  typia.assert(popularityResponse);

  // Step 6: Test rating-based sorting for quality-first preferences
  const ratingRequest = {
    page: 1,
    limit: 20,
    sortBy: "rating",
    orderBy: "desc",
    includeOutOfStock: false,
  } satisfies IShoppingMallProduct.IRequest;

  const ratingResponse = await api.functional.shoppingMall.products.index(
    connection,
    { body: ratingRequest },
  );
  typia.assert(ratingResponse);

  // Step 7: Test relevance sorting (default behavior)
  const relevanceRequest = {
    page: 1,
    limit: 15,
    sortBy: "relevance",
    orderBy: "desc",
    search: RandomGenerator.name(),
    includeOutOfStock: true,
  } satisfies IShoppingMallProduct.IRequest;

  const relevanceResponse = await api.functional.shoppingMall.products.index(
    connection,
    { body: relevanceRequest },
  );
  typia.assert(relevanceResponse);

  // Step 8: Test combined filtering with sorting - budget-conscious category browsing
  const budgetCategoryRequest = {
    page: 1,
    limit: 18,
    sortBy: "price_low_to_high",
    orderBy: "asc",
    search: RandomGenerator.paragraph({ sentences: 2, wordMin: 4, wordMax: 8 }),
    minPrice: 1,
    maxPrice: 75,
    includeOutOfStock: false,
  } satisfies IShoppingMallProduct.IRequest;

  const budgetCategoryResponse =
    await api.functional.shoppingMall.products.index(connection, {
      body: budgetCategoryRequest,
    });
  typia.assert(budgetCategoryResponse);

  // Validate price range constraint
  budgetCategoryResponse.data.forEach((product) => {
    TestValidator.predicate(
      "Product price within budget range",
      product.price >= budgetCategoryRequest.minPrice! &&
        product.price <= budgetCategoryRequest.maxPrice!,
    );
  });

  // Step 9: Test premium products with high ratings and higher price points
  const premiumQualityRequest = {
    page: 1,
    limit: 12,
    sortBy: "rating",
    orderBy: "desc",
    minPrice: 100,
    includeOutOfStock: false,
  } satisfies IShoppingMallProduct.IRequest;

  const premiumQualityResponse =
    await api.functional.shoppingMall.products.index(connection, {
      body: premiumQualityRequest,
    });
  typia.assert(premiumQualityResponse);

  // Validate all products meet premium price threshold
  premiumQualityResponse.data.forEach((product) => {
    TestValidator.predicate(
      "Product meets premium price threshold",
      product.price >= premiumQualityRequest.minPrice!,
    );
  });

  // Step 10: Test complete sorting validation - verify all available sortBy options work
  const availableSortOptions = [
    "name",
    "price_low_to_high",
    "price_high_to_low",
    "newest",
    "popularity",
    "rating",
    "relevance",
  ] as const;

  await ArrayUtil.asyncForEach(availableSortOptions, async (sortOption) => {
    const sortTestRequest = {
      page: 1,
      limit: 10,
      sortBy: sortOption,
      orderBy: "desc" as const,
      includeOutOfStock: false,
    } satisfies IShoppingMallProduct.IRequest;

    const sortTestResponse = await api.functional.shoppingMall.products.index(
      connection,
      { body: sortTestRequest },
    );
    typia.assert(sortTestResponse);

    TestValidator.predicate(
      `Sort option ${sortOption} returns valid product data`,
      sortTestResponse.data.length > 0,
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallProduct";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductCategory";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Test product discovery filtered by creation dates within specific timeframes.
 * Validates that customers can find products added within their preferred
 * shopping periods or discover new arrivals. This supports marketplace
 * freshness by allowing customers to browse products created within recent time
 * periods for trend-based shopping scenarios.
 *
 * Test steps:
 *
 * 1. Create baseline product data by querying general catalog
 * 2. Test filtering products by recent date range (last 30 days)
 * 3. Test filtering products by narrow date range (specific 7-day window)
 * 4. Test pagination with date filtering
 * 5. Validate product data structure consistency
 * 6. Test date filtering combined with sorting and search
 * 7. Verify response contains correct pagination metadata
 */
export async function test_api_product_catalog_date_range_filtering(
  connection: api.IConnection,
) {
  // Step 1: Create baseline product data by querying general catalog
  const baselineRequest: IShoppingMallProduct.IRequest = {
    page: 1,
    limit: 10,
    sortBy: "newest",
    orderBy: "desc",
  };

  const baselineResults = await api.functional.shoppingMall.products.index(
    connection,
    {
      body: baselineRequest,
    },
  );
  typia.assert(baselineResults);

  TestValidator.equals(
    "baseline products page number",
    baselineResults.pagination.current,
    1,
  );
  TestValidator.predicate(
    "baseline products should have valid pagination data",
    baselineResults.pagination.records >= 0 &&
      baselineResults.pagination.pages >= 1,
  );

  // Step 2: Test filtering by recent timeframe (last 30 days)
  const thirtyDaysAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);
  const now = new Date();

  const recentRequest: IShoppingMallProduct.IRequest = {
    page: 1,
    limit: 10,
    sortBy: "newest",
    orderBy: "desc",
    startDate: thirtyDaysAgo.toISOString(),
    endDate: now.toISOString(),
  };

  const recentResults = await api.functional.shoppingMall.products.index(
    connection,
    {
      body: recentRequest,
    },
  );
  typia.assert(recentResults);

  TestValidator.equals(
    "recent products page number",
    recentResults.pagination.current,
    1,
  );
  TestValidator.predicate(
    "recent products should have valid pagination data",
    recentResults.pagination.records >= recentResults.data.length &&
      recentResults.pagination.pages >= 1,
  );

  // Step 3: Test filtering by narrow 7-day window
  const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);

  const narrowRequest: IShoppingMallProduct.IRequest = {
    page: 1,
    limit: 10,
    sortBy: "newest",
    orderBy: "desc",
    startDate: sevenDaysAgo.toISOString(),
    endDate: now.toISOString(),
  };

  const narrowResults = await api.functional.shoppingMall.products.index(
    connection,
    {
      body: narrowRequest,
    },
  );
  typia.assert(narrowResults);

  TestValidator.equals(
    "narrow window products page number",
    narrowResults.pagination.current,
    1,
  );

  // Step 4: Test pagination with date filtering
  const paginatedRequest: IShoppingMallProduct.IRequest = {
    page: 1,
    limit: 5, // Smaller page size for pagination test
    sortBy: "newest",
    orderBy: "desc",
    startDate: thirtyDaysAgo.toISOString(),
    endDate: now.toISOString(),
  };

  const page1Results = await api.functional.shoppingMall.products.index(
    connection,
    {
      body: paginatedRequest,
    },
  );
  typia.assert(page1Results);

  TestValidator.equals(
    "paginated results page number",
    page1Results.pagination.current,
    1,
  );

  // If there are more pages, test page 2
  if (page1Results.pagination.pages > 1) {
    const page2Request: IShoppingMallProduct.IRequest = {
      ...paginatedRequest,
      page: 2,
    };

    const page2Results = await api.functional.shoppingMall.products.index(
      connection,
      {
        body: page2Request,
      },
    );
    typia.assert(page2Results);

    TestValidator.equals(
      "page 2 number should be 2",
      page2Results.pagination.current,
      2,
    );
    TestValidator.predicate(
      "page 2 should have different set of products",
      page1Results.data.length > 0 && page2Results.data.length > 0,
    );
  }

  // Step 5: Validate product data structure consistency
  if (recentResults.data.length > 0) {
    const sampleProduct = recentResults.data[0];
    TestValidator.predicate(
      "product should have all required properties",
      typia.is<string>(sampleProduct.id) &&
        typia.is<string>(sampleProduct.name) &&
        typia.is<number>(sampleProduct.price) &&
        typia.is<string[]>(sampleProduct.images) &&
        typia.is<IShoppingMallSeller.ISummary>(sampleProduct.seller) &&
        typia.is<IShoppingMallProductCategory.ISummary>(sampleProduct.category),
    );
  }

  // Step 6: Test date filtering combined with search
  const searchWithDateRequest: IShoppingMallProduct.IRequest = {
    page: 1,
    limit: 10,
    sortBy: "relevance",
    search: RandomGenerator.name(1),
    startDate: thirtyDaysAgo.toISOString(),
    endDate: now.toISOString(),
  };

  const searchDateResults = await api.functional.shoppingMall.products.index(
    connection,
    {
      body: searchWithDateRequest,
    },
  );
  typia.assert(searchDateResults);

  TestValidator.predicate(
    "search with date filtering should return valid results",
    searchDateResults.data.length >= 0,
  );

  // Step 7: Test with historical date range (older products)
  const historicalStart = new Date(Date.now() - 90 * 24 * 60 * 60 * 1000);
  const historicalEnd = new Date(Date.now() - 60 * 24 * 60 * 60 * 1000);

  const historicalRequest: IShoppingMallProduct.IRequest = {
    page: 1,
    limit: 10,
    sortBy: "newest",
    orderBy: "desc",
    startDate: historicalStart.toISOString(),
    endDate: historicalEnd.toISOString(),
  };

  const historicalResults = await api.functional.shoppingMall.products.index(
    connection,
    {
      body: historicalRequest,
    },
  );
  typia.assert(historicalResults);

  TestValidator.equals(
    "historical products page number",
    historicalResults.pagination.current,
    1,
  );

  // Step 8: Test with ascending sort order and date filtering
  const oldestFirstRequest: IShoppingMallProduct.IRequest = {
    page: 1,
    limit: 10,
    sortBy: "newest",
    orderBy: "asc", // Oldest first
    startDate: thirtyDaysAgo.toISOString(),
    endDate: now.toISOString(),
  };

  const oldestFirstResults = await api.functional.shoppingMall.products.index(
    connection,
    {
      body: oldestFirstRequest,
    },
  );
  typia.assert(oldestFirstResults);

  TestValidator.equals(
    "oldest first sort page number",
    oldestFirstResults.pagination.current,
    1,
  );

  // Final validation: ensure all date range queries returned valid product summaries
  const allResults = [
    recentResults,
    narrowResults,
    searchDateResults,
    historicalResults,
    oldestFirstResults,
  ];

  TestValidator.predicate(
    "all date filtered results should contain valid product summaries",
    allResults.every((result) =>
      result.data.every(
        (product) =>
          !!product.id &&
          !!product.name &&
          product.price >= 0 &&
          Array.isArray(product.images) &&
          product.images.every((img) => typeof img === "string"),
      ),
    ),
  );
}

