import type { IPageIShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallProduct";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductCategory";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Test product discovery using descriptive product tags and product
 * classifications. This test validates tag-based navigation where customers
 * explore products by descriptive attributes like 'organic', 'handmade',
 * 'eco-friendly', or 'exclusive'. It demonstrates attribute-based shopping
 * experiences beyond traditional category navigation and supports marketplace
 * differentiation strategies.
 */
export async function test_api_product_catalog_tag_based_discovery(
  connection: api.IConnection,
) {
  // Test 1: Search products with organic/eco-friendly tags
  const ecoFriendlyRequest = {
    page: 1,
    limit: 20,
    search: "organic eco-friendly sustainable",
    tags: ["organic", "eco-friendly", "sustainable", "natural"],
    sortBy: "relevance",
    orderBy: "desc",
  } satisfies IShoppingMallProduct.IRequest;

  const ecoFriendlyProducts = await api.functional.shoppingMall.products.index(
    connection,
    { body: ecoFriendlyRequest },
  );
  typia.assert(ecoFriendlyProducts);

  TestValidator.predicate(
    "eco-friendly tag search returns sustainable products",
    ecoFriendlyProducts.data.length > 0,
  );

  // Test 2: Search handmade/artisan products
  const artisanalRequest = {
    page: 1,
    limit: 15,
    search: "handmade artisan craft",
    tags: ["handmade", "artisan", "craft", "traditional"],
    sortBy: "popularity",
    orderBy: "desc",
  } satisfies IShoppingMallProduct.IRequest;

  const artisanalProducts = await api.functional.shoppingMall.products.index(
    connection,
    { body: artisanalRequest },
  );
  typia.assert(artisanalProducts);

  TestValidator.predicate(
    "artisanal tag search returns handmade products",
    artisanalProducts.data.length > 0,
  );

  // Test 3: Search exclusive/luxury items
  const luxuryRequest = {
    page: 1,
    limit: 10,
    search: "exclusive premium luxury",
    tags: ["exclusive", "premium", "luxury", "limited-edition"],
    minPrice: 100,
    sortBy: "price_high_to_low",
    orderBy: "desc",
  } satisfies IShoppingMallProduct.IRequest;

  const luxuryProducts = await api.functional.shoppingMall.products.index(
    connection,
    { body: luxuryRequest },
  );
  typia.assert(luxuryProducts);

  TestValidator.predicate(
    "luxury tag search returns premium products",
    luxuryProducts.data.length > 0,
  );

  // Test 4: Multi-tag filtering with price ranges
  const multiTagRequest = {
    page: 1,
    limit: 25,
    tags: ["organic", "handmade", "local"],
    minPrice: 10,
    maxPrice: 200,
    availability: "in_stock",
    sortBy: "price_low_to_high",
    orderBy: "asc",
  } satisfies IShoppingMallProduct.IRequest;

  const multiTagProducts = await api.functional.shoppingMall.products.index(
    connection,
    { body: multiTagRequest },
  );
  typia.assert(multiTagProducts);

  TestValidator.predicate(
    "multi-tag filtering returns products within price range",
    multiTagProducts.data.length > 0,
  );

  // Validate price range constraints
  for (const product of multiTagProducts.data) {
    TestValidator.predicate(
      "product price within specified range",
      product.price >= 10 && product.price <= 200,
    );
  }

  // Test 5: Tag-based search with date filtering
  const startDate = new Date(
    Date.now() - 30 * 24 * 60 * 60 * 1000,
  ).toISOString();
  const endDate = new Date().toISOString();

  const recentEcoRequest = {
    page: 1,
    limit: 30,
    tags: ["organic", "new-arrival", "trending"],
    startDate,
    endDate,
    sortBy: "newest",
    orderBy: "desc",
  } satisfies IShoppingMallProduct.IRequest;

  const recentEcoProducts = await api.functional.shoppingMall.products.index(
    connection,
    { body: recentEcoRequest },
  );
  typia.assert(recentEcoProducts);

  TestValidator.predicate(
    "recent eco-friendly products search returns results",
    recentEcoProducts.data.length >= 0,
  );

  // Test 6: Pagination with tag-based discovery
  const paginatedRequest1 = {
    page: 1,
    limit: 5,
    tags: ["handmade", "artisan"],
    sortBy: "name",
    orderBy: "asc",
  } satisfies IShoppingMallProduct.IRequest;

  const page1Products = await api.functional.shoppingMall.products.index(
    connection,
    { body: paginatedRequest1 },
  );
  typia.assert(page1Products);

  const paginatedRequest2 = {
    page: 2,
    limit: 5,
    tags: ["handmade", "artisan"],
    sortBy: "name",
    orderBy: "asc",
  } satisfies IShoppingMallProduct.IRequest;

  const page2Products = await api.functional.shoppingMall.products.index(
    connection,
    { body: paginatedRequest2 },
  );
  typia.assert(page2Products);

  TestValidator.predicate(
    "different pages return different tag-filtered products",
    page1Products.data.length > 0 && page2Products.data.length > 0,
  );

  // Test 7: Validate tag count constraints
  const maxTagsRequest = {
    page: 1,
    limit: 10,
    tags: ArrayUtil.repeat(20, () =>
      RandomGenerator.pick(["eco", "organic", "artisan", "luxury"] as const),
    ),
    sortBy: "relevance",
    orderBy: "desc",
  } satisfies IShoppingMallProduct.IRequest;

  const maxTagsProducts = await api.functional.shoppingMall.products.index(
    connection,
    { body: maxTagsRequest },
  );
  typia.assert(maxTagsProducts);

  TestValidator.predicate(
    "maximum tag count filtering works correctly",
    maxTagsProducts.data.length >= 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";

/**
 * Test successful customer token refresh operation using valid refresh token.
 *
 * This test validates the complete token refresh flow for customer
 * authentication:
 *
 * 1. Generates realistic customer authorization data using the SDK's random
 *    function
 * 2. Uses the refresh token to request new tokens via the refresh endpoint
 * 3. Verifies the response contains valid customer profile data and new tokens
 * 4. Validates that new tokens have updated expiration timestamps
 * 5. Ensures the refresh token mechanism maintains session continuity
 * 6. Confirms authorization headers are properly updated by the SDK
 *
 * The test covers JWT token structure validation, expiration timestamp updates,
 * customer profile data consistency, and proper session management.
 */
export async function test_api_customer_token_refresh_success(
  connection: api.IConnection,
) {
  // Generate realistic customer authorization data using the SDK's random function
  // This simulates having valid tokens from a previous authentication
  const mockAuthorizedCustomer = api.functional.auth.customer.refresh.random();
  const validRefreshToken = mockAuthorizedCustomer.token.refresh;

  // Store original connection headers to verify they're updated
  const originalHeaders = { ...connection.headers };

  // Test the refresh endpoint with valid refresh token
  const refreshResponse: IShoppingMallCustomer.IAuthorized =
    await api.functional.auth.customer.refresh(connection, {
      body: {
        refresh_token: validRefreshToken,
      } satisfies IShoppingMallCustomer.IRefresh,
    });

  // Validate the response structure and completeness
  typia.assert(refreshResponse);

  // Verify customer profile data is complete and valid
  TestValidator.predicate(
    "customer has valid UUID ID",
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
      refreshResponse.id,
    ),
  );

  TestValidator.predicate(
    "customer email has valid format",
    /^[a-z0-9!#$%&'*+/=?^_`{|}~-]+(?:\.[a-z0-9!#$%&'*+/=?^_`{|}~-]+)*@(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$/i.test(
      refreshResponse.email,
    ),
  );

  TestValidator.predicate(
    "customer name is not empty",
    refreshResponse.name.length > 0,
  );

  TestValidator.predicate(
    "customer name has reasonable length",
    refreshResponse.name.length >= 1 && refreshResponse.name.length <= 255,
  );

  // Validate customer status and verification fields
  TestValidator.equals("customer account status", refreshResponse.status, true);

  TestValidator.predicate(
    "email verification status is boolean",
    typeof refreshResponse.is_email_verified === "boolean",
  );

  TestValidator.predicate(
    "phone verification status is boolean",
    typeof refreshResponse.is_phone_verified === "boolean",
  );

  TestValidator.predicate(
    "marketing opt-in is boolean",
    typeof refreshResponse.marketing_opt_in === "boolean",
  );

  // Validate account type is one of the allowed values
  TestValidator.predicate(
    "account type is valid",
    ["standard", "premium", "vip"].includes(refreshResponse.account_type),
  );

  TestValidator.predicate(
    "language code has reasonable length",
    refreshResponse.language.length >= 2 &&
      refreshResponse.language.length <= 10,
  );

  TestValidator.predicate(
    "timezone has reasonable length",
    refreshResponse.timezone.length >= 3 &&
      refreshResponse.timezone.length <= 50,
  );

  // Validate token structure and content
  TestValidator.predicate(
    "access token is present and not empty",
    refreshResponse.token.access.length > 0,
  );

  TestValidator.predicate(
    "refresh token is present and not empty",
    refreshResponse.token.refresh.length > 0,
  );

  TestValidator.predicate(
    "access token has valid expiration timestamp format",
    /^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])(T|\s)([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9](?:\.[0-9]{1,9})?(Z|[+-]([01][0-9]|2[0-3]):[0-5][0-9])$/i.test(
      refreshResponse.token.expired_at,
    ),
  );

  TestValidator.predicate(
    "refresh token has valid expiration timestamp format",
    /^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])(T|\s)([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9](?:\.[0-9]{1,9})?(Z|[+-]([01][0-9]|2[0-3]):[0-5][0-9])$/i.test(
      refreshResponse.token.refreshable_until,
    ),
  );

  // Verify token expiration timestamps are in the future
  const currentTime = new Date();
  const accessTokenExpiry = new Date(refreshResponse.token.expired_at);
  const refreshTokenExpiry = new Date(refreshResponse.token.refreshable_until);

  TestValidator.predicate(
    "access token expires in the future",
    accessTokenExpiry > currentTime,
  );

  TestValidator.predicate(
    "refresh token expires in the future",
    refreshTokenExpiry > currentTime,
  );

  // Verify timestamp fields have valid formats
  TestValidator.predicate(
    "created_at has valid timestamp format",
    /^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])(T|\s)([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9](?:\.[0-9]{1,9})?(Z|[+-]([01][0-9]|2[0-3]):[0-5][0-9])$/i.test(
      refreshResponse.created_at,
    ),
  );

  TestValidator.predicate(
    "updated_at has valid timestamp format",
    /^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])(T|\s)([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9](?:\.[0-9]{1,9})?(Z|[+-]([01][0-9]|2[0-3]):[0-5][0-9])$/i.test(
      refreshResponse.updated_at,
    ),
  );

  // Test optional avatar field if present
  if (refreshResponse.avatar !== null && refreshResponse.avatar !== undefined) {
    TestValidator.predicate(
      "avatar has valid URI format",
      /^https?:\/\/.+/.test(refreshResponse.avatar),
    );
  }

  // Test optional birth_date field if present
  if (
    refreshResponse.birth_date !== null &&
    refreshResponse.birth_date !== undefined
  ) {
    TestValidator.predicate(
      "birth_date has valid date format",
      /^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$/.test(
        refreshResponse.birth_date,
      ),
    );
  }

  // Test optional gender field if present
  if (refreshResponse.gender !== null && refreshResponse.gender !== undefined) {
    TestValidator.predicate(
      "gender has valid value",
      ["male", "female", "other", "prefer_not_to_say"].includes(
        refreshResponse.gender,
      ),
    );
  }

  // Verify authorization header was updated by the SDK
  TestValidator.notEquals(
    "connection headers were updated with new access token",
    connection.headers?.Authorization,
    originalHeaders.Authorization,
  );

  TestValidator.predicate(
    "new authorization header contains access token",
    connection.headers?.Authorization === refreshResponse.token.access,
  );

  // Test sequential refresh operations to ensure session continuity
  const secondRefreshToken = refreshResponse.token.refresh;
  const secondRefreshTime = new Date();

  const secondRefreshResponse: IShoppingMallCustomer.IAuthorized =
    await api.functional.auth.customer.refresh(connection, {
      body: {
        refresh_token: secondRefreshToken,
      } satisfies IShoppingMallCustomer.IRefresh,
    });

  typia.assert(secondRefreshResponse);

  // Verify customer data consistency across refreshes
  TestValidator.equals(
    "customer ID remains consistent across refreshes",
    secondRefreshResponse.id,
    refreshResponse.id,
  );

  TestValidator.equals(
    "customer email remains consistent across refreshes",
    secondRefreshResponse.email,
    refreshResponse.email,
  );

  TestValidator.equals(
    "customer name remains consistent across refreshes",
    secondRefreshResponse.name,
    refreshResponse.name,
  );

  // Verify new tokens are different (token rotation working)
  TestValidator.notEquals(
    "new access token is different from previous",
    secondRefreshResponse.token.access,
    refreshResponse.token.access,
  );

  TestValidator.notEquals(
    "new refresh token is different from previous",
    secondRefreshResponse.token.refresh,
    refreshResponse.token.refresh,
  );

  // Verify authorization header was updated again
  TestValidator.notEquals(
    "connection headers updated with second refresh",
    connection.headers?.Authorization,
    refreshResponse.token.access,
  );

  TestValidator.equals(
    "second refresh updates authorization header correctly",
    connection.headers?.Authorization,
    secondRefreshResponse.token.access,
  );

  // Verify new expiration times are updated and still in the future
  const newAccessExpiry = new Date(secondRefreshResponse.token.expired_at);
  const newRefreshExpiry = new Date(
    secondRefreshResponse.token.refreshable_until,
  );

  TestValidator.predicate(
    "new access token expires in the future",
    newAccessExpiry > secondRefreshTime,
  );

  TestValidator.predicate(
    "new refresh token expires in the future",
    newRefreshExpiry > secondRefreshTime,
  );

  TestValidator.predicate(
    "new access token has later expiration than previous",
    newAccessExpiry > accessTokenExpiry,
  );

  TestValidator.predicate(
    "new refresh token has later expiration than previous",
    newRefreshExpiry > refreshTokenExpiry,
  );

  // Test with invalid refresh token to ensure proper error handling
  await TestValidator.error(
    "refresh with invalid token should fail",
    async () => {
      await api.functional.auth.customer.refresh(connection, {
        body: {
          refresh_token: "invalid_refresh_token_12345",
        } satisfies IShoppingMallCustomer.IRefresh,
      });
    },
  );

  // Test with empty refresh token
  await TestValidator.error(
    "refresh with empty token should fail",
    async () => {
      await api.functional.auth.customer.refresh(connection, {
        body: {
          refresh_token: "",
        } satisfies IShoppingMallCustomer.IRefresh,
      });
    },
  );

  // Final validation: verify all required customer fields are present
  TestValidator.predicate(
    "all required customer profile fields are present",
    refreshResponse.id !== undefined &&
      refreshResponse.email !== undefined &&
      refreshResponse.name !== undefined &&
      refreshResponse.status !== undefined &&
      refreshResponse.is_email_verified !== undefined &&
      refreshResponse.is_phone_verified !== undefined &&
      refreshResponse.account_type !== undefined &&
      refreshResponse.language !== undefined &&
      refreshResponse.timezone !== undefined &&
      refreshResponse.marketing_opt_in !== undefined &&
      refreshResponse.created_at !== undefined &&
      refreshResponse.updated_at !== undefined &&
      refreshResponse.token !== undefined,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallProductVariant";
import type { IShoppingMallInventoryStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallInventoryStatus";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductCategory";
import type { IShoppingMallProductImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductImage";
import type { IShoppingMallProductReviewStatistics } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductReviewStatistics";
import type { IShoppingMallProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductVariant";
import type { IShoppingMallProductVariantSortField } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductVariantSortField";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import type { ISortOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/ISortOrder";

/**
 * Test advanced inventory-based filtering for product variants.
 *
 * This test validates that sellers can efficiently filter and monitor their
 * product variants based on inventory levels. It covers filtering by
 * minimum/maximum quantities, active status, sorting by inventory quantity, and
 * identifying variants requiring restocking.
 *
 * The test follows this comprehensive workflow:
 *
 * 1. Seller registration with business credentials
 * 2. Create a parent product in the marketplace
 * 3. Generate multiple product variants with diverse inventory levels (0, low,
 *    medium, high)
 * 4. Test inventory filtering capabilities with various scenarios
 * 5. Validate sorting functionality for efficient restocking decisions
 * 6. Test pagination for performance optimization with large variant catalogs
 *
 * This ensures sellers can optimize inventory management decisions through the
 * platform's advanced filtering capabilities.
 */
export async function test_api_product_variant_inventory_performance_filtering(
  connection: api.IConnection,
) {
  // Step 1: Create a seller account with proper business credentials
  const sellerRequest = {
    email: typia.random<string & tags.Format<"email">>(),
    business_name: RandomGenerator.name(2),
    business_registration_number: RandomGenerator.alphaNumeric(10),
    tax_id: RandomGenerator.alphaNumeric(9),
    phone: RandomGenerator.mobile("010"),
    business_type: RandomGenerator.pick([
      "Sole Proprietorship",
      "Corporation",
      "LLC",
      "Partnership",
    ] as const),
  } satisfies IShoppingMallSeller.IJoin;

  const seller = await api.functional.auth.seller.join(connection, {
    body: sellerRequest,
  });
  typia.assert(seller);
  TestValidator.equals(
    "seller has verification status",
    seller.verification_status,
    "pending",
  );

  // Step 2: Create a parent product with comprehensive details
  const productData = {
    sku: `PROD-${RandomGenerator.alphaNumeric(8)}`,
    name: `Smart Electronics ${RandomGenerator.name()}`,
    description: RandomGenerator.content({
      paragraphs: 2,
      sentenceMin: 5,
      sentenceMax: 10,
    }),
    price: typia.random<
      number & tags.Type<"uint32"> & tags.Minimum<50> & tags.Maximum<2000>
    >(),
    condition: "new",
    weight: typia.random<
      number & tags.Type<"uint32"> & tags.Minimum<100> & tags.Maximum<2000>
    >(),
    weight_unit: "g",
    track_quantity: true,
    allow_backorder: false,
    is_shipping_required: true,
    is_taxable: true,
    seo_title: RandomGenerator.paragraph({ sentences: 3 }),
    seo_description: RandomGenerator.paragraph({ sentences: 5 }),
    tags: "electronics,smart,trendy",
    featured_image: typia.random<string & tags.Format<"uri">>(),
    category_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_seller_id: seller.id,
    href: "https://example.com/dashboard/products/create",
    referrer: "https://example.com/dashboard",
  } satisfies IShoppingMallProduct.ICreate;

  const product = await api.functional.shoppingMall.seller.products.create(
    connection,
    {
      body: productData,
    },
  );
  typia.assert(product);
  TestValidator.equals(
    "product has multiple variants setup",
    product.variants_count,
    0,
  );

  // Helper function for clean SKU generation
  const createVariantSku = (baseSku: string, variantTitle: string): string => {
    const cleanTitle = variantTitle
      .toLowerCase()
      .replace(/\s+memory\s*/g, "")
      .replace(/\s+/g, "-")
      .replace(/[^a-z0-9-]/g, "");
    return `${baseSku}-${cleanTitle}`;
  };

  // Step 3: Create product variants with diverse inventory levels
  const variantConfigs = [
    { title: "Red, Memory: 64GB", inventory: 0, priceAdj: 0, active: false },
    { title: "Red, Memory: 128GB", inventory: 2, priceAdj: 50, active: true },
    { title: "Red, Memory: 256GB", inventory: 15, priceAdj: 100, active: true },
    { title: "Blue, Memory: 64GB", inventory: 50, priceAdj: 0, active: true },
    {
      title: "Blue, Memory: 128GB",
      inventory: 100,
      priceAdj: 50,
      active: true,
    },
    {
      title: "Blue, Memory: 256GB",
      inventory: 200,
      priceAdj: 100,
      active: true,
    },
    { title: "Green, Memory: 64GB", inventory: 1, priceAdj: 0, active: true },
    {
      title: "Green, Memory: 128GB",
      inventory: 8,
      priceAdj: 50,
      active: false,
    },
  ];

  const createdVariants: IShoppingMallProductVariant[] = [];

  for (const [index, config] of variantConfigs.entries()) {
    const variantData = {
      shopping_mall_product_id: product.id,
      shopping_mall_product_unit_id: typia.random<
        string & tags.Format<"uuid">
      >(),
      sku: createVariantSku(product.sku, config.title),
      title: config.title,
      price_adjustment: config.priceAdj,
      inventory_quantity: config.inventory,
      cost_adjustment: null,
      weight_adjustment: null,
      barcode: null,
      image: null,
      inventory_policy: "deny",
      position: index,
      is_active: config.active,
    } satisfies IShoppingMallProductVariant.ICreate;

    const variant =
      await api.functional.shoppingMall.seller.products.variants.create(
        connection,
        {
          productCode: product.sku,
          body: variantData,
        },
      );
    createdVariants.push(variant);
    typia.assert(variant);
  }

  // Step 4: Test basic retrieval without filters
  const basicFilterRequest = {
    page: 1,
    limit: 50,
  } satisfies IShoppingMallProductVariant.IRequest;

  const basicResults =
    await api.functional.shoppingMall.products.variants.index(connection, {
      productCode: product.sku,
      body: basicFilterRequest,
    });
  typia.assert(basicResults);
  TestValidator.predicate(
    "basic filter returns variants",
    basicResults.data.length > 0,
  );
  TestValidator.predicate(
    "pagination info is complete",
    basicResults.pagination !== undefined,
  );

  // Step 5: Test min inventory filtering for restocking alerts
  const minInventoryFilter = {
    page: 1,
    limit: 50,
    min_inventory_quantity: 5,
    sort_by: "inventory_quantity" as IShoppingMallProductVariantSortField,
    sort_order: "asc" as ISortOrder,
  } satisfies IShoppingMallProductVariant.IRequest;

  const minInventoryResults =
    await api.functional.shoppingMall.products.variants.index(connection, {
      productCode: product.sku,
      body: minInventoryFilter,
    });
  typia.assert(minInventoryResults);

  TestValidator.predicate(
    "min inventory filter returns low stock variants",
