        "image display order is positive",
        image.display_order > 0,
      );
      TestValidator.predicate(
        "image primary status is boolean",
        typeof image.is_primary === "boolean",
      );
      TestValidator.predicate(
        "image has creation timestamp",
        image.created_at.length > 0,
      );
    });
