      typia.is<string & tags.Format<"date-time">>(product.published_at),
    );
  }
  if (product.deleted_at) {
    TestValidator.predicate(
      "deleted_at has valid format",
      typia.is<string & tags.Format<"date-time">>(product.deleted_at),
