    await api.functional.shoppingMall.seller.products.units.create(connection, {
      productCode: product.sku,
      body: {
        name: "Size",
        type: "size",
        display_style: "dropdown",
        is_required: true,
        is_multiple: false,
        sort_order: 1,
      } satisfies IShoppingMallProductUnit.ICreate,
    });
  typia.assert(sizeUnit);

  const colorUnit =
    await api.functional.shoppingMall.seller.products.units.create(connection, {
      productCode: product.sku,
      body: {
        name: "Color",
        type: "color",
        display_style: "swatches",
        is_required: true,
        is_multiple: false,
        sort_order: 2,
      } satisfies IShoppingMallProductUnit.ICreate,
    });
  typia.assert(colorUnit);

  const materialUnit =
    await api.functional.shoppingMall.seller.products.units.create(connection, {
      productCode: product.sku,
      body: {
        name: "Material",
        type: "material",
        display_style: "buttons",
        is_required: false,
        is_multiple: false,
        sort_order: 3,
      } satisfies IShoppingMallProductUnit.ICreate,
    });
  typia.assert(materialUnit);

  // Step 4: Create multiple variants with different positions for merchandising testing
  const classicVariant =
    await api.functional.shoppingMall.seller.products.variants.create(
      connection,
      {
        productCode: product.sku,
        body: {
          shopping_mall_product_id: product.id,
          shopping_mall_product_unit_id: sizeUnit.id,
          sku: `${product.sku}-CLASSIC`,
          title: "Classic Size, Standard Color",
          price_adjustment: 0,
          inventory_quantity: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<10> & tags.Maximum<100>
          >(),
          inventory_policy: "deny",
          position: 1,
          is_active: true,
        } satisfies IShoppingMallProductVariant.ICreate,
      },
    );
  typia.assert(classicVariant);

  const premiumVariant =
    await api.functional.shoppingMall.seller.products.variants.create(
      connection,
      {
        productCode: product.sku,
        body: {
          shopping_mall_product_id: product.id,
          shopping_mall_product_unit_id: colorUnit.id,
          sku: `${product.sku}-PREMIUM`,
          title: "Premium Color, Limited Edition",
          price_adjustment: typia.random<
            number & tags.Minimum<25> & tags.Maximum<150>
          >(),
          inventory_quantity: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<5> & tags.Maximum<50>
          >(),
          cost_adjustment: typia.random<
            number & tags.Minimum<15> & tags.Maximum<80>
          >(),
          inventory_policy: "continue",
          position: 2,
          is_active: true,
        } satisfies IShoppingMallProductVariant.ICreate,
      },
    );
  typia.assert(premiumVariant);

  const budgetVariant =
    await api.functional.shoppingMall.seller.products.variants.create(
      connection,
      {
        productCode: product.sku,
        body: {
          shopping_mall_product_id: product.id,
          shopping_mall_product_unit_id: materialUnit.id,
          sku: `${product.sku}-BUDGET`,
          title: "Budget Material, Basic Option",
          price_adjustment: typia.random<
            number & tags.Minimum<10> & tags.Maximum<0>
          >(),
          inventory_quantity: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<20> & tags.Maximum<200>
          >(),
          inventory_policy: "deny",
          position: 3,
          is_active: true,
        } satisfies IShoppingMallProductVariant.ICreate,
      },
    );
  typia.assert(budgetVariant);

  const luxuryVariant =
    await api.functional.shoppingMall.seller.products.variants.create(
      connection,
      {
        productCode: product.sku,
        body: {
          shopping_mall_product_id: product.id,
          shopping_mall_product_unit_id: sizeUnit.id,
          sku: `${product.sku}-LUXURY`,
          title: "Luxury Size, Premium Material",
          price_adjustment: typia.random<
            number & tags.Minimum<75> & tags.Maximum<300>
          >(),
          inventory_quantity: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<2> & tags.Maximum<25>
          >(),
          weight_adjustment: typia.random<
            number & tags.Minimum<0.1> & tags.Maximum<2>
          >(),
          inventory_policy: "deny",
          position: 4,
          is_active: true,
        } satisfies IShoppingMallProductVariant.ICreate,
      },
    );
  typia.assert(luxuryVariant);

  // Step 5: Test strategic variant position optimization for merchandising
  // Optimize positions: Premium (most profitable) at position 0, Luxury at 1, Classic at 2, Budget at 3
  const optimizedPremiumVariant =
    await api.functional.shoppingMall.seller.products.variants.update(
      connection,
      {
        productCode: product.sku,
        variantCode: premiumVariant.sku,
        body: {
          position: 0, // Move premium variant to top position for maximum visibility
          price_adjustment: premiumVariant.price_adjustment + 10, // Slight price increase for high-position variant
        } satisfies IShoppingMallProductVariant.IUpdate,
      },
    );
  typia.assert(optimizedPremiumVariant);
  TestValidator.equals(
    "premium variant position optimized",
    optimizedPremiumVariant.position,
    0,
  );

  const optimizedLuxuryVariant =
    await api.functional.shoppingMall.seller.products.variants.update(
      connection,
      {
        productCode: product.sku,
        variantCode: luxuryVariant.sku,
        body: {
          position: 1, // Luxury variant at second position
          price_adjustment: luxuryVariant.price_adjustment + 5, // Small premium for strategic positioning
        } satisfies IShoppingMallProductVariant.IUpdate,
      },
    );
  typia.assert(optimizedLuxuryVariant);
  TestValidator.equals(
    "luxury variant position optimized",
    optimizedLuxuryVariant.position,
    1,
  );

  const optimizedClassicVariant =
    await api.functional.shoppingMall.seller.products.variants.update(
      connection,
      {
        productCode: product.sku,
        variantCode: classicVariant.sku,
        body: {
          position: 2, // Classic variant moves to third position
        } satisfies IShoppingMallProductVariant.IUpdate,
      },
    );
  typia.assert(optimizedClassicVariant);
  TestValidator.equals(
    "classic variant position optimized",
    optimizedClassicVariant.position,
    2,
  );

  const optimizedBudgetVariant =
    await api.functional.shoppingMall.seller.products.variants.update(
      connection,
      {
        productCode: product.sku,
        variantCode: budgetVariant.sku,
        body: {
          position: 3, // Budget variant at bottom for conversion optimization
          is_active: true, // Keep active but in lower priority position
        } satisfies IShoppingMallProductVariant.IUpdate,
      },
    );
  typia.assert(optimizedBudgetVariant);
  TestValidator.equals(
    "budget variant position optimized",
    optimizedBudgetVariant.position,
    3,
  );

  // Step 6: Test promotional campaign support through position manipulation
  // Create new promotional variant and position it strategically
  const promotionalVariant =
    await api.functional.shoppingMall.seller.products.variants.create(
      connection,
      {
        productCode: product.sku,
        body: {
          shopping_mall_product_id: product.id,
          shopping_mall_product_unit_id: colorUnit.id,
          sku: `${product.sku}-PROMO`,
          title: "Special Promotion - Limited Time",
          price_adjustment: typia.random<
            number & tags.Minimum<20> & tags.Maximum<100>
          >(),
          inventory_quantity: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<15> & tags.Maximum<75>
          >(),
          inventory_policy: "deny",
          position: 5, // Initially create at bottom position
          is_active: true,
        } satisfies IShoppingMallProductVariant.ICreate,
      },
    );
  typia.assert(promotionalVariant);

  // Promote the variant to top position for campaign visibility
  const promotedVariant =
    await api.functional.shoppingMall.seller.products.variants.update(
      connection,
      {
        productCode: product.sku,
        variantCode: promotionalVariant.sku,
        body: {
          position: 0, // Promote to top position for maximum campaign visibility
          is_active: true,
        } satisfies IShoppingMallProductVariant.IUpdate,
      },
    );
  typia.assert(promotedVariant);
  TestValidator.equals(
    "promotional variant positioned for maximum visibility",
    promotedVariant.position,
    0,
  );

  // Step 7: Validate conversion rate optimization through display manipulation
  // Test inventory-based position optimization
  const lowInventoryVariant =
    await api.functional.shoppingMall.seller.products.variants.create(
      connection,
      {
        productCode: product.sku,
        body: {
          shopping_mall_product_id: product.id,
          shopping_mall_product_unit_id: sizeUnit.id,
          sku: `${product.sku}-LOWSTOCK`,
          title: "Limited Stock - Act Fast",
          price_adjustment: typia.random<
            number & tags.Minimum<30> & tags.Maximum<120>
          >(),
          inventory_quantity: 3, // Very low inventory to create urgency
          inventory_policy: "deny",
          position: 6,
          is_active: true,
        } satisfies IShoppingMallProductVariant.ICreate,
      },
    );
  typia.assert(lowInventoryVariant);

  // Position low inventory variant strategically to drive urgency
  const urgencyPositionedVariant =
    await api.functional.shoppingMall.seller.products.variants.update(
      connection,
      {
        productCode: product.sku,
        variantCode: lowInventoryVariant.sku,
        body: {
          position: 1, // Second position for high visibility with urgency messaging
        } satisfies IShoppingMallProductVariant.IUpdate,
      },
    );
  typia.assert(urgencyPositionedVariant);
  TestValidator.equals(
    "low inventory variant positioned for urgency",
    urgencyPositionedVariant.position,
    1,
  );

  // Step 8: Test comprehensive merchandising validation
  // Verify all variants maintain correct positioning after multiple updates
  const variants = [
    promotedVariant,
    urgencyPositionedVariant,
    optimizedLuxuryVariant,
    optimizedClassicVariant,
    optimizedBudgetVariant,
    optimizedPremiumVariant,
  ];

  // Sort variants by position to validate merchandising order
  const sortedVariants = variants.sort((a, b) => a.position - b.position);

  TestValidator.predicate(
    "promotional variant has highest merchandising priority",
    sortedVariants[0].sku.includes("PROMO"),
  );
  TestValidator.predicate(
    "urgency variant has second merchandising priority",
    sortedVariants[1].sku.includes("LOWSTOCK"),
  );
  TestValidator.predicate(
    "luxury variant maintains strategic position",
    sortedVariants[2].sku.includes("LUXURY"),
  );
  TestValidator.predicate(
    "classic variant in middle merchandising position",
    sortedVariants[3].sku.includes("CLASSIC"),
  );
  TestValidator.predicate(
    "budget variant in lower merchandising position",
    sortedVariants[4].sku.includes("BUDGET"),
  );
  TestValidator.predicate(
    "premium variant repositioned for profitability",
    sortedVariants[5].sku.includes("PREMIUM"),
  );

  // Validate price optimization through positioning
  TestValidator.predicate(
    "promotional variant has competitive pricing",
    promotedVariant.price_adjustment > 0,
  );
  TestValidator.predicate(
    "luxury variant maintains premium pricing",
    optimizedLuxuryVariant.price_adjustment >
      optimizedClassicVariant.price_adjustment,
  );
  TestValidator.predicate(
    "budget variant offers value pricing",
    optimizedBudgetVariant.price_adjustment <
      optimizedClassicVariant.price_adjustment,
  );

  // Test conversion optimization elements
  TestValidator.predicate(
    "low inventory variant creates urgency messaging",
    lowInventoryVariant.inventory_quantity <= 5,
  );
  TestValidator.predicate(
    "promotional variant uses compelling title",
    promotedVariant.title.toLowerCase().includes("special") ||
      promotedVariant.title.toLowerCase().includes("promotion"),
  );
  TestValidator.predicate(
    "luxury variant positioned for premium appeal",
    optimizedLuxuryVariant.position <= 3,
  );
  TestValidator.predicate(
    "budget variant positioned for value shoppers",
    optimizedBudgetVariant.position >= 3,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductCategory";

/**
 * Test visual merchandising updates including category images, featured status,
 * and sort order modifications. Validates visual asset management and
 * promotional display configurations. Ensures that visual updates maintain
 * proper image formats and display consistency across the platform.
 */
export async function test_api_admin_category_visual_merchandising(
  connection: api.IConnection,
) {
  // Step 1: Create admin account for authentication
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      firstname: RandomGenerator.name(1),
      lastname: RandomGenerator.name(1),
      adminlevel: "department_admin",
    } satisfies IShoppingMallAdmin.ICreate,
  });

  // Step 2: Create multiple product categories for visual merchandising testing
  const categoryCode1 = RandomGenerator.alphaNumeric(8);
  const category1 = await api.functional.shoppingMall.admin.categories.create(
    connection,
    {
      body: {
        code: categoryCode1,
        name: `Featured Electronics ${RandomGenerator.name()}`,
        description: RandomGenerator.paragraph({
          sentences: 10,
          wordMin: 4,
          wordMax: 8,
        }),
      } satisfies IShoppingMallProductCategory.ICreate,
    },
  );

  const categoryCode2 = RandomGenerator.alphaNumeric(8);
  const category2 = await api.functional.shoppingMall.admin.categories.create(
    connection,
    {
      body: {
        code: categoryCode2,
        name: `Regular Category ${RandomGenerator.name()}`,
        description: RandomGenerator.paragraph({
          sentences: 8,
          wordMin: 4,
          wordMax: 8,
        }),
      } satisfies IShoppingMallProductCategory.ICreate,
    },
  );

  // Step 3: Update first category with visual merchandising configurations - promotional focus
  const merchandisedCategory1 =
    await api.functional.shoppingMall.admin.categories.update(connection, {
      categoryCode: category1.code,
      body: {
        name: `🌟 Featured ${category1.name}`,
        description: `Premium merchandising category - ${category1.description} - Perfect for promotional displays and homepage features`,
      } satisfies IShoppingMallProductCategory.IUpdate,
    });

  // Step 4: Update second category with enhanced merchandising content
  const merchandisedCategory2 =
    await api.functional.shoppingMall.admin.categories.update(connection, {
      categoryCode: category2.code,
      body: {
        name: `Best Sellers ${category2.name}`,
        description: `Customer favorite products - ${category2.description} - Ideal for cross-selling and bundling strategies`,
      } satisfies IShoppingMallProductCategory.IUpdate,
    });

  // Validate visual merchandising updates
  TestValidator.equals(
    "first category id remains consistent",
    merchandisedCategory1.id,
    category1.id,
  );
  TestValidator.equals(
    "second category id remains consistent",
    merchandisedCategory2.id,
    category2.id,
  );

  TestValidator.predicate(
    "promotional emoji added to merchandised category name",
    merchandisedCategory1.name.includes("🌟"),
  );
  TestValidator.predicate(
    "merchandised category name includes promotional terms",
    merchandisedCategory1.name.includes("Featured"),
  );
  TestValidator.predicate(
    "second category includes merchandising terminology",
    merchandisedCategory2.name.includes("Best Sellers"),
  );

  TestValidator.predicate(
    "merchandised category description enhanced with promotional context",
    merchandisedCategory1.description?.includes("Premium merchandising") ??
      false,
  );
  TestValidator.predicate(
    "merchandised category description includes marketing terms",
    merchandisedCategory1.description?.includes(
      "Perfect for promotional displays",
    ) ?? false,
  );
  TestValidator.predicate(
    "second category includes merchandising strategy terms",
    merchandisedCategory2.description?.includes("cross-selling and bundling") ??
      false,
  );

  // Validate platform merchandising consistency
  TestValidator.predicate(
    "both categories maintain active status for display",
    merchandisedCategory1.is_active && merchandisedCategory2.is_active,
  );
  TestValidator.predicate(
    "featured status preserved for merchandising control",
    merchandisedCategory1.is_featured === false &&
      merchandisedCategory2.is_featured === false,
  );
  TestValidator.predicate(
    "sort order maintained within merchandising bounds",
    merchandisedCategory1.sort_order >= 0 &&
      merchandisedCategory1.sort_order <= 9999 &&
      merchandisedCategory2.sort_order >= 0 &&
      merchandisedCategory2.sort_order <= 9999,
  );

  // Validate hierarchical integrity for merchandising structure
  TestValidator.predicate(
    "category level maintained for merchandising hierarchy",
    merchandisedCategory1.level >= 0 &&
      merchandisedCategory1.level <= 10 &&
      merchandisedCategory2.level >= 0 &&
      merchandisedCategory2.level <= 10,
  );

  // Validate timestamp consistency for audit trails
  TestValidator.predicate(
    "updated_at reflects merchandising modifications",
    merchandisedCategory1.updated_at > category1.updated_at &&
      merchandisedCategory2.updated_at > category2.updated_at,
  );

  // Validate merchandising-specific validation
  TestValidator.predicate(
    "category codes maintained for merchandising identity",
    merchandisedCategory1.code === categoryCode1 &&
      merchandisedCategory2.code === categoryCode2,
  );

  TestValidator.predicate(
    "category paths maintained for merchandising organization",
    merchandisedCategory1.path.length > 0 &&
      merchandisedCategory2.path.length > 0,
  );

  // Validate image URL handling capability (null/missing image handling)
  TestValidator.predicate(
    "image field properly handles null for visual assets",
    merchandisedCategory1.image === undefined ||
      merchandisedCategory1.image === null,
  );

  // Validate SEO metadata readiness for merchandising
  TestValidator.predicate(
    "SEO metadata fields available for merchandising optimization",
    merchandisedCategory1.meta_title === undefined ||
      (merchandisedCategory1.meta_title !== null &&
        merchandisedCategory1.meta_title.length <= 60),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallInventoryLevels } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallInventoryLevels";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallInventoryLevels } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallInventoryLevels";
import type { IShoppingMallInventoryStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallInventoryStatus";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductCategory";
import type { IShoppingMallProductImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductImage";
import type { IShoppingMallProductReviewStatistics } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductReviewStatistics";
import type { IShoppingMallProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductVariant";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import type { IShoppingMallWarehouse } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallWarehouse";

/**
 * Test warehouse-specific inventory monitoring with geographic filtering and
 * multi-location distribution analysis.
 *
 * Validates inventory tracking across warehouse facilities with location-based
 * filtering, warehouse code identification, and capacity planning. Tests
 * warehouse stock assessment including current stock, reserved quantities,
 * allocated stock, and reorder point analysis.
 */
export async function test_api_admin_inventory_monitoring_warehouse_analysis(
  connection: api.IConnection,
) {
  // Monitor comprehensive inventory levels across warehouse network
  const comprehensiveMonitor =
    await api.functional.shoppingMall.admin.inventoryLevels.index(connection, {
      body: {
        include_out_of_stock: "true",
        sort_by: "current_stock",
        page: 0,
        limit: 50,
        alert_status_filter: "all",
        sort_direction: "asc",
      } satisfies IShoppingMallInventoryLevels.IRequest,
    });

  TestValidator.equals(
    "comprehensive monitoring returns data",
    comprehensiveMonitor.data.length >= 0,
    true,
  );
  TestValidator.predicate(
    "monitoring includes pagination info",
    comprehensiveMonitor.pagination.records >= 0,
  );

  // Test geographic filtering for New York region
  const nyRegionMonitor =
    await api.functional.shoppingMall.admin.inventoryLevels.index(connection, {
      body: {
        include_out_of_stock: "true",
        sort_by: "warehouse_name",
        page: 0,
        limit: 15,
        alert_status_filter: "normal",
        sort_direction: "asc",
        search_text: "New York",
        warehouse_codes: ["WH-NYC-001"],
      } satisfies IShoppingMallInventoryLevels.IRequest,
    });

  TestValidator.predicate(
    "geographic filtering works",
    nyRegionMonitor.data.length >= 0,
  );
  TestValidator.predicate(
    "warehouse code filtering active",
    nyRegionMonitor.data.length <= 15,
  );

  // Monitor low-stock inventory levels for reorder analysis
  const lowStockMonitor =
    await api.functional.shoppingMall.admin.inventoryLevels.index(connection, {
      body: {
        include_out_of_stock: "true",
        sort_by: "current_stock",
        page: 0,
        limit: 20,
        alert_status_filter: "low_stock",
        sort_direction: "asc",
        low_stock_threshold: 25,
      } satisfies IShoppingMallInventoryLevels.IRequest,
    });

  TestValidator.predicate(
    "low stock monitoring active",
    lowStockMonitor.data.length >= 0,
  );
  TestValidator.predicate(
    "query size respects limit",
    lowStockMonitor.data.length <= 20,
  );

  // Test multi-warehouse distribution analysis
  const multiWarehouseAnalysis =
    await api.functional.shoppingMall.admin.inventoryLevels.index(connection, {
      body: {
        include_out_of_stock: "false",
        sort_by: "warehouse_name",
        page: 0,
        limit: 30,
        alert_status_filter: "normal",
        sort_direction: "asc",
        warehouse_codes: ["WH-NYC-001", "WH-LA-002", "WH-CHI-003"],
      } satisfies IShoppingMallInventoryLevels.IRequest,
    });

  TestValidator.predicate(
    "multi-warehouse analysis works",
    multiWarehouseAnalysis.data.length >= 0,
  );
  TestValidator.predicate(
    "analysis covers multiple locations",
    multiWarehouseAnalysis.data.length <= 30,
  );

  // Test seller-specific distribution monitoring
  const sellerDistributionMonitor =
    await api.functional.shoppingMall.admin.inventoryLevels.index(connection, {
      body: {
        include_out_of_stock: "true",
        sort_by: "seller_name",
        page: 0,
        limit: 25,
        alert_status_filter: "all",
        sort_direction: "asc",
        search_text: "Merchant",
      } satisfies IShoppingMallInventoryLevels.IRequest,
    });

  TestValidator.predicate(
    "seller inventory monitoring active",
    sellerDistributionMonitor.data.length >= 0,
  );
  TestValidator.predicate(
    "seller search filters relevant data",
    sellerDistributionMonitor.data.length <= 25,
  );

  // Test capacity planning and distribution optimization
  const capacityPlanningMonitor =
    await api.functional.shoppingMall.admin.inventoryLevels.index(connection, {
      body: {
        include_out_of_stock: "false",
        sort_by: "reorder_point",
        page: 0,
        limit: 10,
        alert_status_filter: "normal",
        sort_direction: "asc",
        include_aggregated_counts: "true",
      } satisfies IShoppingMallInventoryLevels.IRequest,
    });

  TestValidator.predicate(
    "capacity planning monitoring works",
    capacityPlanningMonitor.data.length >= 0,
  );
  TestValidator.predicate(
    "reorder point analysis prioritizes needs",
    capacityPlanningMonitor.data.length <= 10,
  );

  // TEST FILTERING BY PRODUCT CATEGORIES AND SKU
  const categorySkuFilteredMonitor =
    await api.functional.shoppingMall.admin.inventoryLevels.index(connection, {
      body: {
        include_out_of_stock: "true",
        search_text: "Standard",
        sort_by: "seller_name",
        page: 0,
        limit: 20,
        alert_status_filter: "normal",
