  const percentageDiscountCodes = JSON.stringify([
    { code: "SAVE10", type: "percentage", value: 10, seller_id: "marketplace" },
    {
      code: "SUMMER20",
      type: "percentage",
      value: 20,
      seller_id: "marketplace",
    },
  ]);

  const percentageCart = await api.functional.shoppingMall.carts.create(
    connection,
    {
      body: {
        promotional_codes: percentageDiscountCodes,
      } satisfies IShoppingMallCart.ICreate,
    },
  );
  typia.assert(percentageCart);

  TestValidator.predicate(
    "percentage discount cart should have promotional codes",
    percentageCart.promotional_codes !== null &&
      percentageCart.promotional_codes !== undefined,
  );

  // Test cart creation with fixed amount coupon promotional codes
  const fixedAmountCodes = JSON.stringify([
    {
      code: "SAVE5",
      type: "fixed",
      value: 5,
      seller_id: "marketplace",
      expires_at: new Date(Date.now() + 86400000).toISOString(),
