import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCart";

/**
 * Test comprehensive timestamp management in shopping cart creation.
 *
 * Validates automatic generation of accurate timestamps for created_at,
 * updated_at, and last_activity_at fields during cart initialization. Tests
 * proper timezone handling and timestamp format compliance. Ensures that
 * converted_at and deleted_at remain null for new carts while activity tracking
 * is properly initiated. Validates that timestamp precision supports real-time
 * analytics and customer behavior tracking across the shopping mall platform
 * ecosystem effectively.
 */
export async function test_api_cart_creation_timestamp_handling(
  connection: api.IConnection,
) {
  // Test 1: Basic cart creation with timestamp validation
  const basicCartBody = {} satisfies IShoppingMallCart.ICreate;
  const basicCart = await api.functional.shoppingMall.carts.create(connection, {
    body: basicCartBody,
  });
  typia.assert(basicCart);

  // Verify automatic timestamp generation (format already validated by typia.assert)
  TestValidator.predicate(
    "created_at is generated automatically",
    basicCart.created_at !== null && basicCart.created_at !== undefined,
  );

  TestValidator.predicate(
    "updated_at is generated automatically",
    basicCart.updated_at !== null && basicCart.updated_at !== undefined,
  );

  TestValidator.predicate(
    "last_activity_at is generated automatically",
    basicCart.last_activity_at !== null &&
      basicCart.last_activity_at !== undefined,
  );

  // Verify null fields for new carts
  TestValidator.equals("converted_at is null", basicCart.converted_at, null);
  TestValidator.equals("deleted_at is null", basicCart.deleted_at, null);

  // Verify cart initialization state
  TestValidator.equals("status should be active", basicCart.status, "active");
  TestValidator.equals(
    "total_item_count starts at 0",
    basicCart.total_item_count,
    0,
  );
  TestValidator.equals(
    "total_product_count starts at 0",
    basicCart.total_product_count,
    0,
  );
  TestValidator.equals(
    "is_locked_for_checkout starts false",
    basicCart.is_locked_for_checkout,
    false,
  );

  // Test 2: Cart creation with customer preferences
  const preferencesBody = {
    customer_shipping_preference: JSON.stringify({
      carrier: "UPS",
      speed: "standard",
      instructions: "Leave at door",
    }),
    customer_notes: "Please deliver between 9AM-5PM",
  } satisfies IShoppingMallCart.ICreate;

  const preferencesCart = await api.functional.shoppingMall.carts.create(
    connection,
    {
      body: preferencesBody,
    },
  );
  typia.assert(preferencesCart);

  // Verify timestamps are generated for cart with preferences
  TestValidator.predicate(
    "preferences cart has created_at timestamp",
    preferencesCart.created_at !== null &&
      preferencesCart.created_at !== undefined,
  );

  TestValidator.predicate(
    "preferences cart has updated_at timestamp",
    preferencesCart.updated_at !== null &&
      preferencesCart.updated_at !== undefined,
  );

  TestValidator.predicate(
    "preferences cart has last_activity_at timestamp",
    preferencesCart.last_activity_at !== null &&
      preferencesCart.last_activity_at !== undefined,
  );

  // Test 3: Cart creation with promotional codes
  const promoBody = {
    promotional_codes: JSON.stringify([
      { code: "SAVE20", discount: 20, type: "percentage" },
      { code: "FREESHIP", discount: 0, type: "shipping" },
    ]),
  } satisfies IShoppingMallCart.ICreate;

  const promoCart = await api.functional.shoppingMall.carts.create(connection, {
    body: promoBody,
  });
  typia.assert(promoCart);

  // Verify chronological relationships
  const createdTime = new Date(promoCart.created_at).getTime();
  const updatedTime = new Date(promoCart.updated_at).getTime();
  const activityTime = new Date(promoCart.last_activity_at).getTime();

  TestValidator.predicate(
    "timestamps are chronologically consistent",
    createdTime <= updatedTime && updatedTime <= activityTime,
  );

  // Test 4: Multiple cart creation for timezone validation
  const carts = await ArrayUtil.asyncRepeat(3, async (index) => {
    const body = {
      customer_notes: `Test cart ${index + 1}`,
    } satisfies IShoppingMallCart.ICreate;

    return await api.functional.shoppingMall.carts.create(connection, {
      body,
    });
  });

  // Verify all carts have consistent timestamp generation
  carts.forEach((cart, index) => {
    typia.assert(cart);

    TestValidator.predicate(
      `cart ${index + 1} has created_at timestamp`,
      cart.created_at !== null && cart.created_at !== undefined,
    );

    TestValidator.predicate(
      `cart ${index + 1} has updated_at timestamp`,
      cart.updated_at !== null && cart.updated_at !== undefined,
    );

    TestValidator.predicate(
      `cart ${index + 1} has last_activity_at timestamp`,
      cart.last_activity_at !== null && cart.last_activity_at !== undefined,
    );
  });

  // Test 5: Empty cart with all optional fields as null
  const emptyCartBody = {
    customer_shipping_preference: null,
    promotional_codes: null,
    customer_notes: null,
  } satisfies IShoppingMallCart.ICreate;

  const emptyCart = await api.functional.shoppingMall.carts.create(connection, {
    body: emptyCartBody,
  });
  typia.assert(emptyCart);

  // Verify null handling doesn't affect timestamp generation
  TestValidator.predicate(
    "empty cart has created_at timestamp",
    emptyCart.created_at !== null && emptyCart.created_at !== undefined,
  );

  TestValidator.equals(
    "empty cart converted_at is null",
    emptyCart.converted_at,
    null,
  );
  TestValidator.equals(
    "empty cart deleted_at is null",
    emptyCart.deleted_at,
    null,
  );

  // Test 6: Verify cart ID generation
  const uuidCart = await api.functional.shoppingMall.carts.create(connection, {
    body: {},
  });
  typia.assert(uuidCart);

  // Test 7: Real-time analytics support
  const analyticsTest = await api.functional.shoppingMall.carts.create(
    connection,
    {
      body: {
        customer_notes: "Analytics test cart",
      },
    },
  );
  typia.assert(analyticsTest);

  // Verify timestamps are suitable for sorting and filtering (format already validated)
  TestValidator.predicate(
    "all timestamps are different (showing precision)",
    analyticsTest.created_at !== basicCart.created_at &&
      analyticsTest.updated_at !== basicCart.updated_at &&
      analyticsTest.last_activity_at !== basicCart.last_activity_at,
  );

  // Test timestamp consistency across operations
  TestValidator.predicate(
    "timestamps support real-time sorting",
    new Date(analyticsTest.created_at).getTime() >
      new Date(basicCart.created_at).getTime(),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallInventoryStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallInventoryStatus";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductCategory";
import type { IShoppingMallProductImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductImage";
import type { IShoppingMallProductReviewStatistics } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductReviewStatistics";
import type { IShoppingMallProductUnit } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductUnit";
import type { IShoppingMallProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductVariant";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Test comprehensive multi-selection capability toggling for product units in a
 * shopping mall marketplace. This test validates seller ability to dynamically
 * switch unit configurations between single and multiple selection modes,
 * ensuring proper variant generation, inventory validation, and business rule
 * enforcement. The workflow includes seller registration, product catalog setup
 * with dual units (traditional single and special multi-select), variant
 * creation with pricing rules, and complex scenario testing including state
 * transitions, requirement validation, and option management.
 *
 * Detailed test flow:
 *
 * 1. Seller creates verified merchant account with business details
 * 2. Product catalog creation with comprehensive SKU placement strategy
 * 3. Dual unit architecture setup: single (Size) and multi-select units (Feature
 *    Add-ons)
 * 4. Variant pricing layers with adaptive cost structures
 * 5. Enable multi-selection capability with confidence validation
 * 6. State transition testing between required/optional modes
 * 7. Sort order reorganization to optimize customer interface
 * 8. Backward compatibility testing for single selection mode
 * 9. Non-destructive update verification preserving existing variants
 * 10. End-to-end customer selection flow simulation
 */
export async function test_api_seller_product_unit_update_multiple_selection(
  connection: api.IConnection,
) {
  // 1. Seller registration with business credentials
  const sellerCreds = {
    email: typia.random<string & tags.Format<"email">>(),
    business_name: RandomGenerator.name(),
    business_registration_number: RandomGenerator.alphaNumeric(15),
    tax_id: RandomGenerator.alphaNumeric(12),
    phone: RandomGenerator.mobile(),
    business_type: "corporation",
  } satisfies IShoppingMallSeller.IJoin;

  const authenticatedSeller = await api.functional.auth.seller.join(
    connection,
    {
      body: sellerCreds,
    },
  );
  typia.assert(authenticatedSeller);

  // 2. Product creation with dual unit strategy
  const productCode = RandomGenerator.alphaNumeric(12);
  const primaryProduct =
    await api.functional.shoppingMall.seller.products.create(connection, {
      body: {
        sku: productCode,
        name: "Custom Electronics Bundle - Premium Edition",
        description: RandomGenerator.content({
          paragraphs: 3,
          sentenceMin: 8,
          sentenceMax: 15,
        }),
        price: 799.0,
        compare_at_price: 999.99,
        cost: 450.0,
        condition: "new",
        weight: 2.5,
        weight_unit: "kg",
        barcode: "PROD" + RandomGenerator.alphaNumeric(10),
        track_quantity: true,
        allow_backorder: false,
        is_shipping_required: true,
        is_taxable: true,
        seo_title: "Professional Electronics Bundle with Custom Features",
        seo_description:
          "High-performance electronics with customizable configurations and professional-grade specifications",
        tags: "electronics,bundle,premium,custom",
        category_id: typia.random<string & tags.Format<"uuid">>(),
        shopping_mall_seller_id: authenticatedSeller.id,
        href: "https://seller-dashboard.example.com/product/create",
        referrer: "https://seller-dashboard.example.com/",
      } satisfies IShoppingMallProduct.ICreate,
    });
  typia.assert(primaryProduct);

  // 3a. Create traditional single selection unit (Size)
  const sizeUnit =
    await api.functional.shoppingMall.seller.products.units.create(connection, {
      productCode,
      body: {
        name: "Storage Capacity",
        type: "size",
        display_style: "dropdown",
        is_required: true,
        is_multiple: false,
        sort_order: 1,
      } satisfies IShoppingMallProductUnit.ICreate,
    });
  typia.assert(sizeUnit);

  // 3b. Create multi-select unit (Feature Add-ons)
  const featureUnit =
    await api.functional.shoppingMall.seller.products.units.create(connection, {
      productCode,
      body: {
        name: "Additional Features",
        type: "custom",
        display_style: "buttons",
        is_required: false,
        is_multiple: false, // Initially single selection
        sort_order: 2,
      } satisfies IShoppingMallProductUnit.ICreate,
    });
  typia.assert(featureUnit);

  // 4. Test multi-selection enablement with full scenario validation
  const multiSelectEnabledUnit =
    await api.functional.shoppingMall.seller.products.units.update(connection, {
      productCode,
      unitId: featureUnit.id,
      body: {
        is_multiple: true, // Enable multi-selection - CRITICAL BUSINESS CHANGE
        display_style: "buttons",
        sort_order: 1, // Elevate to primary selection option
      } satisfies IShoppingMallProductUnit.IUpdate,
    });
  typia.assert(multiSelectEnabledUnit);

  TestValidator.predicate(
    "multi-selection enabled successfully",
    multiSelectEnabledUnit.is_multiple === true,
  );
  TestValidator.equals(
    "display style preserved",
    multiSelectEnabledUnit.display_style,
    "buttons",
  );
  TestValidator.equals(
    "sort order updated",
    multiSelectEnabledUnit.sort_order,
    1,
  );

  // 5. Test single selection revert for backward compatibility
  const singleSelectRevertedUnit =
    await api.functional.shoppingMall.seller.products.units.update(connection, {
      productCode,
      unitId: featureUnit.id,
      body: {
        is_multiple: false, // Revert to single selection
        is_required: true, // Make required to test state transition
        sort_order: 2, // Return to secondary position
      } satisfies IShoppingMallProductUnit.IUpdate,
    });
  typia.assert(singleSelectRevertedUnit);

  TestValidator.predicate(
    "single selection reverted successfully",
    singleSelectRevertedUnit.is_multiple === false,
  );
  TestValidator.predicate(
    "unit now required",
    singleSelectRevertedUnit.is_required === true,
  );
  TestValidator.equals(
    "sort order restored",
    singleSelectRevertedUnit.sort_order,
    2,
  );

  // 6. Test non-destructive update preserving configuration
  const finalConfigUnit =
    await api.functional.shoppingMall.seller.products.units.update(connection, {
      productCode,
      unitId: featureUnit.id,
      body: {
        name: "Selected Add-ons", // Name change should not affect selection behavior
        display_style: "swatches", // Change display style for better UI
        // Note: is_multiple, is_required, sort_order unchanged to test preservation
      } satisfies IShoppingMallProductUnit.IUpdate,
    });
  typia.assert(finalConfigUnit);

  TestValidator.equals(
    "name updated non-destructively",
    finalConfigUnit.name,
    "Selected Add-ons",
  );
  TestValidator.equals(
    "display style updated",
    finalConfigUnit.display_style,
    "swatches",
  );
  TestValidator.predicate(
    "is_multiple preserved",
    finalConfigUnit.is_multiple === false,
  );
  TestValidator.predicate(
    "is_required preserved",
    finalConfigUnit.is_required === true,
  );
  TestValidator.equals("sort_order preserved", finalConfigUnit.sort_order, 2);

  // 7. Verify configuration combinations work together
  const complexUnitUpdate =
    await api.functional.shoppingMall.seller.products.units.update(connection, {
      productCode,
      unitId: featureUnit.id,
      body: {
        is_multiple: true, // Multi-select
        is_required: false, // Optional selection
        sort_order: 1, // Primary
        display_style: "dropdown", // Change to dropdown
      } satisfies IShoppingMallProductUnit.IUpdate,
    });
  typia.assert(complexUnitUpdate);

  TestValidator.predicate(
    "multi-select with optional configuration works",
    complexUnitUpdate.is_multiple === true &&
      complexUnitUpdate.is_required === false,
  );
  TestValidator.equals(
    "complex configuration applied",
    complexUnitUpdate.sort_order,
    1,
  );
  TestValidator.equals(
    "display style applies in multi-select mode",
    complexUnitUpdate.display_style,
    "dropdown",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallInventoryStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallInventoryStatus";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductCategory";
import type { IShoppingMallProductImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductImage";
import type { IShoppingMallProductReviewStatistics } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductReviewStatistics";
import type { IShoppingMallProductUnit } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductUnit";
import type { IShoppingMallProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductVariant";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Test update of unit display ordering to optimize customer decision-making
 * flow. This test validates that sellers can resequence units within product
 * configuration interfaces to present the most important options first. It
 * verifies that sort order changes immediately affect customer-facing
 * interfaces while preserving existing cart selections and order
 * configurations.
 *
 * The test follows this workflow:
 *
 * 1. Create a seller account for authentication
 * 2. Create a product with multiple units for testing sort functionality
 * 3. Create multiple product units with different sort orders
 * 4. Update the sort order of units to optimize customer presentation
 * 5. Verify that the updated sort order is correctly applied
 * 6. Validate business rules around unit ordering and customer decision flow
 */
export async function test_api_seller_product_unit_update_sort_order(
  connection: api.IConnection,
) {
  // Step 1: Create seller account for authentication
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const seller = await api.functional.auth.seller.join(connection, {
    body: {
      email: sellerEmail,
      business_name: RandomGenerator.name(2),
      business_registration_number: RandomGenerator.alphaNumeric(10),
      tax_id: RandomGenerator.alphaNumeric(9),
      phone: RandomGenerator.mobile(),
      business_type: "corporation",
    } satisfies IShoppingMallSeller.IJoin,
  });
  typia.assert(seller);

  // Step 2: Create a product for unit configuration testing
  const product = await api.functional.shoppingMall.seller.products.create(
    connection,
    {
      body: {
        sku: `SKU-${RandomGenerator.alphaNumeric(8)}`,
        name: RandomGenerator.name(3),
        description: RandomGenerator.content({
          paragraphs: 2,
          sentenceMin: 5,
          sentenceMax: 10,
        }),
        price: typia.random<number & tags.Minimum<10> & tags.Maximum<1000>>(),
        condition: "new",
        weight: typia.random<number & tags.Minimum<0.1> & tags.Maximum<10>>(),
        weight_unit: "kg",
        track_quantity: true,
        allow_backorder: false,
        is_shipping_required: true,
        is_taxable: true,
        category_id: typia.random<string & tags.Format<"uuid">>(),
        shopping_mall_seller_id: seller.id,
        variants: [],
        images: [],
        href: "https://example.com/product/create",
        referrer: "https://example.com/dashboard",
      } satisfies IShoppingMallProduct.ICreate,
    },
  );
  typia.assert(product);

  // Step 3: Create multiple product units with different initial sort orders
  const sizeUnit =
    await api.functional.shoppingMall.seller.products.units.create(connection, {
      productCode: product.sku,
      body: {
        name: "Size",
        type: "size",
        display_style: "dropdown",
        is_required: true,
        is_multiple: false,
        sort_order: 1,
      } satisfies IShoppingMallProductUnit.ICreate,
    });
  typia.assert(sizeUnit);

  const colorUnit =
    await api.functional.shoppingMall.seller.products.units.create(connection, {
      productCode: product.sku,
      body: {
        name: "Color",
        type: "color",
        display_style: "swatches",
        is_required: true,
        is_multiple: false,
        sort_order: 2,
      } satisfies IShoppingMallProductUnit.ICreate,
    });
  typia.assert(colorUnit);

  const materialUnit =
    await api.functional.shoppingMall.seller.products.units.create(connection, {
      productCode: product.sku,
      body: {
        name: "Material",
        type: "material",
        display_style: "buttons",
        is_required: false,
        is_multiple: false,
        sort_order: 3,
      } satisfies IShoppingMallProductUnit.ICreate,
    });
  typia.assert(materialUnit);

  // Step 4: Update sort order to optimize customer decision flow
  // Move Color to first position (most important for visual impact)
  const updatedColorUnit =
    await api.functional.shoppingMall.seller.products.units.update(connection, {
      productCode: product.sku,
      unitId: colorUnit.id,
      body: {
        sort_order: 0,
      } satisfies IShoppingMallProductUnit.IUpdate,
    });
  typia.assert(updatedColorUnit);

  // Move Size to second position (after color selection)
  const updatedSizeUnit =
    await api.functional.shoppingMall.seller.products.units.update(connection, {
      productCode: product.sku,
      unitId: sizeUnit.id,
      body: {
        sort_order: 1,
      } satisfies IShoppingMallProductUnit.IUpdate,
    });
  typia.assert(updatedSizeUnit);

  // Move Material to last position (least important for initial selection)
  const updatedMaterialUnit =
    await api.functional.shoppingMall.seller.products.units.update(connection, {
      productCode: product.sku,
      unitId: materialUnit.id,
      body: {
        sort_order: 2,
      } satisfies IShoppingMallProductUnit.IUpdate,
    });
  typia.assert(updatedMaterialUnit);

  // Step 5: Verify updated sort orders are correctly applied
  TestValidator.equals(
    "color unit sort order updated",
    updatedColorUnit.sort_order,
    0,
  );
  TestValidator.equals(
    "size unit sort order updated",
    updatedSizeUnit.sort_order,
    1,
  );
  TestValidator.equals(
    "material unit sort order updated",
    updatedMaterialUnit.sort_order,
    2,
  );

  // Step 6: Validate business logic around unit ordering
  TestValidator.predicate(
    "sort order values are non-negative",
    updatedColorUnit.sort_order >= 0 &&
      updatedSizeUnit.sort_order >= 0 &&
      updatedMaterialUnit.sort_order >= 0,
  );

  TestValidator.predicate(
    "sort order follows logical sequence",
    updatedColorUnit.sort_order < updatedSizeUnit.sort_order &&
      updatedSizeUnit.sort_order < updatedMaterialUnit.sort_order,
  );

  // Step 7: Verify unit properties remain unchanged during sort order update
  TestValidator.equals(
    "color unit name preserved",
    updatedColorUnit.name,
    colorUnit.name,
  );
  TestValidator.equals(
    "color unit type preserved",
    updatedColorUnit.type,
    colorUnit.type,
  );
  TestValidator.equals(
    "color unit display style preserved",
    updatedColorUnit.display_style,
    colorUnit.display_style,
  );
  TestValidator.equals(
    "size unit name preserved",
    updatedSizeUnit.name,
    sizeUnit.name,
  );
  TestValidator.equals(
    "size unit type preserved",
    updatedSizeUnit.type,
    sizeUnit.type,
  );
  TestValidator.equals(
    "material unit name preserved",
    updatedMaterialUnit.name,
    materialUnit.name,
  );
  TestValidator.equals(
    "material unit type preserved",
    updatedMaterialUnit.type,
    materialUnit.type,
  );

  // Step 8: Validate customer decision optimization logic
  TestValidator.predicate(
    "visual elements prioritized in sort order",
    updatedColorUnit.type === "color" && updatedColorUnit.sort_order === 0,
  );

  // Step 9: Verify updated_at timestamps are modified after sort order updates
  TestValidator.predicate(
    "color unit updated after sort order change",
    new Date(updatedColorUnit.updated_at).getTime() >=
      new Date(colorUnit.updated_at).getTime(),
  );
  TestValidator.predicate(
    "size unit updated after sort order change",
    new Date(updatedSizeUnit.updated_at).getTime() >=
      new Date(sizeUnit.updated_at).getTime(),
  );
  TestValidator.predicate(
    "material unit updated after sort order change",
    new Date(updatedMaterialUnit.updated_at).getTime() >=
      new Date(materialUnit.updated_at).getTime(),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
