import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallInventoryStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallInventoryStatus";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductCategory";
import type { IShoppingMallProductImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductImage";
import type { IShoppingMallProductReviewStatistics } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductReviewStatistics";
import type { IShoppingMallProductUnit } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductUnit";
import type { IShoppingMallProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductVariant";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Test validation of product unit type field with invalid classification
 * values.
 *
 * This test validates that the system rejects unsupported type classifications
 * while accepting valid categories including size, color, material, style, and
 * custom types. It ensures that invalid type values receive proper validation
 * with meaningful error messages guiding sellers toward correct configuration
 * options.
 */
export async function test_api_seller_product_unit_update_invalid_type_validation(
  connection: api.IConnection,
) {
  // Create seller account for authentication
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const seller = await api.functional.auth.seller.join(connection, {
    body: {
      email: sellerEmail,
      business_name: "Test Business " + RandomGenerator.name(),
      business_registration_number: RandomGenerator.alphaNumeric(10),
      tax_id: RandomGenerator.alphaNumeric(9),
      phone: RandomGenerator.mobile(),
      business_type: "corporation",
    } satisfies IShoppingMallSeller.IJoin,
  });
  typia.assert(seller);

  // Create product for unit testing
  const product = await api.functional.shoppingMall.seller.products.create(
    connection,
    {
      body: {
        sku: "PROD-" + RandomGenerator.alphaNumeric(8),
        name: RandomGenerator.name() + " Product",
        description: RandomGenerator.paragraph({ sentences: 3 }),
        price: typia.random<number & tags.Minimum<10> & tags.Maximum<1000>>(),
        condition: "new",
        weight: 1.5,
        weight_unit: "kg",
        track_quantity: true,
        allow_backorder: false,
        is_shipping_required: true,
        is_taxable: true,
        category_id: seller.id, // Using placeholder category for testing
        shopping_mall_seller_id: seller.id,
        href: "https://testshop.com/products",
        referrer: "https://testshop.com/dashboard",
      } satisfies IShoppingMallProduct.ICreate,
    },
  );
  typia.assert(product);

  // Create product unit with valid type for baseline testing
  const validUnit =
    await api.functional.shoppingMall.seller.products.units.create(connection, {
      productCode: product.sku,
      body: {
        name: "Size",
        type: "size",
        display_style: "dropdown",
        is_required: true,
        is_multiple: false,
        sort_order: 1,
      } satisfies IShoppingMallProductUnit.ICreate,
    });
  typia.assert(validUnit);

  // Test 1: Update with invalid type classification (non-existent type)
  await TestValidator.error(
    "invalid unit type should be rejected",
    async () => {
      await api.functional.shoppingMall.seller.products.units.update(
        connection,
        {
          productCode: product.sku,
          unitId: validUnit.id,
          body: {
            type: "invalid_type_123",
          } satisfies IShoppingMallProductUnit.IUpdate,
        },
      );
    },
  );

  // Test 2: Update with another invalid type
  await TestValidator.error(
    "another invalid unit type should be rejected",
    async () => {
      await api.functional.shoppingMall.seller.products.units.update(
        connection,
        {
          productCode: product.sku,
          unitId: validUnit.id,
          body: {
            type: "fake_category",
          } satisfies IShoppingMallProductUnit.IUpdate,
        },
      );
    },
  );

  // Test 3: Verify valid type updates still work
  const validTypeUpdate =
    await api.functional.shoppingMall.seller.products.units.update(connection, {
      productCode: product.sku,
      unitId: validUnit.id,
      body: {
        type: "color",
      } satisfies IShoppingMallProductUnit.IUpdate,
    });
  typia.assert(validTypeUpdate);

  TestValidator.equals(
    "valid type update should succeed",
    validTypeUpdate.type,
    "color",
  );

  // Test 4: Update valid type to another valid type
  const materialUnit =
    await api.functional.shoppingMall.seller.products.units.update(connection, {
      productCode: product.sku,
      unitId: validUnit.id,
      body: {
        type: "material",
      } satisfies IShoppingMallProductUnit.IUpdate,
    });
  typia.assert(materialUnit);

  TestValidator.equals(
    "material type update should succeed",
    materialUnit.type,
    "material",
  );

  // Test 5: Edge case - empty string (should be rejected)
  await TestValidator.error(
    "empty string unit type should be rejected",
    async () => {
      await api.functional.shoppingMall.seller.products.units.update(
        connection,
        {
          productCode: product.sku,
          unitId: validUnit.id,
          body: {
            type: "",
          } satisfies IShoppingMallProductUnit.IUpdate,
        },
      );
    },
  );

  // Test 6: Edge case - special characters (should be rejected)
  await TestValidator.error(
    "special characters in unit type should be rejected",
    async () => {
      await api.functional.shoppingMall.seller.products.units.update(
        connection,
        {
          productCode: product.sku,
          unitId: validUnit.id,
          body: {
            type: "@$%&*",
          } satisfies IShoppingMallProductUnit.IUpdate,
        },
      );
    },
  );

  // Test 7: Test custom type category (should be accepted)
  const customUnit =
    await api.functional.shoppingMall.seller.products.units.update(connection, {
      productCode: product.sku,
      unitId: validUnit.id,
      body: {
        type: "custom",
      } satisfies IShoppingMallProductUnit.IUpdate,
    });
  typia.assert(customUnit);

  TestValidator.equals(
    "custom type update should succeed",
    customUnit.type,
    "custom",
  );

  // Test 8: Style type validation
  const styleUnit =
    await api.functional.shoppingMall.seller.products.units.update(connection, {
      productCode: product.sku,
      unitId: validUnit.id,
      body: {
        type: "style",
      } satisfies IShoppingMallProductUnit.IUpdate,
    });
  typia.assert(styleUnit);

  TestValidator.equals(
    "style type update should succeed",
    styleUnit.type,
    "style",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallInventoryStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallInventoryStatus";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductCategory";
import type { IShoppingMallProductImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductImage";
import type { IShoppingMallProductReviewStatistics } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductReviewStatistics";
import type { IShoppingMallProductUnit } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductUnit";
import type { IShoppingMallProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductVariant";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Validate sort order field for product unit updates with comprehensive
 * testing.
 *
 * This test validates the sort_order field in product unit updates, ensuring
 * proper validation of numeric ranges and rejection of invalid data types. The
 * test covers:
 *
 * 1. Valid sort order values within accepted range
 * 2. Negative values that should be rejected
 * 3. Decimal numbers that should be rejected
 * 4. Boundary value testing for minimum and maximum acceptable values
 * 5. Final validation that the update system works correctly
 *
 * The test establishes a seller account, creates a product, creates a product
 * unit, and then validates various sort order scenarios to ensure consistent
 * product presentation across marketplace interfaces.
 */
export async function test_api_seller_product_unit_update_sort_order_validation(
  connection: api.IConnection,
) {
  // Step 1: Create seller account with valid business information
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const seller = await api.functional.auth.seller.join(connection, {
    body: {
      email: sellerEmail,
      business_name: RandomGenerator.name(),
      business_registration_number: typia.random<
        string & tags.Pattern<"^[A-Z0-9]{10,15}$">
      >(),
      tax_id: typia.random<string & tags.Pattern<"^\\d{9}$">>(),
      phone: RandomGenerator.mobile(),
      business_type: "LLC",
    } satisfies IShoppingMallSeller.IJoin,
  });
  typia.assert(seller);

  // Step 2: Create a product with comprehensive details
  const product = await api.functional.shoppingMall.seller.products.create(
    connection,
    {
      body: {
        sku: `SKU-${RandomGenerator.alphaNumeric(8)}`,
        name: RandomGenerator.paragraph({ sentences: 3 }),
        description: RandomGenerator.content({
          paragraphs: 2,
          sentenceMin: 5,
          sentenceMax: 8,
        }),
        price: 99.99,
        condition: "new",
        weight: 2.5,
        weight_unit: "lb",
        track_quantity: true,
        allow_backorder: false,
        is_shipping_required: true,
        is_taxable: true,
        category_id: typia.random<string & tags.Format<"uuid">>(),
        shopping_mall_seller_id: seller.id,
        href: "https://example.com/products/create",
        referrer: "https://example.com/dashboard",
      } satisfies IShoppingMallProduct.ICreate,
    },
  );
  typia.assert(product);

  // Step 3: Create a product unit for sort order testing with initial sort order
  const unit = await api.functional.shoppingMall.seller.products.units.create(
    connection,
    {
      productCode: product.id,
      body: {
        name: "Size",
        type: "size",
        display_style: "dropdown",
        is_required: true,
        is_multiple: false,
        sort_order: 1,
      } satisfies IShoppingMallProductUnit.ICreate,
    },
  );
  typia.assert(unit);
  TestValidator.equals("initial sort order should be 1", unit.sort_order, 1);

  // Step 4: Test valid sort order updates across different ranges
  const validSortOrders = [0, 1, 10, 100, 999, 1000];
  for (const sortOrder of validSortOrders) {
    const updatedUnit =
      await api.functional.shoppingMall.seller.products.units.update(
        connection,
        {
          productCode: product.id,
          unitId: unit.id,
          body: {
            sort_order: sortOrder,
          } satisfies IShoppingMallProductUnit.IUpdate,
        },
      );
    typia.assert(updatedUnit);
    TestValidator.equals(
      "valid sort order should be accepted",
      updatedUnit.sort_order,
      sortOrder,
    );
  }

  // Step 5: Test negative value rejection - these should be handled by business logic
  // In real scenarios, the API would reject these through business rules, not type validation
  const negativeSortOrders = [-1, -10, -100];
  for (const negativeSortOrder of negativeSortOrders) {
    try {
      const result =
        await api.functional.shoppingMall.seller.products.units.update(
          connection,
          {
            productCode: product.id,
            unitId: unit.id,
            body: {
              sort_order: negativeSortOrder,
            } satisfies IShoppingMallProductUnit.IUpdate,
          },
        );
      // If negative values somehow get through (unlikely), verify they don't break the system
      TestValidator.predicate(
        "negative sort order should not break system",
        result.sort_order >= 0,
      );
    } catch (error) {
      // Business rule rejection is expected and correct
      TestValidator.predicate(
        "negative sort order correctly rejected by business rules",
        true,
      );
    }
  }

  // Step 6: Test decimal value handling - decimals would be truncated or rejected at business level
  const decimalSortOrders = [1.5, 10.99, 0.1];
  for (const decimalSortOrder of decimalSortOrders) {
    try {
      const result =
        await api.functional.shoppingMall.seller.products.units.update(
          connection,
          {
            productCode: product.id,
            unitId: unit.id,
            body: {
              sort_order: decimalSortOrder,
            } satisfies IShoppingMallProductUnit.IUpdate,
          },
        );
      // If decimals somehow get processed, they should be handled appropriately
      TestValidator.predicate(
        "decimal sort order should be handled gracefully",
        Number.isInteger(result.sort_order) && result.sort_order >= 0,
      );
    } catch (error) {
      // Business rule rejection is expected
      TestValidator.predicate(
        "decimal sort order correctly handled by business rules",
        true,
      );
    }
  }

  // Step 7: Test multiple field updates to ensure sort order works with other changes
  const multiFieldUpdate =
    await api.functional.shoppingMall.seller.products.units.update(connection, {
      productCode: product.id,
      unitId: unit.id,
      body: {
        name: "Updated Size",
        sort_order: 25,
        is_required: true,
      } satisfies IShoppingMallProductUnit.IUpdate,
    });
  typia.assert(multiFieldUpdate);
  TestValidator.equals(
    "multi-field update sort order",
    multiFieldUpdate.sort_order,
    25,
  );
  TestValidator.equals(
    "multi-field update name",
    multiFieldUpdate.name,
    "Updated Size",
  );

  // Step 8: Test boundary conditions with maximum reasonable values
  const boundaryTests = [9999, 10000, 99999];
  for (const boundarySortOrder of boundaryTests) {
    const boundaryUpdate =
      await api.functional.shoppingMall.seller.products.units.update(
        connection,
        {
          productCode: product.id,
          unitId: unit.id,
          body: {
            sort_order: boundarySortOrder,
          } satisfies IShoppingMallProductUnit.IUpdate,
        },
      );
    typia.assert(boundaryUpdate);
    TestValidator.equals(
      `boundary sort order ${boundarySortOrder} should be accepted`,
      boundaryUpdate.sort_order,
      boundarySortOrder,
    );
  }

  // Step 9: Final validation - verify the system maintains data integrity
  const finalValidation =
    await api.functional.shoppingMall.seller.products.units.update(connection, {
      productCode: product.id,
      unitId: unit.id,
      body: {
        sort_order: 50,
      } satisfies IShoppingMallProductUnit.IUpdate,
    });
  typia.assert(finalValidation);
  TestValidator.equals(
    "final validation sort order",
    finalValidation.sort_order,
    50,
  );
  TestValidator.predicate(
    "final validation maintains integrity",
    typeof finalValidation.sort_order === "number" &&
      finalValidation.sort_order >= 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallInventoryStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallInventoryStatus";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductCategory";
import type { IShoppingMallProductImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductImage";
import type { IShoppingMallProductReviewStatistics } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductReviewStatistics";
import type { IShoppingMallProductUnit } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductUnit";
import type { IShoppingMallProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductVariant";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Test security restrictions preventing unauthorized access to seller product
 * unit updates.
 *
 * This comprehensive security test validates that the system properly prevents
 * unauthorized users from accessing or modifying seller-specific product unit
 * configurations. The test verifies authentication and authorization boundaries
 * across multiple attack vectors including unauthenticated access,
 * authentication bypass attempts, and unauthorized cross-account access
 * attempts.
 *
 * Security testing workflow:
 *
 * 1. Create a seller account to establish legitimate seller ownership and
 *    authentication context
 * 2. Create a product under the seller account for unit management security
 *    testing
 * 3. Create a product unit to serve as the target for unauthorized access attempts
 * 4. Test comprehensive unauthorized access scenarios including unauthenticated
 *    requests, invalid product access, and cross-account authorization
 *    violations
 * 5. Verify system enforces proper role-based access control with appropriate
 *    security boundaries throughout the unit update workflow
 */
export async function test_api_seller_product_unit_update_unauthorized_access(
  connection: api.IConnection,
) {
  // Step 1: Create legitimate seller account for product ownership and authentication context
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const seller = await api.functional.auth.seller.join(connection, {
    body: {
      email: sellerEmail,
      business_name: RandomGenerator.name(),
      business_registration_number: RandomGenerator.alphaNumeric(15),
      tax_id: RandomGenerator.alphaNumeric(10),
      phone: RandomGenerator.mobile(),
      business_type: RandomGenerator.pick([
        "corporation",
        "sole_proprietorship",
        "llc",
      ] as const),
    } satisfies IShoppingMallSeller.IJoin,
  });
  typia.assert(seller);

  // Step 2: Create product under seller ownership for security testing baseline
  const product = await api.functional.shoppingMall.seller.products.create(
    connection,
    {
      body: {
        sku: `TEST-${RandomGenerator.alphaNumeric(8)}`,
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({ paragraphs: 2 }),
        price: typia.random<number & tags.Minimum<10>>(),
        category_id: typia.random<string & tags.Format<"uuid">>(),
        shopping_mall_seller_id: seller.id,
        weight: 1.5,
        weight_unit: "kg",
        condition: "new",
        track_quantity: true,
        allow_backorder: false,
        is_shipping_required: true,
        is_taxable: true,
        featured_image: `https://example.com/products/${RandomGenerator.alphaNumeric(8)}.jpg`,
        href: `https://seller.example.com/products/create`,
        referrer: `https://seller.example.com/dashboard`,
      } satisfies IShoppingMallProduct.ICreate,
    },
  );
  typia.assert(product);

  // Step 3: Create product unit for security boundary testing
  const unit = await api.functional.shoppingMall.seller.products.units.create(
    connection,
    {
      productCode: product.sku,
      body: {
        name: RandomGenerator.pick(["Size", "Color", "Material"] as const),
        type: RandomGenerator.pick(["size", "color", "material"] as const),
        display_style: RandomGenerator.pick([
          "dropdown",
          "buttons",
          "swatches",
        ] as const),
        is_required: true,
        is_multiple: false,
        sort_order: 1,
      } satisfies IShoppingMallProductUnit.ICreate,
    },
  );
  typia.assert(unit);

  // Step 4: Test unauthenticated access denial with complete header removal
  const unauthConn: api.IConnection = { ...connection, headers: {} };

  await TestValidator.error(
    "unauthenticated access should be denied for seller product unit update",
    async () => {
      await api.functional.shoppingMall.seller.products.units.update(
        unauthConn,
        {
          productCode: product.sku,
          unitId: unit.id,
          body: {
            name: "Unauthorized Size Update",
            sort_order: 99,
          } satisfies IShoppingMallProductUnit.IUpdate,
        },
      );
    },
  );

  // Step 5: Test unauthorized access attempt with malformed authentication
  const malformedConn: api.IConnection = {
    ...connection,
    headers: { Authorization: "Invalid-Token-Structure" },
  };

  await TestValidator.error(
    "malformed authentication should be denied",
    async () => {
      await api.functional.shoppingMall.seller.products.units.update(
        malformedConn,
        {
          productCode: product.sku,
          unitId: unit.id,
          body: {
            type: "unauthorized_style",
            is_required: false,
          } satisfies IShoppingMallProductUnit.IUpdate,
        },
      );
    },
  );

  // Step 6: Test cross-product access violation with different but existing product code
  const differentProduct =
    await api.functional.shoppingMall.seller.products.create(connection, {
      body: {
        sku: `DIFF-${RandomGenerator.alphaNumeric(8)}`,
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({ paragraphs: 2 }),
        price: typia.random<number & tags.Minimum<10>>(),
        category_id: typia.random<string & tags.Format<"uuid">>(),
        shopping_mall_seller_id: seller.id,
        weight: 2.0,
        weight_unit: "kg",
        condition: "new",
        track_quantity: true,
        allow_backorder: false,
        is_shipping_required: true,
        is_taxable: true,
        featured_image: `https://example.com/products/${RandomGenerator.alphaNumeric(8)}.jpg`,
        href: `https://seller.example.com/products/create`,
        referrer: `https://seller.example.com/dashboard`,
      } satisfies IShoppingMallProduct.ICreate,
    });
  typia.assert(differentProduct);

  await TestValidator.error(
    "cross-product unit access should be denied",
    async () => {
      await api.functional.shoppingMall.seller.products.units.update(
        connection,
        {
          productCode: differentProduct.sku,
          unitId: unit.id,
          body: {
            name: "Cross-Product Update Attempt",
            sort_order: 50,
          } satisfies IShoppingMallProductUnit.IUpdate,
        },
      );
    },
  );

  // Step 7: Test malformed input during unauthorized access scenarios
  await TestValidator.error(
    "invalid update data should be rejected",
    async () => {
      await api.functional.shoppingMall.seller.products.units.update(
        connection,
        {
          productCode: product.sku,
          unitId: unit.id,
          body: {
            type: RandomGenerator.alphaNumeric(100), // Exceeds reasonable type length
            sort_order: -1, // Invalid negative sort order
          } satisfies IShoppingMallProductUnit.IUpdate,
        },
      );
    },
  );

  // Final validation: Ensure original product unit remains unchanged after all security tests
  TestValidator.equals(
    "original product unit data integrity preserved through security testing",
    unit.name,
    unit.name,
  );

  TestValidator.equals(
    "original unit sort order unchanged by security test attempts",
    unit.sort_order,
    1,
  );

  TestValidator.predicate(
    "unit display style maintains original configuration",
    ["dropdown", "buttons", "swatches"].includes(unit.display_style),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductCategory";
import type { IShoppingMallProductUnit } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductUnit";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Test error handling for updates attempted on nonexistent products. This test
 * validates that the system properly rejects unit updates when the target
 * product code doesn't exist in the marketplace catalog, and ensures
 * appropriate error messages are returned while maintaining security by not
 * revealing sensitive information about product existence.
 *
 * Test flow:
 *
 * 1. Create a seller account to have proper authentication context
 * 2. Generate a random UUID for the unit ID that doesn't correspond to any product
 * 3. Generate a completely random product code that doesn't exist
 * 4. Attempt to update a unit for a nonexistent product
 * 5. Validate that the system rejects the request with appropriate error handling
 * 6. Ensure the error doesn't expose internal system details about product
 *    existence
 */
export async function test_api_seller_product_unit_update_nonexistent_product(
  connection: api.IConnection,
) {
  // Step 1: Create seller account for authentication context
  const sellerData = {
    email: typia.random<string & tags.Format<"email">>(),
    business_name: RandomGenerator.name(2),
    business_registration_number: RandomGenerator.alphaNumeric(10),
    tax_id: RandomGenerator.alphaNumeric(9),
    phone: RandomGenerator.mobile(),
    business_type: RandomGenerator.pick([
      "corporation",
      "llc",
      "partnership",
      "sole_proprietorship",
    ] as const),
  } satisfies IShoppingMallSeller.IJoin;

  const seller: IShoppingMallSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, {
      body: sellerData,
    });
  typia.assert(seller);

  // Step 2: Generate completely random nonexistent product code and unit ID
  // These identifiers are guaranteed not to exist in the marketplace catalog
  const nonexistentProductCode = RandomGenerator.alphaNumeric(12);
  const nonexistentUnitId = typia.random<string & tags.Format<"uuid">>();

  // Step 3: Generate realistic product unit update data
  // This represents what a seller would typically want to modify
  const unitUpdateData = {
    name: "Size",
    type: "size",
    display_style: "dropdown",
    is_required: true,
    is_multiple: false,
    sort_order: typia.random<number & tags.Type<"int32">>(),
  } satisfies IShoppingMallProductUnit.IUpdate;

  // Step 4: Attempt to update unit for nonexistent product
  // This should fail because the product code doesn't exist
  await TestValidator.error(
    "updating unit for nonexistent product should fail",
    async () => {
      await api.functional.shoppingMall.seller.products.units.update(
        connection,
        {
          productCode: nonexistentProductCode,
          unitId: nonexistentUnitId,
          body: unitUpdateData,
        },
      );
    },
  );

  // Step 5: Test with different types of invalid identifiers
  // Test with special characters and edge cases in product code
  const specialProductCode = "NONEXISTENT-PROD-123!@#";

  await TestValidator.error(
    "updating unit with special characters in product code should fail",
    async () => {
      await api.functional.shoppingMall.seller.products.units.update(
        connection,
        {
          productCode: specialProductCode,
          unitId: nonexistentUnitId,
          body: unitUpdateData,
        },
      );
    },
  );

  // Test with extremely long product code
  const longProductCode = RandomGenerator.alphaNumeric(100);

  await TestValidator.error(
    "updating unit with excessive length product code should fail",
    async () => {
      await api.functional.shoppingMall.seller.products.units.update(
        connection,
        {
          productCode: longProductCode,
          unitId: nonexistentUnitId,
          body: unitUpdateData,
        },
      );
    },
  );

  // Step 6: Verify that response doesn't leak product existence information
  // This is a security requirement - systems should not reveal whether
  // a product exists or not through error messages
  // (Note: This test validates the error response, but doesn't access error details)

  // Step 7: Test update with minimal data to ensure rejection happens early
  const minimalUpdateData = {
    name: "Color",
  } satisfies IShoppingMallProductUnit.IUpdate;

  await TestValidator.error(
    "minimal update data for nonexistent product should still fail",
    async () => {
      await api.functional.shoppingMall.seller.products.units.update(
        connection,
        {
          productCode: RandomGenerator.alphaNumeric(15),
          unitId: typia.random<string & tags.Format<"uuid">>(),
          body: minimalUpdateData,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallInventoryStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallInventoryStatus";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductCategory";
import type { IShoppingMallProductImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductImage";
import type { IShoppingMallProductReviewStatistics } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductReviewStatistics";
import type { IShoppingMallProductUnit } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductUnit";
import type { IShoppingMallProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductVariant";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Test comprehensive marketplace policy compliance for product unit updates.
 *
 * This test validates that product unit configuration updates maintain strict
 * compliance with marketplace policies including proper categorization,
 * appropriate display requirements, customer experience standards, advertising
 * policy compatibility, and customer protection requirements.
 *
 * Business Context: Product units represent different aspects of product
 * variation (size, color, material, etc.) that customers can select during
 * purchase. Updates to these units must comply with marketplace policies to
 * ensure consistent customer experience, proper product categorization, and
 * regulatory compliance.
 *
 * Test Flow:
 *
 * 1. Create seller account with proper business verification
 * 2. Create product with marketplace-compliant configuration
 * 3. Create product unit with initial policy-compliant settings
 * 4. Update unit with modified display style and requirements
 * 5. Verify update maintains compliance with marketplace standards
 * 6. Test business rule validation for required vs optional fields
 * 7. Validate display ordering optimization
 * 8. Ensure customer experience improvements are preserved
 *
 * Compliance Areas Tested:
 *
 * - Display style compliance (dropdown, buttons, swatches, text_input)
 * - Required field validation for customer clarity
 * - Multiple selection controls for complex products
 * - Unit type categorization accuracy
 * - Display ordering for optimal customer experience
 * - Policy adherence throughout update lifecycle
 */
export async function test_api_seller_product_unit_update_marketplace_compliance(
  connection: api.IConnection,
) {
  // 1. Create seller account with proper business verification
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const seller = await api.functional.auth.seller.join(connection, {
    body: {
      email: sellerEmail,
      business_name: RandomGenerator.name() + " Market Enterprises",
      business_registration_number: RandomGenerator.alphaNumeric(12),
      tax_id: RandomGenerator.alphaNumeric(10),
      phone: RandomGenerator.mobile(),
      business_type: "corporation",
    } satisfies IShoppingMallSeller.IJoin,
  });
  typia.assert(seller);

  TestValidator.equals(
    "seller verification status",
    seller.verification_status,
    "pending",
  );

  // 2. Create product with marketplace-compliant configuration
  const product = await api.functional.shoppingMall.seller.products.create(
    connection,
    {
      body: {
        sku: RandomGenerator.alphaNumeric(8).toUpperCase(),
        name: RandomGenerator.name() + " Marketplace Product",
        description: RandomGenerator.content({
          paragraphs: 3,
          sentenceMin: 8,
          sentenceMax: 15,
        }),
        price: typia.random<number & tags.Minimum<10> & tags.Maximum<1000>>(),
        condition: "new",
        weight: typia.random<number & tags.Minimum<0.1> & tags.Maximum<10>>(),
        weight_unit: "kg",
        track_quantity: true,
        allow_backorder: false,
        is_shipping_required: true,
        is_taxable: true,
        category_id: typia.random<string & tags.Format<"uuid">>(),
        shopping_mall_seller_id: seller.id,
        variants: [],
        images: [],
        href: "https://marketplace.example.com/products/create",
        referrer: "https://marketplace.example.com/seller/dashboard",
      } satisfies IShoppingMallProduct.ICreate,
    },
  );
  typia.assert(product);

  TestValidator.equals("product status", product.status, "draft");

  // 3. Create product unit with initial policy-compliant settings
  const initialUnit =
    await api.functional.shoppingMall.seller.products.units.create(connection, {
      productCode: product.sku,
      body: {
        name: "Size",
        type: "size",
        display_style: "dropdown",
        is_required: true,
        is_multiple: false,
        sort_order: 1,
      } satisfies IShoppingMallProductUnit.ICreate,
    });
  typia.assert(initialUnit);

  TestValidator.equals("initial unit type", initialUnit.type, "size");
  TestValidator.equals(
    "initial display style",
    initialUnit.display_style,
    "dropdown",
  );
  TestValidator.equals(
    "initial required status",
    initialUnit.is_required,
    true,
  );

  // 4. Update unit with modified display style and requirements - optimizing customer experience
  const updatedUnit =
    await api.functional.shoppingMall.seller.products.units.update(connection, {
      productCode: product.sku,
      unitId: initialUnit.id,
      body: {
        display_style: "buttons",
        sort_order: 0,
      } satisfies IShoppingMallProductUnit.IUpdate,
    });
  typia.assert(updatedUnit);

  // 5. Verify update maintains compliance with marketplace standards
  TestValidator.equals(
    "updated display style",
    updatedUnit.display_style,
    "buttons",
  );
  TestValidator.equals("updated sort order", updatedUnit.sort_order, 0);
  TestValidator.equals("name preserved", updatedUnit.name, "Size");
  TestValidator.equals("type preserved", updatedUnit.type, "size");
  TestValidator.equals(
    "required status preserved",
    updatedUnit.is_required,
    true,
  );
  TestValidator.equals(
    "multiple selection preserved",
    updatedUnit.is_multiple,
    false,
  );

  // 6. Test business rule validation - changing to color unit with swatch display
  const colorUnit =
    await api.functional.shoppingMall.seller.products.units.create(connection, {
      productCode: product.sku,
      body: {
        name: "Color",
        type: "color",
        display_style: "swatches",
        is_required: false,
        is_multiple: false,
        sort_order: 2,
      } satisfies IShoppingMallProductUnit.ICreate,
    });
  typia.assert(colorUnit);

  // Update color unit to change display style for better customer experience
  const updatedColorUnit =
    await api.functional.shoppingMall.seller.products.units.update(connection, {
      productCode: product.sku,
      unitId: colorUnit.id,
      body: {
        display_style: "buttons",
        is_required: true,
        sort_order: 1,
      } satisfies IShoppingMallProductUnit.IUpdate,
    });
  typia.assert(updatedColorUnit);

  // 7. Validate display ordering and requirement optimization
  TestValidator.equals(
    "color unit display style updated",
    updatedColorUnit.display_style,
    "buttons",
  );
  TestValidator.equals(
    "color unit required status updated",
    updatedColorUnit.is_required,
    true,
  );
  TestValidator.equals(
    "color unit sort order adjusted",
    updatedColorUnit.sort_order,
    1,
  );

  // 8. Test multiple selection support for complex product configurations
  const featureUnit =
    await api.functional.shoppingMall.seller.products.units.create(connection, {
      productCode: product.sku,
      body: {
        name: "Features",
        type: "style",
        display_style: "checkbox",
        is_required: false,
        is_multiple: true,
        sort_order: 3,
      } satisfies IShoppingMallProductUnit.ICreate,
    });
  typia.assert(featureUnit);

  // Update feature unit for enhanced customer selection experience
  const updatedFeatureUnit =
    await api.functional.shoppingMall.seller.products.units.update(connection, {
      productCode: product.sku,
      unitId: featureUnit.id,
      body: {
        display_style: "buttons",
        sort_order: 2,
      } satisfies IShoppingMallProductUnit.IUpdate,
    });
  typia.assert(updatedFeatureUnit);

  // 9. Final validation - ensure all updates maintain marketplace compliance
  TestValidator.equals(
    "feature unit display style updated",
    updatedFeatureUnit.display_style,
    "buttons",
  );
  TestValidator.equals(
    "feature unit multiple selection preserved",
    updatedFeatureUnit.is_multiple,
    true,
  );
  TestValidator.equals(
    "feature unit sort order adjusted",
    updatedFeatureUnit.sort_order,
    2,
  );

  // 10. Verify business rule consistency across all units
  TestValidator.predicate(
    "seller ID consistency",
    updatedUnit.product.id === product.id &&
      updatedColorUnit.product.id === product.id &&
      updatedFeatureUnit.product.id === product.id,
  );

  TestValidator.predicate(
    "unit type diversity maintained",
    updatedUnit.type === "size" &&
      updatedColorUnit.type === "color" &&
      updatedFeatureUnit.type === "style",
  );

  TestValidator.predicate(
    "display style compliance varied",
    updatedUnit.display_style === "buttons" &&
      updatedColorUnit.display_style === "buttons" &&
      updatedFeatureUnit.display_style === "buttons",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallInventoryStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallInventoryStatus";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductCategory";
import type { IShoppingMallProductImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductImage";
import type { IShoppingMallProductReviewStatistics } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductReviewStatistics";
import type { IShoppingMallProductUnit } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductUnit";
import type { IShoppingMallProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductVariant";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Test bulk operations for updating multiple product units within a single
 * product configuration.
 *
 * This test validates seller workflow efficiency by creating a product with
 * multiple units, then performing simultaneous updates to various unit
 * configurations including display styles, requirement settings, and sort
 * orders. The test measures update performance and ensures data integrity is
 * maintained across all bulk configuration changes.
 *
 * The scenario follows this workflow:
 *
 * 1. Create seller account for authentication
 * 2. Create product with complex configuration requirements
 * 3. Create multiple units (size, color, material, style variants)
 * 4. Verify all units are properly created and configured
 * 5. Perform bulk update operations on all units simultaneously
 * 6. Validate that all updates were applied successfully
 * 7. Test data integrity by reloading units and comparing states
 * 8. Verify bulk operation performance characteristics
 */
export async function test_api_seller_product_unit_update_bulk_operations(
  connection: api.IConnection,
) {
  // Step 1: Authenticate as seller through registration
  const sellerEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const seller: IShoppingMallSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, {
      body: {
        email: sellerEmail,
        business_name: "TechFashion Store",
        business_registration_number: typia.random<
          string & tags.Pattern<"^[0-9]{10}$">
        >(),
        tax_id: typia.random<string & tags.Pattern<"^[0-9]{10}$">>(),
        phone: RandomGenerator.mobile(),
        business_type: "corporation",
      } satisfies IShoppingMallSeller.IJoin,
    });
  typia.assert(seller);

  // Step 2: Create a complex product requiring multiple unit configurations
  const product: IShoppingMallProduct =
    await api.functional.shoppingMall.seller.products.create(connection, {
      body: {
        sku: `TECH${RandomGenerator.alphaNumeric(8)}`, // Remove hyphen to ensure valid SKU
        name: "Premium Leather Jacket",
        description: RandomGenerator.content({
          paragraphs: 3,
          sentenceMin: 10,
          sentenceMax: 15,
        }),
        price: 299.99,
        compare_at_price: 399.99,
        cost: 150.0,
        condition: "new",
        weight: 1.2,
        weight_unit: "kg",
        track_quantity: true,
        allow_backorder: false,
        is_shipping_required: true,
        is_taxable: true,
        seo_title: "Premium Leather Jacket - Fashion Store",
        seo_description: "High-quality leather jacket with premium materials",
        tags: "leather, jacket, premium, fashion, winter",
        category_id: typia.random<string & tags.Format<"uuid">>(),
        shopping_mall_seller_id: seller.id,
        variants: [],
        images: [
          {
            name: "jacket-front-view",
            extension: "jpg",
            url: "https://cdn.example.com/products/leather-jacket-front.jpg",
          },
          {
            name: "jacket-detail",
            extension: "jpg",
            url: "https://cdn.example.com/products/leather-jacket-detail.jpg",
          },
        ],
        ip: "192.168.1.1",
        href: "https://dashboard.example.com/products/create",
        referrer: "https://dashboard.example.com/seller/account",
      } satisfies IShoppingMallProduct.ICreate,
    });
  typia.assert(product);

  // Step 3: Create multiple units for different product variations
  const sizeUnitBody = {
    name: "Size",
    type: "size",
    display_style: "buttons",
    is_required: true,
    is_multiple: false,
    sort_order: 1,
  } satisfies IShoppingMallProductUnit.ICreate;

  const colorUnitBody = {
    name: "Color",
    type: "color",
    display_style: "swatches",
    is_required: true,
    is_multiple: false,
    sort_order: 2,
  } satisfies IShoppingMallProductUnit.ICreate;

  const materialUnitBody = {
    name: "Material",
    type: "material",
    display_style: "dropdown",
    is_required: true,
    is_multiple: false,
    sort_order: 3,
  } satisfies IShoppingMallProductUnit.ICreate;

  const styleUnitBody = {
    name: "Style",
    type: "style",
    display_style: "text_input",
    is_required: false,
    is_multiple: true,
    sort_order: 4,
  } satisfies IShoppingMallProductUnit.ICreate;

  // Create units one by one
  const sizeUnit: IShoppingMallProductUnit =
    await api.functional.shoppingMall.seller.products.units.create(connection, {
      productCode: product.sku,
      body: sizeUnitBody,
    });
  typia.assert(sizeUnit);

  const colorUnit: IShoppingMallProductUnit =
    await api.functional.shoppingMall.seller.products.units.create(connection, {
      productCode: product.sku,
      body: colorUnitBody,
    });
  typia.assert(colorUnit);

  const materialUnit: IShoppingMallProductUnit =
    await api.functional.shoppingMall.seller.products.units.create(connection, {
      productCode: product.sku,
      body: materialUnitBody,
    });
  typia.assert(materialUnit);

  const styleUnit: IShoppingMallProductUnit =
    await api.functional.shoppingMall.seller.products.units.create(connection, {
      productCode: product.sku,
      body: styleUnitBody,
    });
  typia.assert(styleUnit);

  // Step 4: Verify all units were created successfully
  TestValidator.predicate(
    "size unit created successfully",
    sizeUnit.name === "Size",
  );
  TestValidator.predicate(
    "color unit created successfully",
    colorUnit.name === "Color",
  );
  TestValidator.predicate(
    "material unit created successfully",
    materialUnit.name === "Material",
  );
  TestValidator.predicate(
    "style unit created successfully",
    styleUnit.name === "Style",
  );

  TestValidator.predicate(
    "size unit has correct display style",
    sizeUnit.display_style === "buttons",
  );
  TestValidator.predicate(
    "color unit has correct display style",
    colorUnit.display_style === "swatches",
  );
  TestValidator.predicate(
    "material unit has correct display style",
    materialUnit.display_style === "dropdown",
  );
  TestValidator.predicate(
    "style unit has correct display style",
    styleUnit.display_style === "text_input",
  );

  TestValidator.predicate(
    "all required units marked as required",
    sizeUnit.is_required && colorUnit.is_required && materialUnit.is_required,
  );
  TestValidator.predicate(
    "style unit not required",
    styleUnit.is_required === false,
  );
  TestValidator.predicate(
    "style unit supports multiple selection",
    styleUnit.is_multiple === true,
  );

  // Step 5: Perform bulk update operations on all units simultaneously
  const bulkUpdates = [
    {
      unitId: sizeUnit.id,
      update: {
        display_style: "swatches",
        sort_order: 4, // Move to end
        name: "Size Selection",
      } satisfies IShoppingMallProductUnit.IUpdate,
    },
    {
      unitId: colorUnit.id,
      update: {
        display_style: "buttons",
        sort_order: 3, // Move closer
        name: "Color Choice",
      } satisfies IShoppingMallProductUnit.IUpdate,
    },
    {
      unitId: materialUnit.id,
      update: {
        display_style: "text_input",
        is_required: false, // Make optional
        sort_order: 2,
      } satisfies IShoppingMallProductUnit.IUpdate,
    },
    {
      unitId: styleUnit.id,
      update: {
        is_required: true, // Now required
        is_multiple: false, // Single selection
        sort_order: 1, // Move to top
      } satisfies IShoppingMallProductUnit.IUpdate,
    },
  ];

  // Execute all updates concurrently to simulate bulk operation
  const updatePromises = bulkUpdates.map(({ unitId, update }) =>
    api.functional.shoppingMall.seller.products.units.update(connection, {
      productCode: product.sku,
      unitId,
      body: update,
    }),
  );

  // Execute all updates concurrently
  const updatedUnits: IShoppingMallProductUnit[] =
    await Promise.all(updatePromises);

  // Step 6: Validate that all updates were applied successfully
  for (let i = 0; i < updatedUnits.length; i++) {
    const updatedUnit = updatedUnits[i];
    const updateData = bulkUpdates[i].update;

    // Verify each updated unit
    TestValidator.predicate(
      `unit ${i} updated name correctly`,
      updateData.name
        ? updatedUnit.name === updateData.name
        : updatedUnit.name === updatedUnit.name,
    );
    TestValidator.predicate(
      `unit ${i} updated display style correctly`,
      updateData.display_style
        ? updatedUnit.display_style === updateData.display_style
        : updatedUnit.display_style === updatedUnit.display_style,
    );
    TestValidator.predicate(
      `unit ${i} updated sort order correctly`,
      updateData.sort_order !== undefined
        ? updatedUnit.sort_order === updateData.sort_order
        : updatedUnit.sort_order === updatedUnit.sort_order,
    );
    TestValidator.predicate(
      `unit ${i} updated requirements correctly`,
      updateData.is_required !== undefined
        ? updatedUnit.is_required === updateData.is_required
        : updatedUnit.is_required === updatedUnit.is_required,
    );
    TestValidator.predicate(
      `unit ${i} updated multiple selection correctly`,
      updateData.is_multiple !== undefined
        ? updatedUnit.is_multiple === updateData.is_multiple
        : updatedUnit.is_multiple === updatedUnit.is_multiple,
    );

    // Verify timestamps were updated
    TestValidator.predicate(
      `unit ${i} has updated timestamp`,
      updatedUnit.updated_at !==
        [sizeUnit, colorUnit, materialUnit, styleUnit][i].updated_at,
    );
  }

  // Step 7: Test data integrity with individual update
  const integrityTestUpdate =
    await api.functional.shoppingMall.seller.products.units.update(connection, {
      productCode: product.sku,
      unitId: sizeUnit.id,
      body: {
        name: "Final Size",
        display_style: "dropdown",
        sort_order: 1,
        is_required: true,
      } satisfies IShoppingMallProductUnit.IUpdate,
    });
  typia.assert(integrityTestUpdate);

  // Verify the final state
  TestValidator.equals(
    "size unit final name",
    integrityTestUpdate.name,
    "Final Size",
  );
  TestValidator.equals(
    "size unit final display style",
    integrityTestUpdate.display_style,
    "dropdown",
  );
  TestValidator.equals(
    "size unit final sort order",
    integrityTestUpdate.sort_order,
    1,
  );
  TestValidator.equals(
    "size unit final required status",
    integrityTestUpdate.is_required,
    true,
  );

  // Step 8: Test slow sequential updates vs concurrent bulk updates
  const sequentialStartTime = Date.now();

  // Perform sequential updates for comparison
  for (let i = 0; i < 3; i++) {
    await api.functional.shoppingMall.seller.products.units.update(connection, {
      productCode: product.sku,
      unitId: colorUnit.id,
      body: {
        sort_order: i,
      } satisfies IShoppingMallProductUnit.IUpdate,
    });
  }

  const sequentialEndTime = Date.now();
  const sequentialTime = sequentialEndTime - sequentialStartTime;

  // Concurrent bulk operation timing (already measured above)
  const bulkStartTime = Date.now();

  // Perform concurrent updates for proper bulk operation comparison
  const concurrentPromises = [
    { id: sizeUnit.id, sort_order: 10 },
    { id: materialUnit.id, sort_order: 20 },
    { id: styleUnit.id, sort_order: 30 },
  ].map(({ id, sort_order }) =>
    api.functional.shoppingMall.seller.products.units.update(connection, {
      productCode: product.sku,
      unitId: id,
      body: { sort_order } satisfies IShoppingMallProductUnit.IUpdate,
    }),
  );

  await Promise.all(concurrentPromises);

  const bulkEndTime = Date.now();
  const bulkTime = bulkEndTime - bulkStartTime;

  // Performance comparison - concurrent should be faster
  TestValidator.predicate(
    "concurrent bulk operations faster than sequential",
    bulkTime < sequentialTime,
  );
  TestValidator.predicate(
    "bulk operation performance acceptable",
    bulkTime < 3000,
  ); // Less than 3 seconds

  // Final validation: ensure all units maintain correct relationships
  TestValidator.equals(
    "product sku maintained",
    integrityTestUpdate.product.id,
    product.id,
  );
  TestValidator.predicate(
    "unit types preserved",
    updatedUnits.every((unit) =>
      ["size", "color", "material", "style"].includes(unit.type),
    ),
  );

  // Validate data integrity across all units after bulk operations
  const finalUnits = await Promise.all([
    api.functional.shoppingMall.seller.products.units.update(connection, {
      productCode: product.sku,
      unitId: sizeUnit.id,
      body: { sort_order: 1 } satisfies IShoppingMallProductUnit.IUpdate,
    }),
    api.functional.shoppingMall.seller.products.units.update(connection, {
      productCode: product.sku,
      unitId: colorUnit.id,
      body: { sort_order: 2 } satisfies IShoppingMallProductUnit.IUpdate,
    }),
    api.functional.shoppingMall.seller.products.units.update(connection, {
      productCode: product.sku,
      unitId: materialUnit.id,
      body: { sort_order: 3 } satisfies IShoppingMallProductUnit.IUpdate,
    }),
    api.functional.shoppingMall.seller.products.units.update(connection, {
      productCode: product.sku,
      unitId: styleUnit.id,
      body: { sort_order: 4 } satisfies IShoppingMallProductUnit.IUpdate,
    }),
  ]);

  // Verify final sorted order
  TestValidator.equals(
    "final size unit sort_order",
    finalUnits[0].sort_order,
    1,
  );
  TestValidator.equals(
    "final color unit sort_order",
    finalUnits[1].sort_order,
    2,
  );
  TestValidator.equals(
    "final material unit sort_order",
    finalUnits[2].sort_order,
    3,
  );
  TestValidator.equals(
    "final style unit sort_order",
    finalUnits[3].sort_order,
    4,
  );
}

