            weight_unit: "kg",
            track_quantity: true,
            allow_backorder: false,
            is_shipping_required: true,
            is_taxable: true,
            category_id: typia.random<string & tags.Format<"uuid">>(),
            shopping_mall_seller_id: seller.id,
            href: "https://example.com/products/create",
            referrer: "https://example.com/dashboard",
          } satisfies IShoppingMallProduct.ICreate,
        },
      );
    },
  );

  // Create multiple snapshots per product by updating products
  await ArrayUtil.asyncForEach(products, async (product) => {
    await ArrayUtil.asyncRepeat(2, async () => {
      await api.functional.shoppingMall.seller.products.update(connection, {
        productCode: product.sku,
        body: {
          name: RandomGenerator.name(2),
          description: RandomGenerator.content({
            paragraphs: 2,
            sentenceMin: 5,
            sentenceMax: 10,
          }),
          price: typia.random<
            number &
              tags.Type<"uint32"> &
              tags.Minimum<100> &
              tags.Maximum<10000>
          >(),
        } satisfies IShoppingMallProduct.IUpdate,
      });
      // Small delay to ensure different timestamps
      await new Promise((resolve) => setTimeout(resolve, 100));
    });
  });

  // Test minimum pagination (1 item per page)
  for (const product of products) {
    const minPage = await api.functional.admin.products.snapshots.index(
      connection,
      {
        productCode: product.sku,
        body: {
          page: 1,
          limit: 1,
        } satisfies IShoppingMallProductSnapshot.IRequest,
      },
    );

    TestValidator.equals(
      "minimum page limit is 1",
      minPage.pagination.limit,
      1,
    );
    TestValidator.predicate(
      "minimum page has maximum 1 item",
      minPage.data.length <= 1,
    );

    if (minPage.data.length > 0) {
      typia.assert(minPage.data[0]);
      TestValidator.equals(
        "minimum page data has correct product reference",
        minPage.data[0].sku_code,
        product.sku,
      );
    }
  }

  // Test maximum pagination (100 items per page)
  for (const product of products) {
    const maxPage = await api.functional.admin.products.snapshots.index(
      connection,
      {
        productCode: product.sku,
        body: {
          page: 1,
          limit: 100,
        } satisfies IShoppingMallProductSnapshot.IRequest,
      },
    );

    TestValidator.equals(
      "maximum page limit is 100",
      maxPage.pagination.limit,
      100,
    );
    TestValidator.predicate(
      "maximum page has maximum 100 items",
      maxPage.data.length <= 100,
    );

    // Validate all snapshots in page have correct product reference
    maxPage.data.forEach((snapshot) => {
      typia.assert(snapshot);
      TestValidator.equals(
        "maximum page snapshot has correct product reference",
        snapshot.sku_code,
        product.sku,
      );
    });
  }

  // Test boundary conditions (limits around 100)
  for (const product of products) {
    // Test limit = 99 (just below maximum)
    const page99 = await api.functional.admin.products.snapshots.index(
      connection,
      {
        productCode: product.sku,
        body: {
          page: 1,
          limit: 99,
        } satisfies IShoppingMallProductSnapshot.IRequest,
      },
    );

    TestValidator.equals(
      "boundary page 99 limit is 99",
      page99.pagination.limit,
      99,
    );
    TestValidator.predicate(
      "boundary page 99 has maximum 99 items",
      page99.data.length <= 99,
    );

    // Test limit = 100 (maximum)
    const page100 = await api.functional.admin.products.snapshots.index(
      connection,
      {
        productCode: product.sku,
        body: {
          page: 1,
          limit: 100,
        } satisfies IShoppingMallProductSnapshot.IRequest,
      },
    );

    TestValidator.equals(
      "boundary page 100 limit is 100",
      page100.pagination.limit,
      100,
    );
    TestValidator.predicate(
      "boundary page 100 has maximum 100 items",
      page100.data.length <= 100,
    );
  }

  // Test page correlation and offset calculations
  for (const product of products) {
    // Get all snapshots for comparison
    const allSnapshots = await api.functional.admin.products.snapshots.index(
      connection,
      {
        productCode: product.sku,
        body: {
          page: 1,
          limit: 100,
        } satisfies IShoppingMallProductSnapshot.IRequest,
      },
    );

    if (allSnapshots.data.length > 1) {
      // Test pagination correlation
      const page1 = await api.functional.admin.products.snapshots.index(
        connection,
        {
          productCode: product.sku,
          body: {
            page: 1,
            limit: 1,
          } satisfies IShoppingMallProductSnapshot.IRequest,
        },
      );

      const page2 = await api.functional.admin.products.snapshots.index(
        connection,
        {
          productCode: product.sku,
          body: {
            page: 2,
            limit: 1,
          } satisfies IShoppingMallProductSnapshot.IRequest,
        },
      );

      if (page1.data.length > 0 && page2.data.length > 0) {
        TestValidator.notEquals(
          "pagination page 1 and 2 have different snapshots",
          page1.data[0].id,
          page2.data[0].id,
        );
        TestValidator.notEquals(
          "pagination page 1 and 2 have different timestamps",
          page1.data[0].snapshot_created_at,
          page2.data[0].snapshot_created_at,
        );
      }
    }
  }

  // Test total page count accuracy
  for (const product of products) {
    // Get snapshots with limit 10 to test page count calculation
    const pageWithLimit10 = await api.functional.admin.products.snapshots.index(
      connection,
      {
        productCode: product.sku,
        body: {
          page: 1,
          limit: 10,
        } satisfies IShoppingMallProductSnapshot.IRequest,
      },
    );

    // Get all snapshots to verify total count
    const allSnapshots = await api.functional.admin.products.snapshots.index(
      connection,
      {
        productCode: product.sku,
        body: {
          page: 1,
          limit: 100,
        } satisfies IShoppingMallProductSnapshot.IRequest,
      },
    );

    // Calculate expected page count
    const expectedPages = Math.ceil(allSnapshots.data.length / 10);
    TestValidator.equals(
      "pagination records match total snapshots",
      pageWithLimit10.pagination.records,
      allSnapshots.data.length,
    );
    TestValidator.predicate(
      "pagination pages calculation is correct",
      pageWithLimit10.pagination.pages >= expectedPages,
    );
  }

  // Test data consistency across pagination
  for (const product of products) {
    const limit = 5;
    const page1 = await api.functional.admin.products.snapshots.index(
      connection,
      {
        productCode: product.sku,
        body: {
          page: 1,
          limit: limit,
        } satisfies IShoppingMallProductSnapshot.IRequest,
      },
    );

    if (page1.pagination.pages > 1) {
      const page2 = await api.functional.admin.products.snapshots.index(
        connection,
        {
          productCode: product.sku,
          body: {
            page: 2,
            limit: limit,
          } satisfies IShoppingMallProductSnapshot.IRequest,
        },
      );

      // Ensure no overlapping data between pages
      const page1Ids = new Set(page1.data.map((s) => s.id));
      const page2Ids = new Set(page2.data.map((s) => s.id));

      const overlap = ArrayUtil.has([...page1Ids], (id) => page2Ids.has(id));
      TestValidator.predicate(
        "pagination data consistency - no overlap between pages",
        !overlap,
      );
    }
  }

  // Test edge case: empty results
  for (const product of products) {
    // Request page beyond available data
    const beyondPage = await api.functional.admin.products.snapshots.index(
      connection,
      {
        productCode: product.sku,
        body: {
          page: 999,
          limit: 10,
        } satisfies IShoppingMallProductSnapshot.IRequest,
      },
    );

    TestValidator.equals(
      "beyond page returns no data",
      beyondPage.data.length,
      0,
    );
    TestValidator.predicate(
      "beyond page respects pagination bounds",
      beyondPage.pagination.current <= beyondPage.pagination.pages,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallInventoryStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallInventoryStatus";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductCategory";
import type { IShoppingMallProductImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductImage";
import type { IShoppingMallProductReviewStatistics } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductReviewStatistics";
import type { IShoppingMallProductUnit } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductUnit";
import type { IShoppingMallProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductVariant";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Test seller creation of size-color variant matrices for apparel and fashion
 * products with comprehensive inventory management across all combinations.
 *
 * This test validates:
 *
 * - Variant-specific SKU assignment for size-color combinations
 * - Inventory allocation across all size-color matrix combinations
 * - Price differentiation by size or premium colors
 * - Customer selection interfaces supporting complex fashion catalog requirements
 * - Accurate stock management and fulfillment coordination
 *
 * The test creates a complete fashion product with multi-dimensional variants
 * including standard sizes (S, M, L, XL) and standard colors (red, blue, black)
 * with appropriate inventory tracking and pricing adjustments for different
 * configuration options.
 *
 * Step 1: Seller Registration - Create authenticated seller account Step 2:
 * Base Product Creation - Create product to support variants Step 3: Size Unit
 * Configuration - Configure size selection options Step 4: Color Unit
 * Configuration - Configure color selection options\
 * Step 5: Variant Matrix Creation - Generate all size-color combinations Step
 * 6: Inventory & Pricing Validation - Verify each variant has proper settings
 *
 * Each variant gets unique SKU, proper inventory allocation, and flexible
 * pricing based on size/color premium adjustments with comprehensive
 * marketplace relationship validation.
 */
export async function test_api_seller_variant_creation_size_color_matrix(
  connection: api.IConnection,
) {
  // Step 1: Create seller account for variant creation testing
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const seller = await api.functional.auth.seller.join(connection, {
    body: {
      email: sellerEmail,
      business_name: RandomGenerator.name(2),
      business_registration_number:
        RandomGenerator.alphaNumeric(10).toUpperCase(),
      tax_id: RandomGenerator.alphaNumeric(9),
      phone: RandomGenerator.mobile(),
      business_type: "corporation",
    } satisfies IShoppingMallSeller.IJoin,
  });
  typia.assert(seller);

  // Step 2: Create base fashion product that supports size and color variations
  const baseProductSku = `FASHION-${RandomGenerator.alphaNumeric(8).toUpperCase()}`;
  const product = await api.functional.shoppingMall.seller.products.create(
    connection,
    {
      body: {
        sku: baseProductSku,
        name: "Premium Cotton T-Shirt - Size & Color Variants",
        description: RandomGenerator.content({
          paragraphs: 3,
          sentenceMin: 8,
          sentenceMax: 12,
          wordMin: 4,
          wordMax: 8,
        }),
        price: typia.random<
          number & tags.Type<"uint32"> & tags.Minimum<2000> & tags.Maximum<5000>
        >(),
        condition: "new",
        weight: 0.25,
        weight_unit: "kg",
        track_quantity: true,
        allow_backorder: false,
        is_shipping_required: true,
        is_taxable: true,
        category_id: typia.random<string & tags.Format<"uuid">>(),
        shopping_mall_seller_id: seller.id,
        variants: [],
        images: [],
        href: `https://seller.example.com/products/${baseProductSku}`,
        referrer: "seller-dashboard",
      } satisfies IShoppingMallProduct.ICreate,
    },
  );
  typia.assert(product);

  // Step 3: Configure size product unit for variant creation
  const sizeUnit =
    await api.functional.shoppingMall.seller.products.units.create(connection, {
      productCode: product.sku,
      body: {
        name: "Size",
        type: "size",
        display_style: "dropdown",
        is_required: true,
        is_multiple: false,
        sort_order: 1,
      } satisfies IShoppingMallProductUnit.ICreate,
    });
  typia.assert(sizeUnit);

  // Step 4: Configure color product unit for variant creation
  const colorUnit =
    await api.functional.shoppingMall.seller.products.units.create(connection, {
      productCode: product.sku,
      body: {
        name: "Color",
        type: "color",
        display_style: "swatches",
        is_required: true,
        is_multiple: false,
        sort_order: 2,
      } satisfies IShoppingMallProductUnit.ICreate,
    });
  typia.assert(colorUnit);

  // Step 5: Create size-color variant matrix with comprehensive combinations
  const sizeOptions = ["XS", "S", "M", "L", "XL"] as const;
  const colorOptions = ["Red", "Blue", "Green", "Black", "White"] as const;

  const variants: IShoppingMallProductVariant[] = [];

  // Generate all size-color combinations
  for (let sizeIndex = 0; sizeIndex < sizeOptions.length; sizeIndex++) {
    const size = sizeOptions[sizeIndex];
    for (let colorIndex = 0; colorIndex < colorOptions.length; colorIndex++) {
      const color = colorOptions[colorIndex];
      const variantSku = `${baseProductSku}-${size}-${color}`;
      const position = sizeIndex * colorOptions.length + colorIndex;

      // Use primary unit configuration for variant generation
      const variant =
        await api.functional.shoppingMall.seller.products.variants.create(
          connection,
          {
            productCode: product.sku,
            body: {
              shopping_mall_product_id: product.id,
              shopping_mall_product_unit_id: sizeUnit.id, // Use size unit as primary reference
              sku: variantSku,
              title: `${size} / ${color}`,
              price_adjustment: typia.random<
                number &
                  tags.Type<"int32"> &
                  tags.Minimum<-500> &
                  tags.Maximum<500>
              >(),
              cost_adjustment: 0,
              weight_adjustment: 0,
              inventory_quantity: typia.random<
                number & tags.Type<"int32"> & tags.Minimum<5> & tags.Maximum<50>
              >(),
              inventory_policy: RandomGenerator.pick([
                "deny",
                "continue",
              ] as const),
              position: position,
              is_active: true,
            } satisfies IShoppingMallProductVariant.ICreate,
          },
        );
      typia.assert(variant);
      variants.push(variant);

      // Validate variant relationships and properties
      TestValidator.equals(
        "variant has correct parent product ID",
        variant.shopping_mall_product_id,
        product.id,
      );
      TestValidator.equals(
        "variant SKU contains base product SKU",
        variant.sku.startsWith(baseProductSku),
        true,
      );
      TestValidator.equals(
        "variant title contains size and color",
        variant.title,
        `${size} / ${color}`,
      );
      TestValidator.predicate(
        "variant inventory is positive",
        variant.inventory_quantity > 0,
      );
      TestValidator.predicate(
        "variant position is properly ordered",
        variant.position >= 0,
      );
      TestValidator.predicate(
        "variant has valid inventory policy",
        variant.inventory_policy === "deny" ||
          variant.inventory_policy === "continue",
      );
      TestValidator.equals(
        "variant is active for sale",
        variant.is_active,
        true,
      );
    }
  }

  // Step 6: Validate complete variant matrix and inventory status
  TestValidator.equals(
    "total variant count matches matrix calculation",
    variants.length,
    sizeOptions.length * colorOptions.length,
  );

  // Verify unique SKU enforcement across variants
  const variantSkus = variants.map((v) => v.sku);
  const uniqueSkus = new Set(variantSkus);
  TestValidator.equals(
    "all variant SKUs are unique",
    variantSkus.length === uniqueSkus.size,
    true,
  );

  // Validate comprehensive inventory allocation
  const totalInventory = variants.reduce(
    (sum, v) => sum + v.inventory_quantity,
    0,
  );
  TestValidator.predicate(
    "total inventory exists for matrix",
    totalInventory > 0,
  );

  // Verify pricing differentiation exists
  const priceAdjustments = variants.map((v) => v.price_adjustment);
  TestValidator.predicate(
    "price adjustments vary across variants",
    Math.max(...priceAdjustments) !== Math.min(...priceAdjustments),
  );

  // Validate product relationship and hierarchy integrity
  TestValidator.equals(
    "created variants belong to seller's product",
    seller.id,
    product.seller.id,
  );

  // Test variant-specific display properties and customer interface support
  TestValidator.equals(
    "all variants have display position",
    variants.every((v) => v.position >= 0),
    true,
  );
  TestValidator.equals(
    "variants support required fields for customer selection",
    variants.every((v) => v.title && v.sku && v.inventory_quantity >= 0),
    true,
  );

  // Validate accurate stock management and fulfillment readiness
  TestValidator.predicate(
    "inventory policies are properly distributed",
    variants.some((v) => v.inventory_policy === "deny") &&
      variants.some((v) => v.inventory_policy === "continue"),
  );

  TestValidator.predicate(
    "variants have realistic inventory levels",
    variants.every((v) => v.inventory_quantity >= 0),
  );

  // Final validation: Comprehensive fashion catalog compliance
  TestValidator.predicate(
    "variant matrix covers specific combinations",
    variants.some((v) => v.title.includes("M") && v.title.includes("Blue")),
  );

  TestValidator.predicate(
    "variants support fashion-specific requirements",
    variants.every(
      (v) => v.title && v.sku && typeof v.inventory_quantity === "number",
    ),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallInventoryStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallInventoryStatus";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductCategory";
import type { IShoppingMallProductImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductImage";
import type { IShoppingMallProductReviewStatistics } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductReviewStatistics";
import type { IShoppingMallProductUnit } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductUnit";
import type { IShoppingMallProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductVariant";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Test seller creation of measurement-based product units including length,
 * width, height, weight, capacity, and dimensional variations. Validates
 * measurement unit configuration, display interface optimization, inventory
 * tracking by measurement, and customer selection accuracy for products where
 * dimensional precision is critical for purchase satisfaction and proper fit.
 */
export async function test_api_seller_unit_creation_measurement_variations(
  connection: api.IConnection,
) {
  // 1. Create seller account for measurement-based unit creation
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerData = {
    email: sellerEmail,
    business_name: RandomGenerator.name(2),
    business_registration_number: RandomGenerator.alphaNumeric(12),
    tax_id: RandomGenerator.alphaNumeric(9),
    phone: RandomGenerator.mobile(),
    business_type: "corporation",
  } satisfies IShoppingMallSeller.IJoin;

  const seller = await api.functional.auth.seller.join(connection, {
    body: sellerData,
  });
  typia.assert(seller);

  // 2. Create product requiring measurement-based configuration
  const productCode = `MEASURE-${RandomGenerator.alphaNumeric(8)}`;
  const productData = {
    sku: productCode,
    name: "Premium Customizable Furniture",
    description:
      "High-quality furniture with customizable dimensions and measurement options",
    price: 999.99,
    condition: "new",
    weight: 45.5,
    weight_unit: "kg",
    track_quantity: true,
    allow_backorder: false,
    is_shipping_required: true,
    is_taxable: true,
    category_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_seller_id: seller.id,
    href: `https://marketplace.example.com/products/${productCode}` satisfies string &
      tags.Format<"uri">,
    referrer:
      "https://marketplace.example.com/categories/furniture" satisfies string &
        tags.Format<"uri">,
  } satisfies IShoppingMallProduct.ICreate;

  const product = await api.functional.shoppingMall.seller.products.create(
    connection,
    { body: productData },
  );
  typia.assert(product);

  // 3. Create size measurement unit (dropdown selection)
  const sizeUnitData = {
    name: "Size",
    type: "size",
    display_style: "dropdown",
    is_required: true,
    is_multiple: false,
    sort_order: 1,
  } satisfies IShoppingMallProductUnit.ICreate;

  const sizeUnit =
    await api.functional.shoppingMall.seller.products.units.create(connection, {
      productCode: product.sku,
      body: sizeUnitData,
    });
  typia.assert(sizeUnit);

  // 4. Create length measurement unit (button selection)
  const lengthUnitData = {
    name: "Length",
    type: "size",
    display_style: "buttons",
    is_required: true,
    is_multiple: false,
    sort_order: 2,
  } satisfies IShoppingMallProductUnit.ICreate;

  const lengthUnit =
    await api.functional.shoppingMall.seller.products.units.create(connection, {
      productCode: product.sku,
      body: lengthUnitData,
    });
  typia.assert(lengthUnit);

  // 5. Create weight capacity unit (swatches with multiple selection)
  const capacityUnitData = {
    name: "Load Capacity",
    type: "custom",
    display_style: "swatches",
    is_required: true,
    is_multiple: true,
    sort_order: 3,
  } satisfies IShoppingMallProductUnit.ICreate;

  const capacityUnit =
    await api.functional.shoppingMall.seller.products.units.create(connection, {
      productCode: product.sku,
      body: capacityUnitData,
    });
  typia.assert(capacityUnit);

  // 6. Create optional customization unit (text input)
  const customUnitData = {
    name: "Custom Dimensions",
    type: "custom",
    display_style: "text_input",
    is_required: false,
    is_multiple: true,
    sort_order: 4,
  } satisfies IShoppingMallProductUnit.ICreate;

  const customUnit =
    await api.functional.shoppingMall.seller.products.units.create(connection, {
      productCode: product.sku,
      body: customUnitData,
    });
  typia.assert(customUnit);

  // 7. Validate all measurement units were created correctly
  TestValidator.equals("Size unit type matches", sizeUnit.type, "size");
  TestValidator.equals(
    "Length unit display style",
    lengthUnit.display_style,
    "buttons",
  );
  TestValidator.equals(
    "Capacity unit allows multiple selection",
    capacityUnit.is_multiple,
    true,
  );
  TestValidator.equals(
    "Capacity unit type is custom for load capacity",
    capacityUnit.type,
    "custom",
  );
  TestValidator.equals(
    "Custom unit is optional",
    customUnit.is_required,
    false,
  );
  TestValidator.equals(
    "Custom unit allows text input",
    customUnit.display_style,
    "text_input",
  );

  // 8. Verify unit configuration details
  TestValidator.equals(
    "Units are sorted correctly",
    sizeUnit.sort_order < lengthUnit.sort_order &&
      lengthUnit.sort_order < capacityUnit.sort_order &&
      capacityUnit.sort_order < customUnit.sort_order,
    true,
  );

  // 9. Validate measurement configuration completeness
  const requiredUnits = [sizeUnit, lengthUnit, capacityUnit];
  TestValidator.predicate(
    "All required units are marked as required",
    requiredUnits.every((unit) => unit.is_required === true),
  );

  const multipleSelectionUnits = [capacityUnit, customUnit];
  TestValidator.predicate(
    "Units allowing multiple selection are configured correctly",
    multipleSelectionUnits.every((unit) => unit.is_multiple === true),
  );

  // 10. Test unit display style variations make business sense
  TestValidator.predicate(
    "Dropdown style used for standardized size selection",
    sizeUnit.display_style === "dropdown",
  );

  TestValidator.predicate(
    "Button style used for visual length options",
    lengthUnit.display_style === "buttons",
  );

  TestValidator.predicate(
    "Swatches used for capacity visualization",
    capacityUnit.display_style === "swatches",
  );

  TestValidator.predicate(
