/**
 * Test creation of digital products that do not require physical shipping,
 * validating proper inventory policy settings and non-shipping product
 * characteristics.
 *
 * This test validates the complete digital product creation workflow in the
 * shopping mall marketplace:
 *
 * 1. Create a seller account with comprehensive business information
 * 2. Create a digital product (software, e-book, or service) with
 *    is_shipping_required=false
 * 3. Configure appropriate inventory settings for digital products (no physical
 *    stock tracking)
 * 4. Verify the product is created with correct digital product attributes
 * 5. Validate that shipping-related fields are properly handled for non-physical
 *    items
 * 6. Ensure the product catalog correctly identifies and displays digital products
 *
 * Digital products require special configuration since they don't need physical
 * shipping, warehouse storage, or traditional inventory tracking. This test
 * ensures the API properly handles these distinctions while maintaining product
 * catalog integrity.
 */
export async function test_api_seller_product_creation_digital_product(
  connection: api.IConnection,
) {
  // Step 1: Create seller account with proper business credentials
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const seller = await api.functional.auth.seller.join(connection, {
    body: {
      email: sellerEmail,
      business_name: `${RandomGenerator.name()} Digital Solutions`,
      business_registration_number: RandomGenerator.alphaNumeric(12),
      tax_id: RandomGenerator.alphaNumeric(10),
      phone: RandomGenerator.mobile(),
      business_type: RandomGenerator.pick([
        "corporation",
        "llc",
        "partnership",
      ]),
    } satisfies IShoppingMallSeller.IJoin,
  });
  typia.assert(seller);

  // Step 2: Create a digital product with proper configuration
  const digitalProductData = {
    sku: `DIGITAL-${RandomGenerator.alphaNumeric(8)}`,
    name: `${RandomGenerator.name()} Premium Software License`,
    description: RandomGenerator.content({
      paragraphs: 3,
      sentenceMin: 8,
      sentenceMax: 15,
      wordMin: 4,
      wordMax: 8,
    }),
    price: typia.random<number & tags.Minimum<10> & tags.Maximum<500>>(),
    condition: "new",
    weight: 0, // Digital products have no physical weight
    weight_unit: "kg",
    track_quantity: false, // Digital products don't need inventory tracking
    allow_backorder: true, // Digital products can be delivered instantly
    is_shipping_required: false, // Critical: This is a digital product
    is_taxable: true,
    seo_title: RandomGenerator.paragraph({ sentences: 2 }),
    seo_description: RandomGenerator.paragraph({ sentences: 4 }),
    tags: "digital,software,license,download",
    category_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_seller_id: seller.id,
    href: "https://shopping-mall.local/seller/products/create",
    referrer: "https://shopping-mall.local/seller/dashboard",
  } satisfies IShoppingMallProduct.ICreate;

  const digitalProduct =
    await api.functional.shoppingMall.seller.products.create(connection, {
      body: digitalProductData,
    });
  typia.assert(digitalProduct);

  // Step 3: Validate digital product characteristics
  TestValidator.equals(
    "digital product SKU matches",
    digitalProduct.sku,
    digitalProductData.sku,
  );
  TestValidator.equals(
    "digital product name matches",
    digitalProduct.name,
    digitalProductData.name,
  );
  TestValidator.equals(
    "digital product price matches",
    digitalProduct.price,
    digitalProductData.price,
  );
  TestValidator.equals(
    "is_shipping_required is false for digital product",
    digitalProduct.is_shipping_required,
    false,
  );
  TestValidator.equals(
    "track_quantity is false for digital product",
    digitalProduct.track_quantity,
    false,
  );
  TestValidator.equals(
    "allow_backorder is true for digital product",
    digitalProduct.allow_backorder,
    true,
  );
  TestValidator.equals(
    "weight is 0 for digital product",
    digitalProduct.weight,
    0,
  );
  TestValidator.equals(
    "seller relationship established",
    digitalProduct.seller.id,
    seller.id,
  );

  // Step 4: Validate that digital product has proper inventory settings
  TestValidator.predicate(
    "digital product has inventory status",
    digitalProduct.inventory_status !== null &&
      typeof digitalProduct.inventory_status === "object",
  );
  TestValidator.predicate(
    "digital product has review statistics",
    digitalProduct.reviews !== null &&
      typeof digitalProduct.reviews === "object",
  );

  // Step 5: Validate product category assignment
  TestValidator.predicate(
    "digital product has valid category",
    digitalProduct.category.id !== null &&
      digitalProduct.category.name.length > 0,
  );

  // Step 6: Test additional digital product scenarios with different categories
  const softwareProductData = {
    ...digitalProductData,
    sku: `SOFTWARE-${RandomGenerator.alphaNumeric(8)}`,
    name: `${RandomGenerator.name()} Professional Software Suite`,
    description: RandomGenerator.content({
      paragraphs: 2,
      sentenceMin: 6,
      sentenceMax: 12,
    }),
    price: typia.random<number & tags.Minimum<50> & tags.Maximum<1000>>(),
  } satisfies IShoppingMallProduct.ICreate;

  const softwareProduct =
    await api.functional.shoppingMall.seller.products.create(connection, {
      body: softwareProductData,
    });
  typia.assert(softwareProduct);

  TestValidator.equals(
    "software product has correct shipping setting",
    softwareProduct.is_shipping_required,
    false,
  );
  TestValidator.equals(
    "software product has zero weight",
    softwareProduct.weight,
    0,
  );
  TestValidator.equals(
    "software product allows backorder",
    softwareProduct.allow_backorder,
    true,
  );

  // Step 7: Test digital service product
  const serviceProductData = {
    ...digitalProductData,
    sku: `SERVICE-${RandomGenerator.alphaNumeric(8)}`,
    name: `${RandomGenerator.name()} Online Training Course`,
    description: RandomGenerator.content({
      paragraphs: 4,
      sentenceMin: 10,
      sentenceMax: 18,
    }),
    price: typia.random<number & tags.Minimum<25> & tags.Maximum<300>>(),
  } satisfies IShoppingMallProduct.ICreate;

  const serviceProduct =
    await api.functional.shoppingMall.seller.products.create(connection, {
      body: serviceProductData,
    });
  typia.assert(serviceProduct);

  TestValidator.equals(
    "service product has correct shipping setting",
    serviceProduct.is_shipping_required,
    false,
  );
  TestValidator.equals(
    "service product has zero weight",
    serviceProduct.weight,
    0,
  );
  TestValidator.equals(
    "service product doesn't track quantity",
    serviceProduct.track_quantity,
    false,
