      "corporation",
      "llc",
      "partnership",
      "sole proprietorship",
    ]),
  } satisfies IShoppingMallSeller.IJoin;

  const seller = await api.functional.auth.seller.join(connection, {
    body: sellerData,
  });
  typia.assert(seller);
  TestValidator.equals(
    "seller created successfully",
    seller.id.length > 0,
