  TestValidator.equals(
    "medium polyester price adjustment matches input",
    mediumRedPolyester.price_adjustment,
    8,
  );
  TestValidator.equals(
    "small leather inventory policy is deny",
    smallGreenLeather.inventory_policy,
    "deny",
