    await api.functional.shoppingMall.seller.products.units.create(connection, {
      productCode: product.sku,
      body: unitVariant2,
    });

  typia.assert(storageUnit);

  // Step 4: Create variants with comprehensive barcode integration
  const variants = [
    {
      shopping_mall_product_id: product.id,
      shopping_mall_product_unit_id: colorUnit.id,
      sku: `VAR-${product.sku}-BLACK-64GB`,
      title: "Matte Black, 64GB Storage",
      price_adjustment: 0,
      inventory_quantity: 50,
      inventory_policy: "deny",
      position: 1,
      is_active: true,
      barcode: `850${typia.random<string & tags.Pattern<"^[0-9]{9,11}$">>()}`, // UPC-A format
      image: "https://storage.example.com/images/headphones-black.jpg",
      weight_adjustment: 0,
      cost_adjustment: 0,
    } satisfies IShoppingMallProductVariant.ICreate,
    {
      shopping_mall_product_id: product.id,
      shopping_mall_product_unit_id: colorUnit.id,
      sku: `VAR-${product.sku}-WHITE-128GB`,
      title: "Pearl White, 128GB Storage",
      price_adjustment: 50.0, // Premium variant with higher storage
      inventory_quantity: 30,
      inventory_policy: "continue", // Allow backorders for premium variant
      position: 2,
      is_active: true,
      barcode: `850${typia.random<string & tags.Pattern<"^[0-9]{9,11}$">>()}`, // Different barcode
      image: "https://storage.example.com/images/headphones-white.jpg",
      weight_adjustment: 0.02, // Slight weight increase
      cost_adjustment: 45.0, // Cost difference for premium
    } satisfies IShoppingMallProductVariant.ICreate,
    {
      shopping_mall_product_id: product.id,
      shopping_mall_product_unit_id: storageUnit.id, // Link to storage unit instead
      sku: `VAR-${product.sku}-SILVER-256GB`,
      title: "Silver Pro Edition",
      price_adjustment: 150.0, // High-end pro variant
      inventory_quantity: 15,
      inventory_policy: "continue",
      position: 3,
      is_active: true,
      barcode: `87${typia.random<string & tags.Pattern<"^[0-9]{10}$">>()}`, // EAN-13 format
      image: "https://storage.example.com/images/headphones-silver.jpg",
      weight_adjustment: 0.05, // Additional weight for pro components
      cost_adjustment: 120.0, // Significant cost difference
    } satisfies IShoppingMallProductVariant.ICreate,
  ];

  // Store created variants for validation
  const createdVariants: IShoppingMallProductVariant[] = [];

  // Create each variant with barcode integration
  for (const variantData of variants) {
    const variant =
      await api.functional.shoppingMall.seller.products.variants.create(
        connection,
        {
          productCode: product.sku,
          body: variantData,
        },
      );
    typia.assert(variant);
    createdVariants.push(variant);

    // Validate variant properties
    TestValidator.equals("variant SKU matches", variant.sku, variantData.sku);
    TestValidator.equals(
      "variant title matches",
      variant.title,
      variantData.title,
    );
    TestValidator.equals(
      "variant price adjustment",
      variant.price_adjustment,
      variantData.price_adjustment,
    );
    TestValidator.equals(
      "variant inventory quantity",
      variant.inventory_quantity,
      variantData.inventory_quantity,
    );
    TestValidator.equals(
      "variant inventory policy",
      variant.inventory_policy,
      variantData.inventory_policy,
    );
    TestValidator.equals(
      "variant position",
      variant.position,
      variantData.position,
    );
    TestValidator.equals(
      "variant is active",
      variant.is_active,
      variantData.is_active,
    );
    TestValidator.notEquals("variant barcode exists", variant.barcode, null);
    TestValidator.notEquals("variant barcode empty", variant.barcode, "");
    TestValidator.predicate(
      "variant barcode starts with valid prefix",
      variant.barcode!.startsWith("850") ||
        variant.barcode!.startsWith("87") ||
        variant.barcode!.startsWith("73"),
    );

    // Validate barcode uniqueness across variants
    const otherVariants = createdVariants.filter((v) => v.id !== variant.id);
    TestValidator.predicate(
      "barcode is unique",
      otherVariants.every((v) => v.barcode !== variant.barcode),
    );
  }

  // Step 5: Validate retail marketplace integration features
  TestValidator.equals("total variants created", createdVariants.length, 3);

  // Validate SKU structure and consistency
  createdVariants.forEach((variant, index) => {
    TestValidator.predicate(
      `variant ${index + 1} SKU contains product code`,
      variant.sku.includes(product.sku),
    );
    TestValidator.predicate(
      `variant ${index + 1} SKU follows pattern`,
      variant.sku.startsWith(`VAR-${product.sku}`),
    );
  });

  // Validate inventory management integration
  const totalInventory = createdVariants.reduce(
    (sum, variant) => sum + variant.inventory_quantity,
    0,
  );
  TestValidator.equals("total inventory across variants", totalInventory, 95);

  // Validate price differentiation strategy
  TestValidator.predicate(
    "price adjustments increase with premium features",
    () => {
      const adjustments = createdVariants
        .map((v) => v.price_adjustment)
        .sort((a, b) => a - b);
      return (
        adjustments[0] <= adjustments[1] && adjustments[1] <= adjustments[2]
      );
    },
  );

  // Validate retail barcode formats
  createdVariants.forEach((variant, index) => {
    const barcode = variant.barcode!;
    TestValidator.predicate(
      `variant ${index + 1} barcode is numeric`,
      /^\d+$/.test(barcode),
    );
    TestValidator.predicate(
      `variant ${index + 1} barcode has valid length`,
      barcode.length >= 8 && barcode.length <= 13,
    );
  });

  // Step 6: Test retail-specific scenarios
  TestValidator.predicate("variants support POS integration", () =>
    createdVariants.every((variant) => variant.barcode && variant.sku),
  );

  TestValidator.predicate("variants enable warehouse scanning", () =>
    createdVariants.every(
      (variant) =>
        variant.inventory_policy === "deny" ||
        variant.inventory_policy === "continue",
    ),
  );

  TestValidator.predicate("variants provide inventory tracking", () =>
    createdVariants.every((variant) => variant.inventory_quantity >= 0),
  );

  TestValidator.predicate("variants support supply chain coordination", () =>
    createdVariants.every((variant) => variant.is_active === true),
  );

  // Validate proper unit associations
  TestValidator.equals(
    "variants linked to different units",
    new Set(createdVariants.map((v) => v.shopping_mall_product_unit_id)).size,
    2,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallInventoryStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallInventoryStatus";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductCategory";
import type { IShoppingMallProductImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductImage";
import type { IShoppingMallProductReviewStatistics } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductReviewStatistics";
import type { IShoppingMallProductUnit } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductUnit";
import type { IShoppingMallProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductVariant";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Test seller product creation with comprehensive variant management
 *
 * This test validates the complete product creation workflow with variant
 * support:
 *
 * 1. Seller registration and authentication setup
 * 2. Create base product with comprehensive details
 * 3. Configure product units for variant differentiation (size, color, material)
 * 4. Validate SKU assignment strategy and inventory tracking
 * 5. Test pricing differentiation across variants
 * 6. Verify customer choice optimization and inventory accuracy
 *
 * Note: Due to system constraints, we focus on unit configuration and
 * validation rather than full variant instance creation, as the latter requires
 * additional system components not available in this test environment.
 */
export async function test_api_seller_product_creation_with_variants(
  connection: api.IConnection,
) {
  // 1. Create seller account for product management
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const seller = await api.functional.auth.seller.join(connection, {
    body: {
      email: sellerEmail,
      business_name: RandomGenerator.name() + " Store",
      business_registration_number: RandomGenerator.alphabets(10).toUpperCase(),
      tax_id: RandomGenerator.alphabets(9).toUpperCase(),
      phone: RandomGenerator.mobile(),
      business_type: RandomGenerator.pick([
        "corporation",
        "sole proprietorship",
        "partnership",
      ] as const),
    } satisfies IShoppingMallSeller.IJoin,
  });
  typia.assert(seller);

  // 2. Create variant-ready product with comprehensive configuration
  const productSku = "SKU-" + RandomGenerator.alphabets(8).toUpperCase();
  const baseProduct = await api.functional.shoppingMall.seller.products.create(
    connection,
    {
      body: {
        sku: productSku,
        name: RandomGenerator.name() + " Premium T-Shirt",
        description: RandomGenerator.content({
          paragraphs: 3,
          sentenceMin: 10,
          sentenceMax: 20,
        }),
        price: typia.random<
          number & tags.Type<"uint32"> & tags.Minimum<20> & tags.Maximum<200>
        >(),
        compare_at_price: null,
        cost: typia.random<
          number & tags.Type<"uint32"> & tags.Minimum<10> & tags.Maximum<100>
        >(),
        condition: "new",
        weight: typia.random<
          number & tags.Type<"uint32"> & tags.Minimum<0> & tags.Maximum<5>
        >(),
        weight_unit: "kg",
        barcode: null,
        track_quantity: true,
        allow_backorder: false,
        is_shipping_required: true,
        is_taxable: true,
        seo_title: RandomGenerator.paragraph({ sentences: 1 }),
        seo_description: RandomGenerator.paragraph({ sentences: 2 }),
        tags: RandomGenerator.paragraph({ sentences: 3 }),
        featured_image: null,
        category_id: "00000000-0000-0000-0000-000000000000", // Using placeholder since category system not available
        shopping_mall_seller_id: seller.id,
        variants: [], // Will be populated by variant creation in real system
        images: [
          {
            name: "main-image.jpg",
            extension: "jpg",
            url: "https://example.com/product-main.jpg",
          } satisfies IShoppingMallProductImage.ICreate,
        ],
        ip: null,
        href: "https://seller-portal.example.com/products/new",
        referrer: "https://seller-portal.example.com/dashboard",
      } satisfies IShoppingMallProduct.ICreate,
    },
  );
  typia.assert(baseProduct);

  TestValidator.equals(
    "product creation success",
    baseProduct.seller.id,
    seller.id,
  );
  TestValidator.equals("product SKU matches", baseProduct.sku, productSku);
  TestValidator.predicate(
    "product has inventory tracking enabled",
    baseProduct.track_quantity === true,
  );
  TestValidator.predicate(
    "product allows no backorder",
    baseProduct.allow_backorder === false,
  );

  // 3. Create comprehensive unit system for variant differentiation

  // Size unit for basic variant differentiation
  const sizeUnit =
    await api.functional.shoppingMall.seller.products.units.create(connection, {
      productCode: baseProduct.sku,
      body: {
        name: "Size",
        type: "size",
        display_style: "dropdown",
        is_required: true,
        is_multiple: false,
        sort_order: 1,
      } satisfies IShoppingMallProductUnit.ICreate,
    });
  typia.assert(sizeUnit);

  TestValidator.equals("size unit name matches", sizeUnit.name, "Size");
  TestValidator.equals("size unit type matches", sizeUnit.type, "size");
  TestValidator.predicate(
    "size unit is required",
    sizeUnit.is_required === true,
  );

  // Color unit for visual variant differentiation
  const colorUnit =
    await api.functional.shoppingMall.seller.products.units.create(connection, {
      productCode: baseProduct.sku,
      body: {
        name: "Color",
        type: "color",
        display_style: "swatches",
        is_required: true,
        is_multiple: false,
        sort_order: 2,
      } satisfies IShoppingMallProductUnit.ICreate,
    });
  typia.assert(colorUnit);

  TestValidator.equals("color unit name matches", colorUnit.name, "Color");
  TestValidator.equals("color unit type matches", colorUnit.type, "color");
  TestValidator.equals(
    "color unit display style",
    colorUnit.display_style,
    "swatches",
  );

  // Material unit for premium differentiation
  const materialUnit =
    await api.functional.shoppingMall.seller.products.units.create(connection, {
      productCode: baseProduct.sku,
      body: {
        name: "Material",
        type: "material",
        display_style: "buttons",
        is_required: false,
        is_multiple: false,
        sort_order: 3,
      } satisfies IShoppingMallProductUnit.ICreate,
    });
  typia.assert(materialUnit);

  TestValidator.equals(
    "material unit name matches",
    materialUnit.name,
    "Material",
  );
  TestValidator.equals(
    "material unit type matches",
    materialUnit.type,
    "material",
  );
  TestValidator.predicate(
    "material unit is optional",
    materialUnit.is_required === false,
  );

  // 4. Validate SKU assignment strategy uniqueness
  const duplicateSkuTest = productSku + "-COPY";
  await TestValidator.error("duplicate SKU should be rejected", async () => {
    await api.functional.shoppingMall.seller.products.create(connection, {
      body: {
        sku: duplicateSkuTest,
        name: "Duplicate SKU Test",
        description: "Testing SKU uniqueness validation",
        price: 99.99,
        condition: "new",
        weight: 0.5,
        weight_unit: "kg",
        track_quantity: true,
        allow_backorder: false,
        is_shipping_required: true,
        is_taxable: true,
        category_id: "00000000-0000-0000-0000-000000000000",
        shopping_mall_seller_id: seller.id,
        href: "https://seller-portal.example.com/products/duplicate",
        referrer: "https://seller-portal.example.com/products",
        ip: null,
      } satisfies IShoppingMallProduct.ICreate,
    });
  });

  // 5. Validate unit configuration relationships
  TestValidator.predicate(
    "all units belong to same product",
    sizeUnit.product.id === baseProduct.id &&
      colorUnit.product.id === baseProduct.id &&
      materialUnit.product.id === baseProduct.id,
  );

  TestValidator.predicate(
    "units have correct sort order",
    sizeUnit.sort_order < colorUnit.sort_order &&
      colorUnit.sort_order < materialUnit.sort_order,
  );

  // 6. Validate seller authorization system
  TestValidator.predicate(
    "seller has valid authorization",
    seller.token !== undefined && seller.token.access.length > 0,
  );

  TestValidator.equals(
    "seller business type is valid",
    seller.business_type,
    RandomGenerator.pick([
      "corporation",
      "sole proprietorship",
      "partnership",
    ] as const),
  );

  // 7. Business logic validation for variant system optimization
  TestValidator.predicate(
    "unit system supports customer choice hierarchy",
    sizeUnit.is_required === true &&
      colorUnit.is_required === true &&
      materialUnit.is_required === false,
  );

  TestValidator.predicate(
    "display styles enhance user decision flow",
    sizeUnit.display_style === "dropdown" &&
      colorUnit.display_style === "swatches" &&
      materialUnit.display_style === "buttons",
  );

  // 8. Validate inventory accuracy principles
  TestValidator.predicate(
    "product enables comprehensive inventory tracking",
    baseProduct.track_quantity === true &&
      baseProduct.allow_backorder === false,
  );

  TestValidator.predicate(
    "variant-ready product supports multiple configurations",
    baseProduct.variants.length === 0 && // Initial product has empty variants array
      sizeUnit.is_multiple === false &&
      colorUnit.is_multiple === false &&
      materialUnit.is_multiple === false,
  );

  // 9. Validate customer experience optimization
  TestValidator.predicate(
    "unit sort order optimizes selection flow (required first)",
    sizeUnit.sort_order === 1 &&
      colorUnit.sort_order === 2 &&
      materialUnit.sort_order === 3,
  );

  TestValidator.predicate(
    "display styles align with unit characteristics",
    sizeUnit.type === "size" &&
      sizeUnit.display_style === "dropdown" &&
      colorUnit.type === "color" &&
      colorUnit.display_style === "swatches" &&
      materialUnit.type === "material" &&
      materialUnit.display_style === "buttons",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallInventoryStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallInventoryStatus";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductCategory";
import type { IShoppingMallProductImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductImage";
import type { IShoppingMallProductReviewStatistics } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductReviewStatistics";
import type { IShoppingMallProductUnit } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductUnit";
import type { IShoppingMallProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductVariant";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Test creation of premium product variants with enhanced pricing, superior
 * materials, advanced features, and luxury positioning strategies. Validates
 * that sellers can effectively differentiate product tiers through
 * variant-specific pricing, inventory policies, and customer targeting while
 * maintaining competitive marketplace positioning and profit optimization
 * across variant configurations.
 */
export async function test_api_seller_variant_creation_premium_configs(
  connection: api.IConnection,
) {
  // Step 1: Register seller account with comprehensive business information
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const seller = await api.functional.auth.seller.join(connection, {
    body: {
      email: sellerEmail,
      business_name: RandomGenerator.name(3),
      business_registration_number: RandomGenerator.alphaNumeric(10),
      tax_id: RandomGenerator.alphaNumeric(9),
      phone: RandomGenerator.mobile("010"),
      business_type: "corporation",
    } satisfies IShoppingMallSeller.IJoin,
  });
  typia.assert(seller);

  // Step 2: Create base product suitable for premium variant differentiation
  const baseProduct = await api.functional.shoppingMall.seller.products.create(
    connection,
    {
      body: {
        sku: `PREMIUM-${RandomGenerator.alphaNumeric(8)}`,
        name: "Luxury Premium Smartwatch Series",
        description: RandomGenerator.content({
          paragraphs: 3,
          sentenceMin: 8,
          sentenceMax: 15,
        }),
        price: 299.99,
        condition: "new",
        weight: 0.08,
        weight_unit: "kg",
        track_quantity: true,
        allow_backorder: false,
        is_shipping_required: true,
        is_taxable: true,
        category_id: seller.id, // Using seller ID as valid UUID for category
        shopping_mall_seller_id: seller.id,
        seo_title: "Premium Luxury Smartwatch - Advanced Technology",
        seo_description: RandomGenerator.paragraph({ sentences: 6 }),
        tags: "luxury, premium, smartwatch, technology, fitness, health",
        featured_image: null,
        href: "https://marketplace.example.com/seller/products/create",
        referrer: "https://marketplace.example.com/seller/dashboard",
      } satisfies IShoppingMallProduct.ICreate,
    },
  );
  typia.assert(baseProduct);

  // Step 3: Create product units for premium variant differentiation
  // Size unit configuration
  const sizeUnit =
    await api.functional.shoppingMall.seller.products.units.create(connection, {
      productCode: baseProduct.sku,
      body: {
        name: "Size",
        type: "size",
        display_style: "dropdown",
        is_required: true,
        is_multiple: false,
        sort_order: 1,
      } satisfies IShoppingMallProductUnit.ICreate,
    });
  typia.assert(sizeUnit);

  // Material unit configuration
  const materialUnit =
    await api.functional.shoppingMall.seller.products.units.create(connection, {
      productCode: baseProduct.sku,
      body: {
        name: "Material",
        type: "material",
        display_style: "buttons",
        is_required: true,
        is_multiple: false,
        sort_order: 2,
      } satisfies IShoppingMallProductUnit.ICreate,
    });
  typia.assert(materialUnit);

  // Features unit for luxury enhancements
  const featuresUnit =
    await api.functional.shoppingMall.seller.products.units.create(connection, {
      productCode: baseProduct.sku,
      body: {
        name: "Premium Features",
        type: "style",
        display_style: "buttons",
        is_required: true,
        is_multiple: true,
        sort_order: 3,
      } satisfies IShoppingMallProductUnit.ICreate,
    });
  typia.assert(featuresUnit);

  // Step 4: Create premium variants with different pricing strategies

  // Standard Premium Variant - Titanium Material
  const titaniumVariant =
    await api.functional.shoppingMall.seller.products.variants.create(
      connection,
      {
        productCode: baseProduct.sku,
        body: {
          shopping_mall_product_id: baseProduct.id,
          shopping_mall_product_unit_id: materialUnit.id,
          sku: `${baseProduct.sku}-TITANIUM`,
          title: "Premium - Titanium Build, Advanced Health Tracking",
          price_adjustment: 150.0, // +$150 for premium materials
          cost_adjustment: 85.0, // Higher material costs
          weight_adjustment: 0.02, // Slightly heavier titanium
          barcode: `PREM${RandomGenerator.alphaNumeric(10)}`,
          image: null,
          inventory_quantity: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<50> & tags.Maximum<200>
          >(),
          inventory_policy: "deny",
          position: 1,
          is_active: true,
        } satisfies IShoppingMallProductVariant.ICreate,
      },
    );
  typia.assert(titaniumVariant);

  // Luxury Elite Variant - Platinum with Diamond Accent
  const platinumVariant =
    await api.functional.shoppingMall.seller.products.variants.create(
      connection,
      {
        productCode: baseProduct.sku,
        body: {
          shopping_mall_product_id: baseProduct.id,
          shopping_mall_product_unit_id: materialUnit.id,
          sku: `${baseProduct.sku}-PLATINUM`,
          title: "Elite - Platinum Edition, Diamond Accent, Concierge Service",
          price_adjustment: 450.0, // +$450 for luxury positioning
          cost_adjustment: 280.0, // Significantly higher luxury costs
          weight_adjustment: 0.05, // Premium materials add weight
          barcode: `LUX${RandomGenerator.alphaNumeric(10)}`,
          image: null,
          inventory_quantity: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<10> & tags.Maximum<50>
          >(), // Limited luxury inventory
          inventory_policy: "deny",
          position: 0, // Highlight at top
          is_active: true,
        } satisfies IShoppingMallProductVariant.ICreate,
      },
    );
  typia.assert(platinumVariant);

  // Enhanced Features Variant - All Premium Add-ons
  const enhancedFeaturesVariant =
    await api.functional.shoppingMall.seller.products.variants.create(
      connection,
      {
        productCode: baseProduct.sku,
        body: {
          shopping_mall_product_id: baseProduct.id,
          shopping_mall_product_unit_id: featuresUnit.id,
          sku: `${baseProduct.sku}-ENHANCED`,
          title:
            "Enhanced - Full Feature Package, Lifetime Warranty, VIP Support",
          price_adjustment: 200.0, // +$200 for feature premium
          cost_adjustment: 120.0, // Higher support and warranty costs
          weight_adjustment: 0.01, // Minimal additional components weight
          barcode: `ENH${RandomGenerator.alphaNumeric(10)}`,
          image: null,
          inventory_quantity: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<25> & tags.Maximum<100>
          >(),
          inventory_policy: "deny",
          position: 2,
          is_active: true,
        } satisfies IShoppingMallProductVariant.ICreate,
      },
    );
  typia.assert(enhancedFeaturesVariant);

  // Step 5: Validate premium variant creation and pricing strategy
  TestValidator.equals("seller verification status", seller.is_verified, true);
  TestValidator.equals("base product status", baseProduct.status, "active");
  TestValidator.equals(
    "base product price strategy",
    baseProduct.price,
    299.99,
  );

  // Validate variant-specific pricing and positioning
  TestValidator.equals(
    "titanium variant price adjustment",
    titaniumVariant.price_adjustment,
    150.0,
