        weight: typia.random<number & tags.Minimum<0.1> & tags.Maximum<10>>(),
        weight_unit: "kg",
        track_quantity: true,
        allow_backorder: false,
        is_shipping_required: true,
        is_taxable: true,
        category_id: typia.random<string & tags.Format<"uuid">>(),
        shopping_mall_seller_id: seller.id,
        href: "https://example.com/dashboard/products/new",
        referrer: "https://example.com/products",
      } satisfies IShoppingMallProduct.ICreate,
    },
  );
  typia.assert(product);

  // Step 3: Create dropdown unit for size selection with optimized display
  const sizeUnit =
    await api.functional.shoppingMall.seller.products.units.create(connection, {
      productCode: product.sku,
      body: {
        name: "Size",
        type: RandomGenerator.pick(["size", "dimension", "custom"]),
        display_style: "dropdown",
        is_required: true,
        is_multiple: false,
        sort_order: 1,
      } satisfies IShoppingMallProductUnit.ICreate,
    });
  typia.assert(sizeUnit);

  // Step 4: Create button unit for color selection with visual arrangement
  const colorUnit =
    await api.functional.shoppingMall.seller.products.units.create(connection, {
      productCode: product.sku,
      body: {
        name: "Color",
        type: RandomGenerator.pick(["color", "custom"]),
        display_style: "buttons",
        is_required: true,
        is_multiple: false,
        sort_order: 2,
      } satisfies IShoppingMallProductUnit.ICreate,
    });
  typia.assert(colorUnit);

  // TestValidator for button arrangement accessibility
  await TestValidator.predicate(
    "color unit has proper accessibility support",
    colorUnit.name.length >= 3 && colorUnit.name.length <= 50,
  );

  // Step 5: Create swatch unit for material selection with visual samples
  const materialUnit =
    await api.functional.shoppingMall.seller.products.units.create(connection, {
      productCode: product.sku,
      body: {
        name: "Material",
        type: RandomGenerator.pick(["material", "texture", "fabric", "custom"]),
        display_style: "swatches",
        is_required: false,
        is_multiple: false,
        sort_order: 3,
      } satisfies IShoppingMallProductUnit.ICreate,
    });
  typia.assert(materialUnit);

  // Step 6: Create text input unit for custom dimensions (mobile-optimized)
  const customUnit =
    await api.functional.shoppingMall.seller.products.units.create(connection, {
      productCode: product.sku,
      body: {
        name: "Custom Dimensions",
        type: RandomGenerator.pick(["size", "dimension", "custom"]),
        display_style: "text_input",
        is_required: false,
        is_multiple: true,
        sort_order: 4,
      } satisfies IShoppingMallProductUnit.ICreate,
    });
  typia.assert(customUnit);

  // Validate display optimization features
  await TestValidator.predicate(
    "size unit uses dropdown for compact mobile display",
    sizeUnit.display_style === "dropdown",
  );
  await TestValidator.predicate(
    "color unit uses buttons for quick visual selection",
    colorUnit.display_style === "buttons",
  );
  await TestValidator.predicate(
    "material unit uses swatches for tactile visualization",
    materialUnit.display_style === "swatches",
  );
  await TestValidator.predicate(
    "custom unit supports multiple inputs for complex specifications",
    customUnit.is_multiple === true,
  );

  // Validate sort order optimization
  await TestValidator.predicate(
    "units are ordered by conversion priority",
    sizeUnit.sort_order < colorUnit.sort_order &&
      colorUnit.sort_order < materialUnit.sort_order &&
      materialUnit.sort_order < customUnit.sort_order,
  );

  // Validate accessibility compliance
  await TestValidator.predicate(
    "all unit names meet accessibility guidelines",
    sizeUnit.name.length >= 2 &&
      sizeUnit.name.length <= 100 &&
      colorUnit.name.length >= 2 &&
      colorUnit.name.length <= 100 &&
      materialUnit.name.length >= 2 &&
      materialUnit.name.length <= 100 &&
      customUnit.name.length >= 2 &&
      customUnit.name.length <= 100,
  );

  // Validate conversion optimization logic
  await TestValidator.predicate(
    "most important selection (size) is required",
    sizeUnit.is_required === true,
  );
  await TestValidator.predicate(
    "visual elements are prioritized for mobile experience",
    (colorUnit.display_style === "buttons" ||
      colorUnit.display_style === "swatches") &&
      (materialUnit.display_style === "buttons" ||
        materialUnit.display_style === "swatches"),
  );

  // Validate mobile-first display characteristics
  await TestValidator.predicate(
    "dropdown selection minimizes screen real estate",
    sizeUnit.display_style === "dropdown" && sizeUnit.is_multiple === false,
  );
  await TestValidator.predicate(
    "button selection enables quick visual decisions",
    colorUnit.display_style === "buttons",
  );
  await TestValidator.predicate(
    "swatch selection provides tactile material representation",
    materialUnit.display_style === "swatches",
  );

  // Verify accessibility and usability standards
  await TestValidator.predicate(
    "unit configurations support screen reader compatibility",
    colorUnit.name.length <= 100 && materialUnit.name.length <= 100,
  );

  // Validate business optimization throughput
  await TestValidator.predicate(
    "high-conversion items require user selection",
    sizeUnit.is_required === true && colorUnit.is_required === true,
  );

  await TestValidator.predicate(
    "optional customization maintains shopping flow",
    materialUnit.is_required === false && customUnit.is_required === false,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallPaymentTransaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallPaymentTransaction";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallOrderPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderPayment";
import type { IShoppingMallPaymentGateway } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPaymentGateway";
import type { IShoppingMallPaymentMethod } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPaymentMethod";
import type { IShoppingMallPaymentTransaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPaymentTransaction";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Test basic payment transaction filtering functionality where an admin
 * searches for transactions within a specific date range and amount threshold.
 * Validates that the filtering system correctly applies search criteria and
 * returns paginated results with proper transaction summaries including gateway
 * information, payment method details, and processing status.
 */
export async function test_api_admin_payment_transaction_filtering_basic(
  connection: api.IConnection,
) {
  //Step 1: Create admin account for authentication to access payment transaction data
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      firstname: RandomGenerator.name(1),
      lastname: RandomGenerator.name(1),
      adminlevel: RandomGenerator.pick([
        "super_admin",
        "department_admin",
        "support_admin",
        "viewer",
      ] as const),
      department: "Finance",
    } satisfies IShoppingMallAdmin.ICreate,
  });
  typia.assert(admin);

  const startDate: string = new Date(
    Date.now() - 7 * 24 * 60 * 60 * 1000,
  ).toISOString(); // 7 days ago
  const endDate: string = new Date().toISOString(); // current time
  const minAmount: number = 50.0;
  const maxAmount: number = 500.0;

  //Step 2: Test transaction filtering with date range and amount threshold
  const requestBody: IShoppingMallPaymentTransaction.IRequest = {
    page: 1,
    limit: 20,
    created_at_start: startDate,
    created_at_end: endDate,
    amount_min: minAmount,
    amount_max: maxAmount,
  } satisfies IShoppingMallPaymentTransaction.IRequest;

  const response =
    await api.functional.shoppingMall.admin.paymentTransactions.index(
      connection,
      {
        body: requestBody,
      },
    );

  typia.assert(response);

  //Step 3: validate response structure and pagination
  TestValidator.predicate(
    "pagination exists",
    response.pagination !== undefined && response.pagination !== null,
  );
  TestValidator.equals("pagination page", response.pagination.current, 1);
  TestValidator.equals("pagination limit", response.pagination.limit, 20);

  if (response.data.length > 0) {
    // Verify ALL returned transactions meet filter criteria
    TestValidator.predicate(
      "all transactions match amount filter",
      response.data.every(
        (t) =>
          t.amount >= requestBody.amount_min! &&
          t.amount <= requestBody.amount_max!,
      ),
    );

    // Verify ALL returned transactions meet date filter criteria
    TestValidator.predicate(
      "all transactions match date filter",
      response.data.every((t) => {
        const transactionDate = new Date(t.created_at);
        const start = new Date(requestBody.created_at_start!);
        const end = new Date(requestBody.created_at_end!);
        return transactionDate >= start && transactionDate <= end;
      }),
    );
  }

  //Step 4: Validate transaction details include complete summary information
  //Since we tested filtering in step 3, just validate structure here
  for (const transaction of response.data) {
    //Validate gateway information is included
    TestValidator.predicate(
      "has gateway info",
      transaction.paymentGateway !== undefined &&
        transaction.paymentGateway !== null,
    );
    TestValidator.predicate(
      "gateway has valid code",
      transaction.paymentGateway.gateway_code !== undefined &&
        transaction.paymentGateway.gateway_code.length > 0,
    );

    //Validate payment method details are included
    TestValidator.predicate(
      "has method info",
      transaction.paymentMethod !== undefined &&
        transaction.paymentMethod !== null,
    );
    TestValidator.predicate(
      "method has id",
      transaction.paymentMethod.id !== undefined &&
        transaction.paymentMethod.id.length > 0,
    );
    TestValidator.predicate(
      "method has category",
      transaction.paymentMethod.method_category !== undefined &&
        transaction.paymentMethod.method_category.length > 0,
    );

    //Validate order summary is included
    TestValidator.predicate(
      "has order payment",
      transaction.orderPayment !== undefined &&
        transaction.orderPayment !== null,
    );
    TestValidator.predicate(
      "order has seller",
      transaction.orderPayment.seller !== undefined &&
        transaction.orderPayment.seller !== null,
    );
    TestValidator.predicate(
      "order has order id",
      transaction.orderPayment.shopping_mall_order_id !== undefined &&
        transaction.orderPayment.shopping_mall_order_id.length > 0,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallPaymentTransaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallPaymentTransaction";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallOrderPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderPayment";
import type { IShoppingMallPaymentGateway } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPaymentGateway";
import type { IShoppingMallPaymentMethod } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPaymentMethod";
import type { IShoppingMallPaymentTransaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPaymentTransaction";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Test gateway-specific transaction filtering where an admin analyzes
 * transactions processed through specific payment gateways like Stripe or
 * PayPal.
 *
 * This test validates filtering by gateway_code parameter and ensures returned
 * transactions match the specified gateway with proper gateway response code
 * analysis. The test simulates comprehensive payment processing scenarios to
 * verify that admin can filter and analyze transaction data based on specific
 * payment gateway providers.
 *
 * 1. Create admin account to access payment transaction monitoring capabilities
 * 2. Generate payment transactions for multiple gateways (Stripe, PayPal, Adyen)
 * 3. Filter transactions by specific gateway code and validate results
 * 4. Analyze gateway response codes for technical troubleshooting
 * 5. Test combined filtering with gateway and response code
 * 6. Verify pagination and total transaction count accuracy
 */
export async function test_api_admin_payment_transaction_gateway_filtering(
  connection: api.IConnection,
) {
  // 1. Create admin account for payment transaction access
  const adminRequestData = {
    email: `${RandomGenerator.alphabets(8)}@admin.com`,
    firstname: RandomGenerator.name(1),
    lastname: RandomGenerator.name(2),
    adminlevel: "super_admin",
    department: "Finance",
  } satisfies IShoppingMallAdmin.ICreate;

  const adminAuthResponse: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: adminRequestData,
    });
  typia.assert(adminAuthResponse);

  // Verify admin has super admin privileges
  TestValidator.predicate(
    "admin should have super admin privileges",
    adminAuthResponse.is_super_admin === true,
  );

  // 2. Generate sample payment transaction data for testing
  // Note: Since we need existing transactions to filter, we'll create a broader search
  // and then verify filtering behavior on whatever data exists
  const initialSearchRequest = {
    page: 1,
    limit: 50,
    sort_by: "created_at",
    order: "desc",
  } satisfies IShoppingMallPaymentTransaction.IRequest;

  const allTransactionsResponse: IPageIShoppingMallPaymentTransaction.ISummary =
    await api.functional.shoppingMall.admin.paymentTransactions.index(
      connection,
      {
        body: initialSearchRequest,
      },
    );
  typia.assert(allTransactionsResponse);

  TestValidator.predicate(
    "should receive paginated transaction results",
    allTransactionsResponse.data.length > 0,
  );
  TestValidator.predicate(
    "pagination metadata should be included",
    allTransactionsResponse.pagination !== undefined,
  );

  // Extract distinct gateway codes from response data
  const gateways = allTransactionsResponse.data
    .filter((tx) => tx.paymentGateway && tx.paymentGateway.gateway_code)
    .map((tx) => tx.paymentGateway.gateway_code);
  const uniqueGateways: string[] = [...new Set(gateways)];

  TestValidator.predicate(
    "should have gateway codes available",
    uniqueGateways.length > 0,
  );

  // 3. Test filtering by specific gateway code
  if (uniqueGateways.length > 0) {
    const targetGateway = RandomGenerator.pick(
      uniqueGateways as readonly string[],
    );
    await searchByGateway(connection, targetGateway as string);
  } else {
    // Test hypothetical gateway filtering if no real data available
    await searchByHypotheticalGateway(connection);
  }

  // 4. Test gateway-specific analysis with date ranges
  await gatewayTransactionAnalysis(connection);

  // 5. Test pagination with gateway filtering
  await testGatewayPagination(connection);

  /** Search transactions by specific gateway code */
  async function searchByGateway(
    connection: api.IConnection,
    gatewayCode: string,
  ) {
    const gatewaySearchRequest = {
      page: 1,
      limit: 20,
      gateway_code: gatewayCode,
      sort_by: "created_at",
      order: "desc",
    } satisfies IShoppingMallPaymentTransaction.IRequest;

    const gatewayResults: IPageIShoppingMallPaymentTransaction.ISummary =
      await api.functional.shoppingMall.admin.paymentTransactions.index(
        connection,
        {
          body: gatewaySearchRequest,
        },
      );
    typia.assert(gatewayResults);

    TestValidator.predicate(
      "gateway filtered results should be returned",
      gatewayResults.data.length > 0,
    );
    TestValidator.predicate(
      `all transactions should use gateway ${gatewayCode}`,
      gatewayResults.data.every(
        (tx) => tx.paymentGateway.gateway_code === gatewayCode,
      ),
    );
  }

  /** Search with hypothetical gateway to test API behavior */
  async function searchByHypotheticalGateway(connection: api.IConnection) {
    const hypotheticalGateways = ["stripe", "paypal", "adyen"] as const;
    const testGateway = RandomGenerator.pick(hypotheticalGateways);

    const hypotheticalSearchRequest = {
      page: 1,
      limit: 10,
      gateway_code: testGateway,
      sort_by: "created_at",
      order: "desc",
    } satisfies IShoppingMallPaymentTransaction.IRequest;

    const hypotheticalResults: IPageIShoppingMallPaymentTransaction.ISummary =
      await api.functional.shoppingMall.admin.paymentTransactions.index(
        connection,
        {
          body: hypotheticalSearchRequest,
        },
      );
    typia.assert(hypotheticalResults);

    TestValidator.predicate(
      "hypothetical gateway search should complete",
      hypotheticalResults !== undefined,
    );
  }

  /** Analyze gateway transaction patterns */
  async function gatewayTransactionAnalysis(connection: api.IConnection) {
    const endDate = new Date();
    const startDate = new Date(
      endDate.getTime() - 7 * 24 * 60 * 60 * 1000,
    ).toISOString(); // 7 days ago

    const analysisRequest = {
      page: 1,
      limit: 30,
      created_at_start: startDate,
      status: RandomGenerator.pick([
        "initiated",
        "processing",
        "authorized",
        "captured",
      ] as const),
      sort_by: "processed_at",
      order: "desc",
    } satisfies IShoppingMallPaymentTransaction.IRequest;

    const analysisResults: IPageIShoppingMallPaymentTransaction.ISummary =
      await api.functional.shoppingMall.admin.paymentTransactions.index(
        connection,
        {
          body: analysisRequest,
        },
      );
    typia.assert(analysisResults);

    TestValidator.predicate(
      "analysis should return transaction data",
      analysisResults.data.length > 0,
    );

    analysisResults.data.forEach(
      (transaction: IShoppingMallPaymentTransaction.ISummary) => {
        TestValidator.predicate(
          "gateway response code should be present",
          transaction.gateway_response_code.length > 0,
        );
        TestValidator.predicate(
          "gateway message should be meaningful",
          transaction.gateway_message.length > 0,
        );
      },
    );
  }

  /** Test pagination with gateway filtering */
  async function testGatewayPagination(connection: api.IConnection) {
    const smallPageRequest = {
      page: 1,
      limit: 5,
      sort_by: "created_at",
      order: "desc",
    } satisfies IShoppingMallPaymentTransaction.IRequest;

    const pagedResults: IPageIShoppingMallPaymentTransaction.ISummary =
      await api.functional.shoppingMall.admin.paymentTransactions.index(
        connection,
        {
          body: smallPageRequest,
        },
      );
    typia.assert(pagedResults);

    TestValidator.equals("should get exact limit", pagedResults.data.length, 5);
    TestValidator.equals(
      "should be on page 1",
      pagedResults.pagination.current,
      1,
    );

    TestValidator.predicate(
      "transactions should have gateway codes",
      pagedResults.data.length === 0 ||
        pagedResults.data.some(
          (tx) =>
            tx.paymentGateway.gateway_code &&
            tx.paymentGateway.gateway_code.length > 0,
        ),
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import type { IShoppingMallSupportTicket } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSupportTicket";
import type { IShoppingMallTicketMessage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallTicketMessage";

/**
 * Test adding a reply message to an existing support ticket.
 *
 * This test validates the support ticket messaging system by testing the
 * complete workflow of:
 *
 * 1. Customer registration and authentication
 * 2. Creating a support ticket
 * 3. Adding messages to the ticket with proper content validation
 * 4. Verifying message threading and conversation history
 * 5. Testing message type restrictions (customers limited to 'text' type)
 * 6. Validating message content format and length requirements
 *
 * The test ensures customers can effectively communicate with support staff
 * while maintaining security boundaries and proper authorization checks. It
 * also verifies that the complete conversation thread is maintained for issue
 * resolution tracking and audit purposes.
 */
export async function test_api_support_ticket_message_addition(
  connection: api.IConnection,
) {
  // Step 1: Register and authenticate a customer
  const customerEmail =
    RandomGenerator.mobile("010").replace(/-/g, "") + "@test.com";
  const customer = await api.functional.auth.customer.join(connection, {
    body: {
      email: customerEmail,
      password: "StrongPassword123!",
      first_name: RandomGenerator.name(1),
      last_name: RandomGenerator.name(1),
      href: "https://example.com/register",
      referrer: "https://example.com",
    } satisfies IShoppingMallCustomer.IRegister,
  });
  typia.assert(customer);

  // Step 2: Create a support ticket to add messages to
  const ticket =
    await api.functional.shoppingMall.customer.supportTickets.create(
      connection,
      {
        body: {
          subject: "Order delivery issue - Tracking number problems",
          description: RandomGenerator.paragraph({ sentences: 5 }),
          priority: RandomGenerator.pick([
            "low",
            "medium",
            "high",
            "urgent",
          ] as const),
          category: "order_issue",
          source: RandomGenerator.pick([
            "email",
            "chat",
            "phone",
            "portal",
            "social_media",
          ] as const),
          severity: RandomGenerator.pick([
            "critical",
            "major",
            "minor",
            "cosmetic",
          ] as const),
          href: "https://example.com/tickets",
          referrer: "https://example.com/dashboard",
        } satisfies IShoppingMallSupportTicket.ICreate,
      },
    );
  typia.assert(ticket);

  // Step 3: Add a customer message to the ticket
  const customerMessage =
    await api.functional.shoppingMall.customer.supportTickets.messages.createMessage(
      connection,
      {
        ticketId: ticket.id,
        body: {
          message_content:
            "Hello, I'm still experiencing the same tracking issue. I checked the tracking number on the carrier website and it shows as not found. Could you please investigate this?",
          message_type: "text", // Customer can only create 'text' or 'attachment' messages
        } satisfies IShoppingMallTicketMessage.ICreate,
      },
    );
  typia.assert(customerMessage);

  // Step 4: Verify the message was created successfully
  TestValidator.equals(
    "message sender is customer",
    customerMessage.sender_customer?.id,
    customer.id,
  );
  TestValidator.equals(
    "message content matches",
    customerMessage.message_content,
    "Hello, I'm still experiencing the same tracking issue. I checked the tracking number on the carrier website and it shows as not found. Could you please investigate this?",
  );
  TestValidator.equals(
    "message type is text",
    customerMessage.message_type,
    "text",
  );
  TestValidator.predicate(
    "message creation timestamp exists",
    customerMessage.created_at !== null,
  );
  TestValidator.predicate(
    "message is not internal",
    customerMessage.is_internal === false,
  );
  TestValidator.predicate(
    "message is not automated",
    customerMessage.is_automated === false,
  );

  // Step 5: Add another message with longer content
  const detailedMessage =
    await api.functional.shoppingMall.customer.supportTickets.messages.createMessage(
      connection,
      {
        ticketId: ticket.id,
        body: {
          message_content: RandomGenerator.content({
            paragraphs: 2,
            sentenceMin: 15,
            sentenceMax: 25,
          }),
          message_type: "text",
        } satisfies IShoppingMallTicketMessage.ICreate,
      },
    );
  typia.assert(detailedMessage);

  // Step 6: Verify message content length and format
  TestValidator.predicate(
    "detailed message content has appropriate length",
    detailedMessage.message_content.length > 100,
  );
  TestValidator.predicate(
    "detailed message content contains paragraphs",
    detailedMessage.message_content.includes("\n\n"),
  );

  // Step 7: Test error handling for forbidden message types (customers cannot create system notices)
  await TestValidator.error(
    "customer cannot create system notice messages",
    async () => {
      await api.functional.shoppingMall.customer.supportTickets.messages.createMessage(
        connection,
        {
          ticketId: ticket.id,
          body: {
            message_content: "This message type should be rejected",
            message_type: "system_notice", // Customers cannot create system notices
          } satisfies IShoppingMallTicketMessage.ICreate,
        },
      );
    },
  );

  // Step 7: Test message to non-existent ticket
