  // Step 3: Create product unit - Size for sizing variants
  const sizeUnit =
    await api.functional.shoppingMall.seller.products.units.create(connection, {
      productCode: product.sku,
      body: {
        name: "Size",
        type: "size",
        display_style: "dropdown",
        is_required: true,
        is_multiple: false,
        sort_order: 1,
      } satisfies IShoppingMallProductUnit.ICreate,
    });
  typia.assert(sizeUnit);

  // Step 4: Create product unit - Color for color variants
  const colorUnit =
    await api.functional.shoppingMall.seller.products.units.create(connection, {
      productCode: product.sku,
      body: {
        name: "Color",
        type: "color",
        display_style: "swatches",
        is_required: true,
        is_multiple: false,
        sort_order: 2,
      } satisfies IShoppingMallProductUnit.ICreate,
    });
  typia.assert(colorUnit);

  // Step 5: Create PREMIUM variant with positive pricing adjustment (price premium)
  const premiumVariant =
    await api.functional.shoppingMall.seller.products.variants.create(
      connection,
      {
        productCode: product.sku,
        body: {
          shopping_mall_product_id: product.id,
          shopping_mall_product_unit_id: sizeUnit.id,
          sku: `PREMIUM-${RandomGenerator.alphaNumeric(8)}`,
          title: "PREMIUM Large T-Shirt",
          price_adjustment: 15.0, // +$15 premium for large size
          cost_adjustment: 8.5, // Higher material cost
          weight_adjustment: 0.1, // Slightly heavier
          inventory_quantity: 25,
          inventory_policy: "deny", // No backorders
          position: 0, // Display first
          is_active: true,
        } satisfies IShoppingMallProductVariant.ICreate,
      },
    );
  typia.assert(premiumVariant);

  TestValidator.equals(
    "premium variant price adjustment",
    premiumVariant.price_adjustment,
    15.0,
  );
  TestValidator.equals(
    "premium variant cost adjustment",
    premiumVariant.cost_adjustment,
    8.5,
  );
  TestValidator.equals(
    "premium variant inventory policy",
    premiumVariant.inventory_policy,
    "deny",
  );
  TestValidator.equals(
    "premium variant display position",
    premiumVariant.position,
    0,
  );

  // Step 6: Create BUDGET variant with negative pricing adjustment (discount)
  const budgetVariant =
    await api.functional.shoppingMall.seller.products.variants.create(
      connection,
      {
        productCode: product.sku,
        body: {
          shopping_mall_product_id: product.id,
          shopping_mall_product_unit_id: colorUnit.id,
          sku: `BUDGET-${RandomGenerator.alphaNumeric(8)}`,
          title: "BUDGET Basic Black",
          price_adjustment: -5.0, // -$5 discount for basic color
          cost_adjustment: -3.0, // Lower material cost
          inventory_quantity: 50,
          inventory_policy: "continue", // Allow backorders
          position: 1,
          is_active: true,
        } satisfies IShoppingMallProductVariant.ICreate,
      },
    );
  typia.assert(budgetVariant);

  TestValidator.equals(
    "budget variant price adjustment",
    budgetVariant.price_adjustment,
    -5.0,
  );
  TestValidator.equals(
    "budget variant cost adjustment",
    budgetVariant.cost_adjustment,
    -3.0,
  );
  TestValidator.equals(
    "budget variant inventory policy",
    budgetVariant.inventory_policy,
    "continue",
  );

  // Step 7: Create STANDARD variant with zero pricing adjustment
  const standardVariant =
    await api.functional.shoppingMall.seller.products.variants.create(
      connection,
      {
        productCode: product.sku,
        body: {
          shopping_mall_product_id: product.id,
          shopping_mall_product_unit_id: sizeUnit.id,
          sku: `STANDARD-${RandomGenerator.alphaNumeric(8)}`,
          title: "STANDARD Small White",
          price_adjustment: 0.0, // No price adjustment
          inventory_quantity: 30,
          inventory_policy: "deny",
          position: 2,
          is_active: true,
        } satisfies IShoppingMallProductVariant.ICreate,
      },
    );
  typia.assert(standardVariant);

  TestValidator.equals(
    "standard variant price adjustment",
    standardVariant.price_adjustment,
    0.0,
  );
  TestValidator.equals(
    "standard variant has no cost adjustment",
    standardVariant.cost_adjustment,
    null,
  );
  TestValidator.equals(
    "standard variant has no weight adjustment",
    standardVariant.weight_adjustment,
    null,
  );

  // Step 8: Create COMPLEX variant with multiple pricing adjustments
  const complexVariant =
    await api.functional.shoppingMall.seller.products.variants.create(
      connection,
      {
        productCode: product.sku,
        body: {
          shopping_mall_product_id: product.id,
          shopping_mall_product_unit_id: colorUnit.id,
          sku: `COMPLEX-${RandomGenerator.alphaNumeric(8)}`,
          title: "COMPLEX Limited Edition Red",
          price_adjustment: 25.0, // +$25 very premium
          cost_adjustment: 15.0, // High-end material cost
          weight_adjustment: 0.15, // Heavy premium fabric
          barcode: `LE-${RandomGenerator.alphabets(6).toUpperCase()}`,
          inventory_quantity: 10,
          inventory_policy: "deny",
          position: 3,
          is_active: true,
        } satisfies IShoppingMallProductVariant.ICreate,
      },
    );
  typia.assert(complexVariant);

  TestValidator.equals(
    "complex variant price adjustment",
    complexVariant.price_adjustment,
    25.0,
  );
  TestValidator.equals(
    "complex variant cost adjustment",
    complexVariant.cost_adjustment,
    15.0,
  );
  TestValidator.equals(
    "complex variant weight adjustment",
    complexVariant.weight_adjustment,
    0.15,
  );
  TestValidator.equals(
    "complex variant has barcode",
    complexVariant.barcode !== null,
    true,
  );

  // Step 9: Validate final pricing calculations for all variants
  const basePrice = product.price;
  TestValidator.equals(
    "premium final price calculation",
    basePrice + premiumVariant.price_adjustment,
    64.99,
  );
  TestValidator.equals(
    "budget final price calculation",
    basePrice + budgetVariant.price_adjustment,
    44.99,
  );
  TestValidator.equals(
    "standard final price calculation",
    basePrice + standardVariant.price_adjustment,
    49.99,
  );
  TestValidator.equals(
    "complex final price calculation",
    basePrice + complexVariant.price_adjustment,
    74.99,
  );

  // Step 10: Test business validation - invalid inventory quantity
  await TestValidator.error(
    "variant creation with negative inventory should fail",
    async () => {
      await api.functional.shoppingMall.seller.products.variants.create(
        connection,
        {
          productCode: product.sku,
          body: {
            shopping_mall_product_id: product.id,
            shopping_mall_product_unit_id: sizeUnit.id,
            sku: `INVALID-${RandomGenerator.alphaNumeric(8)}`,
            title: "Invalid Inventory Test",
            price_adjustment: 0.0,
            inventory_quantity: -1, // Invalid negative inventory
            inventory_policy: "deny",
            position: 4,
            is_active: true,
          } satisfies IShoppingMallProductVariant.ICreate,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallInventoryStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallInventoryStatus";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductCategory";
import type { IShoppingMallProductImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductImage";
import type { IShoppingMallProductReviewStatistics } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductReviewStatistics";
import type { IShoppingMallProductUnit } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductUnit";
import type { IShoppingMallProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductVariant";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

export async function test_api_seller_variant_creation_position_and_display_logic(
  connection: api.IConnection,
) {
  // Step 1: Create seller account for testing
  const seller = await api.functional.auth.seller.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      business_name: RandomGenerator.name(),
      business_registration_number: RandomGenerator.alphaNumeric(10),
      tax_id: RandomGenerator.alphaNumeric(9),
      phone: RandomGenerator.mobile("010"),
      business_type: RandomGenerator.pick([
        "corporation",
        "partnership",
        "llc",
        "sole_proprietorship",
      ] as const),
    } satisfies IShoppingMallSeller.IJoin,
  });
  typia.assert(seller);

  // Step 2: Create product for multiple variant scenarios
  const product = await api.functional.shoppingMall.seller.products.create(
    connection,
    {
      body: {
        sku: `SKU-${RandomGenerator.alphaNumeric(8)}`,
        name: RandomGenerator.paragraph({
          sentences: 2,
          wordMin: 3,
          wordMax: 6,
        }),
        description: RandomGenerator.content({
          paragraphs: 2,
          sentenceMin: 5,
          sentenceMax: 8,
        }),
        price: typia.random<
          number & tags.Type<"uint32"> & tags.Minimum<100> & tags.Maximum<1000>
        >(),
        condition: "new",
        weight: typia.random<
          number & tags.Type<"uint32"> & tags.Minimum<1> & tags.Maximum<10>
        >(),
        weight_unit: "kg",
        track_quantity: true,
        allow_backorder: false,
        is_shipping_required: true,
        is_taxable: true,
        seo_title: RandomGenerator.paragraph({
          sentences: 1,
          wordMin: 5,
          wordMax: 8,
        }),
        seo_description: RandomGenerator.paragraph({
          sentences: 2,
          wordMin: 4,
          wordMax: 6,
        }),
        category_id: typia.random<string & tags.Format<"uuid">>(),
        shopping_mall_seller_id: seller.id,
        href: "https://example.com/seller/product",
        referrer: "https://example.com/seller/dashboard",
      } satisfies IShoppingMallProduct.ICreate,
    },
  );
  typia.assert(product);

  // Step 3: Create product units for variant configuration
  // Size unit - required selection
  const sizeUnit =
    await api.functional.shoppingMall.seller.products.units.create(connection, {
      productCode: product.sku,
      body: {
        name: "Size",
        type: "size",
        display_style: "buttons",
        is_required: true,
        is_multiple: false,
        sort_order: 1,
      } satisfies IShoppingMallProductUnit.ICreate,
    });
  typia.assert(sizeUnit);

  // Color unit - required selection
  const colorUnit =
    await api.functional.shoppingMall.seller.products.units.create(connection, {
      productCode: product.sku,
      body: {
        name: "Color",
        type: "color",
        display_style: "swatches",
        is_required: true,
        is_multiple: false,
        sort_order: 2,
      } satisfies IShoppingMallProductUnit.ICreate,
    });
  typia.assert(colorUnit);

  // Material unit - optional selection with multiple choices
  const materialUnit =
    await api.functional.shoppingMall.seller.products.units.create(connection, {
      productCode: product.sku,
      body: {
        name: "Material",
        type: "material",
        display_style: "dropdown",
        is_required: false,
        is_multiple: true,
        sort_order: 3,
      } satisfies IShoppingMallProductUnit.ICreate,
    });
  typia.assert(materialUnit);

  // Step 4: Create variants with different position values for display testing
  // Create multiple variants with strategic position assignments
  const positions = [0, 1, 2, 3, 4]; // Different position values for testing
  const variants: IShoppingMallProductVariant[] = [];

  for (let i = 0; i < positions.length; i++) {
    // Create variant data with proper type handling
    const variantData = {
      shopping_mall_product_id: product.id,
      shopping_mall_product_unit_id: i % 2 === 0 ? sizeUnit.id : colorUnit.id,
      sku: `VAR-${product.sku}-${positions[i]}-${RandomGenerator.alphaNumeric(3)}`,
      title: `Variant Position ${positions[i]} - ${i % 2 === 0 ? "Size" : "Color"}`,
      price_adjustment: typia.random<
        number & tags.Type<"int32"> & tags.Minimum<0> & tags.Maximum<500>
      >(),
      cost_adjustment:
        i % 3 === 0
          ? typia.random<
              number & tags.Type<"int32"> & tags.Minimum<50> & tags.Maximum<200>
            >()
          : (null as any),
      weight_adjustment:
        i % 2 === 0
          ? typia.random<
              number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<3>
            >()
          : (null as any),
      barcode:
        i % 2 === 0 ? `BAR-${RandomGenerator.alphaNumeric(6)}` : (null as any),
      image:
        i % 3 === 0
          ? `https://example.com/images/product-${positions[i]}.jpg`
          : (null as any),
      inventory_quantity: typia.random<
        number & tags.Type<"uint32"> & tags.Minimum<10> & tags.Maximum<100>
      >(),
      inventory_policy: RandomGenerator.pick(["deny", "continue"] as const) as
        | "deny"
        | "continue",
      position: positions[i],
      is_active: i % 2 === 0,
    } satisfies IShoppingMallProductVariant.ICreate;

    const variant =
      await api.functional.shoppingMall.seller.products.variants.create(
        connection,
        {
          productCode: product.sku,
          body: variantData,
        },
      );
    typia.assert(variant);
    variants.push(variant);
  }

  // Step 5: Validate position-based display ordering works correctly
  TestValidator.equals("number of variants created", variants.length, 5);

  // Verify that variant positions are correctly set
  for (let i = 0; i < variants.length; i++) {
    TestValidator.equals(
      `variant ${i} position matches expected`,
      variants[i].position,
      positions[i],
    );
  }

  // Validate position ordering logic (lower positions should have higher display priority)
  const sortedVariants = variants.sort((a, b) => a.position - b.position);
  TestValidator.equals(
    "variants are ordered by position",
    sortedVariants.map((v) => v.position),
    positions,
  );

  // Step 6: Test display priority configuration for seller optimization
  const priorityVariants = variants.filter((v) => v.position <= 2); // Top 3 priority positions
  TestValidator.equals(
    "priority variants have position ≤ 2",
    priorityVariants.length,
    3,
  );

  // Verify active/inactive status distribution
  const activeVariants = variants.filter((v) => v.is_active);
  TestValidator.predicate(
    "at least 2 variants are active",
    activeVariants.length >= 2,
  );

  // Step 7: Test variant stock management integration
  const totalInventory = variants.reduce(
    (sum, variant) => sum + variant.inventory_quantity,
    0,
  );
  TestValidator.predicate(
    "total inventory across variants is positive",
    totalInventory > 0,
  );

  // Validate individual variant properties
  const sampleVariant = variants[0];
  TestValidator.predicate(
    "variant SKU follows expected pattern",
    sampleVariant.sku.startsWith("VAR-"),
  );
  TestValidator.predicate(
    "variant title is descriptive",
    sampleVariant.title.includes("Position"),
  );

  // Test price adjustment range
  TestValidator.predicate(
    "price adjustment is within reasonable range",
    sampleVariant.price_adjustment >= 0 &&
      sampleVariant.price_adjustment <= 500,
  );

  // Validate inventory management settings
  TestValidator.predicate(
    "inventory policy is one of allowed values",
    sampleVariant.inventory_policy === "deny" ||
      sampleVariant.inventory_policy === "continue",
  );

  // Step 8: Test variant positioning strategy for optimal customer experience
  const positionStrategy = variants.map((v) => ({
    position: v.position,
    title: v.title,
    is_active: v.is_active,
    inventory: v.inventory_quantity,
  }));

  // Verify seller optimization possibilities
  TestValidator.predicate(
    "position 0 variant exists",
    positionStrategy.some((s) => s.position === 0),
  );

  TestValidator.predicate(
    "highest priority position (0) is optimized",
    positionStrategy.filter((s) => s.position === 0).length === 1,
  );

  // Validate variant coverage across position ranges
  const lowPositions = variants.filter((v) => v.position < 3);
  const highPositions = variants.filter((v) => v.position >= 3);

  TestValidator.equals("low position variants count", lowPositions.length, 3);
  TestValidator.equals("high position variants count", highPositions.length, 2);

  // Final validation of display ordering system
  TestValidator.predicate(
    "variants provide complete coverage for testing",
    variants.length >= 5,
  );
  TestValidator.predicate(
    "position values are unique",
    new Set(variants.map((v) => v.position)).size === variants.length,
  );

  console.log(
    "Variant creation with position display logic test completed successfully",
  );
  console.log("Total variants created:", variants.length);
  console.log(
    "Position range:",
    Math.min(...variants.map((v) => v.position)),
    "to",
    Math.max(...variants.map((v) => v.position)),
  );
  console.log("Active variants:", activeVariants.length);
}

