import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallArticleCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallArticleCategory";

export async function test_api_article_category_seo_optimization_setup(
  connection: api.IConnection,
) {
  // Step 1: Create administrator account to access category management
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        firstname: RandomGenerator.name(1),
        lastname: RandomGenerator.name(1),
        adminlevel: "super_admin",
        department: "Content Management",
      } satisfies IShoppingMallAdmin.ICreate,
    });
  typia.assert(admin);
  TestValidator.equals(
    "admin has super admin privileges",
    admin.is_super_admin,
    true,
  );

  // Step 2: Create top-level SEO-optimized category with comprehensive metadata
  const topCategoryCode = `electronics-${RandomGenerator.alphaNumeric(6)}`;
  const topCategoryBody = {
    code: topCategoryCode,
    name: "Electronics & Technology",
    description: RandomGenerator.content({
      paragraphs: 1,
      sentenceMin: 3,
      sentenceMax: 5,
      wordMin: 4,
      wordMax: 8,
    }),
    visible: true,
    featured: true,
    metaTitle: "Latest Electronics & Technology Articles | Shopping Mall",
    metaDescription:
      "Discover cutting-edge electronics, tech reviews, and digital innovation trends. Expert insights on smartphones, laptops, gadgets, and emerging technologies.",
    metaKeywords:
      "electronics, technology, gadgets, smartphones, laptops, innovation, digital trends",
    sequence: 0,
  } satisfies IShoppingMallArticleCategory.ICreate;

  const topCategory =
    await api.functional.shoppingMall.admin.articleCategories.create(
      connection,
      {
        body: topCategoryBody,
      },
    );
  typia.assert(topCategory);

  TestValidator.equals(
    "top category code matches",
    topCategory.code,
    topCategoryCode,
  );
  TestValidator.equals("top category is visible", topCategory.visible, true);
  TestValidator.equals("top category is featured", topCategory.featured, true);
  TestValidator.equals("top category level is 0", topCategory.level, 0);
  TestValidator.equals(
    "top category has 0 articles initially",
    topCategory.articleCount,
    0,
  );
  TestValidator.equals(
    "admin actor type matches",
    topCategory.actorType,
    "channel_admin",
  );

  // Step 3: Create nested sub-category for mobile devices with targeted SEO
  const mobileCategoryCode = `mobile-${RandomGenerator.alphaNumeric(6)}`;
  const mobileCategoryBody = {
    code: mobileCategoryCode,
    name: "Mobile Devices & Accessories",
    description: RandomGenerator.content({
      paragraphs: 1,
      sentenceMin: 2,
      sentenceMax: 4,
      wordMin: 3,
      wordMax: 7,
    }),
    visible: true,
    featured: false,
    metaTitle: "Mobile Devices & Accessories Guide | Complete Coverage",
    metaDescription:
      "Explore comprehensive mobile device reviews, smartphone comparisons, accessory guides, and mobile technology insights for informed purchasing decisions.",
    metaKeywords:
      "mobile devices, smartphones, cell phones, accessories, reviews, comparisons",
    sequence: 0,
    parentCode: topCategoryCode,
  } satisfies IShoppingMallArticleCategory.ICreate;

  const mobileCategory =
    await api.functional.shoppingMall.admin.articleCategories.create(
      connection,
      {
        body: mobileCategoryBody,
      },
    );
  typia.assert(mobileCategory);

  TestValidator.equals(
    "mobile category parent matches",
    mobileCategory.parent?.code,
    topCategoryCode,
  );
  TestValidator.equals("mobile category level is 1", mobileCategory.level, 1);
  TestValidator.equals(
    "mobile category meta keywords exist",
    mobileCategory.metaKeywords,
    mobileCategoryBody.metaKeywords,
  );
  TestValidator.predicate(
    "mobile category sequence is valid",
    mobileCategory.sequence >= 0,
  );

  // Step 4: Create product category with local business SEO focus
  const productCategoryCode = `products-${RandomGenerator.alphaNumeric(6)}`;
  const productCategoryBody = {
    code: productCategoryCode,
    name: "Product Reviews & Comparisons",
    description: RandomGenerator.paragraph({
      sentences: 3,
      wordMin: 5,
      wordMax: 10,
    }),
    visible: true,
    featured: true,
    metaTitle: "Honest Product Reviews & Expert Comparisons | Shopping Mall",
    metaDescription:
      "Read unbiased product reviews, detailed comparisons, and expert recommendations. Make informed decisions with comprehensive analysis of features, prices, and real user experiences.",
    metaKeywords:
      "product reviews, comparisons, buyer guides, recommendations, analysis, features",
    sequence: 1,
  } satisfies IShoppingMallArticleCategory.ICreate;

  const productCategory =
    await api.functional.shoppingMall.admin.articleCategories.create(
      connection,
      {
        body: productCategoryBody,
      },
    );
  typia.assert(productCategory);

  TestValidator.equals(
    "product category featured status",
    productCategory.featured,
    true,
  );
  TestValidator.predicate(
    "product category sequence is ordered",
    productCategory.sequence > topCategory.sequence,
  );
  TestValidator.notEquals(
    "product category code is unique",
    productCategory.code,
    topCategory.code,
  );

  // Step 5: Create seasonal category demonstrating flexible SEO strategies
  const seasonalCategoryCode = `seasonal-${RandomGenerator.alphaNumeric(6)}`;
  const seasonalCategoryBody = {
    code: seasonalCategoryCode,
    name: "Seasonal Trends & Holiday Shopping",
    description: RandomGenerator.paragraph({
      sentences: 4,
      wordMin: 4,
      wordMax: 8,
    }),
    visible: false,
    featured: false,
    metaTitle: "2024 Holiday Shopping Guide & Seasonal Deals | Expert Tips",
    metaDescription:
      "Discover the best seasonal trends and holiday shopping strategies. Find deals, gift ideas, and expert recommendations for Black Friday, Christmas, New Year shopping.",
    metaKeywords: null,
    sequence: 10,
  } satisfies IShoppingMallArticleCategory.ICreate;

  const seasonalCategory =
    await api.functional.shoppingMall.admin.articleCategories.create(
      connection,
      {
        body: seasonalCategoryBody,
      },
    );
  typia.assert(seasonalCategory);

  TestValidator.equals(
    "seasonal category visibility off",
    seasonalCategory.visible,
    false,
  );
  TestValidator.equals(
    "seasonal category not featured",
    seasonalCategory.featured,
    false,
  );
  TestValidator.equals(
    "seasonal category no keywords",
    seasonalCategory.metaKeywords,
    null,
  );
  TestValidator.equals(
    "seasonal category sequence higher",
    seasonalCategory.sequence,
    10,
  );

  // Step 6: Validate all categories have proper timestamps and IDs
  const categories = [
    topCategory,
    mobileCategory,
    productCategory,
    seasonalCategory,
  ];
  for (const category of categories) {
    await TestValidator.predicate(
      "category has valid UUID",
      typia.is<string & tags.Format<"uuid">>(category.id),
    );
    await TestValidator.predicate(
      "category has creation timestamp",
      typia.is<string & tags.Format<"date-time">>(category.createdAt),
    );
    await TestValidator.predicate(
      "category has update timestamp",
      typia.is<string & tags.Format<"date-time">>(category.updatedAt),
    );
    await TestValidator.predicate(
      "category code has proper length",
      category.code.length >= 1 && category.code.length <= 100,
    );
    await TestValidator.predicate(
      "category name has proper length",
      category.name.length >= 1 && category.name.length <= 100,
    );
    await TestValidator.predicate(
      "category description has proper length",
      category.description.length >= 1 && category.description.length <= 1000,
    );
    await TestValidator.predicate(
      "category metaTitle has proper length",
      category.metaTitle.length >= 1 && category.metaTitle.length <= 100,
    );
    await TestValidator.predicate(
      "category metaDescription has proper length",
      category.metaDescription.length >= 1 &&
        category.metaDescription.length <= 500,
    );
  }

  // Step 7: Verify hierarchical structure integrity
  TestValidator.predicate(
    "top category has no parent",
    topCategory.parent === undefined,
  );
  TestValidator.predicate(
    "mobile category has parent",
    mobileCategory.parent !== undefined,
  );
  TestValidator.equals(
    "mobile category parent is top category",
    mobileCategory.parent?.id,
    topCategory.id,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallArticleTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallArticleTag";
import type { IShoppingMallArticleTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallArticleTag";

/**
 * Test article tag discovery through text search functionality.
 *
 * This test validates comprehensive text search capabilities for article tags,
 * ensuring both customers and administrators can efficiently locate relevant
 * tags through partial matching across tag names and descriptions. The test
 * covers various search scenarios including exact matches, partial term
 * matching, case-insensitive search, and multi-word phrase searches.
 *
 * Test workflow:
 *
 * 1. Retrieve baseline tag data to understand current tag collection
 * 2. Generate comprehensive text search with positive terms
 * 3. Validate search result relevance and accuracy
 * 4. Test partial matching with substrings of tag names
 * 5. Verify case-insensitive search functionality
 * 6. Test multi-word phrase searching capabilities
 * 7. Validate search performance with pagination
 */
export async function test_api_articletag_filter_by_text_search(
  connection: api.IConnection,
) {
  // Step 1: Get baseline data with default parameters
  const baselineResult = await api.functional.shoppingMall.articleTags.index(
    connection,
    {
      body: {
        page: 1,
        limit: 20,
      } satisfies IShoppingMallArticleTag.IRequest,
    },
  );
  typia.assert(baselineResult);

  TestValidator.predicate(
    "baseline result contains pagination data",
    baselineResult.pagination.current === 1 &&
      baselineResult.pagination.limit === 20,
  );

  // Step 2: Test with positive search terms
  const searchQueries = ["tech", "electronics", "fashion", "home"];
  const selectedQuery = RandomGenerator.pick(searchQueries);

  const searchResult = await api.functional.shoppingMall.articleTags.index(
    connection,
    {
      body: {
        page: 1,
        limit: 10,
        search: selectedQuery,
      } satisfies IShoppingMallArticleTag.IRequest,
    },
  );
  typia.assert(searchResult);

  // Validate that at least some results are returned
  TestValidator.predicate(
    "search returns meaningful results",
    searchResult.data.length >= 0 && searchResult.pagination.limit === 10,
  );

  // Step 3: Test comprehensive search with multiple terms
  const complexSearchBody = {
    page: typia.random<
      number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<3>
    >(),
    limit: typia.random<
      number & tags.Type<"int32"> & tags.Minimum<5> & tags.Maximum<20>
    >(),
    search: RandomGenerator.paragraph({
      sentences: typia.random<
        number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<3>
      >(),
    }),
  } satisfies IShoppingMallArticleTag.IRequest;

  const complexSearchResult =
    await api.functional.shoppingMall.articleTags.index(connection, {
      body: complexSearchBody,
    });
  typia.assert(complexSearchResult);

  TestValidator.predicate(
    "complex search respects pagination settings",
    complexSearchResult.pagination.current === complexSearchBody.page &&
      complexSearchResult.pagination.limit === complexSearchBody.limit,
  );

  // Step 4: Test case-insensitive search by comparing results
  const lowerCaseQuery = "test";
  const upperCaseQuery = "TEST";

  const lowerCaseResult = await api.functional.shoppingMall.articleTags.index(
    connection,
    {
      body: {
        page: 1,
        limit: 10,
        search: lowerCaseQuery,
      } satisfies IShoppingMallArticleTag.IRequest,
    },
  );
  typia.assert(lowerCaseResult);

  const upperCaseResult = await api.functional.shoppingMall.articleTags.index(
    connection,
    {
      body: {
        page: 1,
        limit: 10,
        search: upperCaseQuery,
      } satisfies IShoppingMallArticleTag.IRequest,
    },
  );
  typia.assert(upperCaseResult);

  TestValidator.predicate(
    "case-insensitive search produces consistent results",
    lowerCaseResult.data.length === upperCaseResult.data.length,
  );

  // Step 5: Test partial matching with meaningful terms
  const partialTerms = ["mob", "comp", "furn"];
  const partialTerm = RandomGenerator.pick(partialTerms);

  const partialSearchResult =
    await api.functional.shoppingMall.articleTags.index(connection, {
      body: {
        page: 1,
        limit: 15,
        search: partialTerm,
      } satisfies IShoppingMallArticleTag.IRequest,
    });
  typia.assert(partialSearchResult);

  // Validate search functionality with specific tag properties
  TestValidator.predicate(
    "partial search returns results",
    partialSearchResult.data.length >= 0,
  );

  // Step 6: Test with visible filter combined with search
  const visibleSearchResult =
    await api.functional.shoppingMall.articleTags.index(connection, {
      body: {
        page: 1,
        limit: 10,
        search: "product",
        visible: true,
      } satisfies IShoppingMallArticleTag.IRequest,
    });
  typia.assert(visibleSearchResult);

  TestValidator.predicate(
    "search with visible filter returns visible tags",
    visibleSearchResult.data.every((tag) => tag.visible === true),
  );

  // Step 7: Test pagination with search functionality
  const pageResults = await ArrayUtil.asyncRepeat(3, async (index) => {
    return await api.functional.shoppingMall.articleTags.index(connection, {
      body: {
        page: index + 1,
        limit: 5,
        search: "cat",
      } satisfies IShoppingMallArticleTag.IRequest,
    });
  });

  pageResults.forEach((result, index) => {
    typia.assert(result);
    TestValidator.equals(
      `pagination page ${index + 1} matches request`,
      result.pagination.current,
      index + 1,
    );
  });

  // Validate that different pages potentially return different results
  const uniqueResults = new Set(
    pageResults.map((result) => result.data.map((tag) => tag.id).join(",")),
  );

  TestValidator.predicate(
    "pagination produces different page content",
    uniqueResults.size > 1 || pageResults[0].data.length <= 5,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallArticleTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallArticleTag";
import type { IShoppingMallArticleTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallArticleTag";

/**
 * Test channel-specific tag filtering for multi-channel marketplace
 * environments.
 *
 * This test validates that article tags can be filtered by specific channel
 * codes to support channel-specific content categorization. The test will:
 *
 * 1. Filter tags by each channel code individually
 * 2. Verify that filtering returns properly structured responses
 * 3. Test pagination and sorting capabilities with channel filtering
 * 4. Validate search functionality within channel context
 * 5. Test visibility filtering
 * 6. Handle invalid channel codes appropriately
 *
 * This ensures tag management works correctly across different marketplace
 * channels and business units within the platform.
 */
export async function test_api_articletag_filter_by_channel_code(
  connection: api.IConnection,
) {
  // Test 1: Filter tags by electronics channel
  const electronicsTags = await api.functional.shoppingMall.articleTags.index(
    connection,
    {
      body: {
        channelCode: "electronics",
        page: 1,
        limit: 20,
      } satisfies IShoppingMallArticleTag.IRequest,
    },
  );
  typia.assert(electronicsTags);

  // Validate pagination info
  TestValidator.equals(
    "electronics page should be 1",
    electronicsTags.pagination.current,
    1,
  );
  TestValidator.predicate(
    "electronics should have valid pagination",
    electronicsTags.pagination.limit > 0 &&
      electronicsTags.pagination.limit <= 100,
  );

  // Test 2: Filter tags by fashion channel
  const fashionTags = await api.functional.shoppingMall.articleTags.index(
    connection,
    {
      body: {
        channelCode: "fashion",
        page: 1,
        limit: 15,
      } satisfies IShoppingMallArticleTag.IRequest,
    },
  );
  typia.assert(fashionTags);

  // Test 3: Filter tags by home-goods channel with different parameters
  const homeGoodsTags = await api.functional.shoppingMall.articleTags.index(
    connection,
    {
      body: {
        channelCode: "home-goods",
        page: 2,
        limit: 10,
        sortBy: "name",
        sortOrder: "asc",
      } satisfies IShoppingMallArticleTag.IRequest,
    },
  );
  typia.assert(homeGoodsTags);

  // Test 4: Test with search query within channel
  const searchResults = await api.functional.shoppingMall.articleTags.index(
    connection,
    {
      body: {
        channelCode: "electronics",
        search: "mobile",
        page: 1,
        limit: 10,
      } satisfies IShoppingMallArticleTag.IRequest,
    },
  );
  typia.assert(searchResults);

  // Test 5: Test with visibility filter
  const visibleTags = await api.functional.shoppingMall.articleTags.index(
    connection,
    {
      body: {
        channelCode: "fashion",
        visible: true,
        page: 1,
        limit: 25,
      } satisfies IShoppingMallArticleTag.IRequest,
    },
  );
  typia.assert(visibleTags);

  // Test 6: Test invalid channel code handling
  const invalidChannelResult =
    await api.functional.shoppingMall.articleTags.index(connection, {
      body: {
        channelCode: "non-existent-channel",
        page: 1,
        limit: 10,
      } satisfies IShoppingMallArticleTag.IRequest,
    });
  typia.assert(invalidChannelResult);

  // Validate that all results are properly structured
  const allResults = [
    electronicsTags,
    fashionTags,
    homeGoodsTags,
    searchResults,
    visibleTags,
    invalidChannelResult,
  ];

  allResults.forEach((result, index) => {
    TestValidator.predicate(
      `result ${index} should have valid pagination`,
      result.pagination.current >= 1 &&
        result.pagination.limit >= 1 &&
        result.pagination.limit <= 100 &&
        result.pagination.records >= 0 &&
        result.pagination.pages >= 0 &&
        result.pagination.current <= Math.max(result.pagination.pages, 1),
    );

    TestValidator.predicate(
      `result ${index} data should be array`,
      Array.isArray(result.data),
    );

    TestValidator.predicate(
      `result ${index} data length should not exceed limit`,
      result.data.length <= result.pagination.limit,
    );

    // Validate each tag in the results
    result.data.forEach((tag, tagIndex) => {
      TestValidator.predicate(
        `tag ${tagIndex} should have valid UUID id`,
        typeof tag.id === "string" && tag.id.length > 0,
      );
      TestValidator.predicate(
        `tag ${tagIndex} should have valid code`,
        typeof tag.code === "string" && tag.code.length > 0,
      );
      TestValidator.predicate(
        `tag ${tagIndex} should have valid name`,
        typeof tag.name === "string" && tag.name.length > 0,
      );
      TestValidator.predicate(
        `tag ${tagIndex} should have valid color`,
        typeof tag.color === "string" && tag.color.length > 0,
      );
      TestValidator.predicate(
        `tag ${tagIndex} should have valid sequence`,
        typeof tag.sequence === "number" &&
          tag.sequence >= 0 &&
          Number.isInteger(tag.sequence),
      );
      TestValidator.predicate(
        `tag ${tagIndex} should have valid visible boolean`,
        typeof tag.visible === "boolean",
      );
    });
  });

  // Test 7: Compare results between different channels to ensure they're different
  TestValidator.notEquals(
    "electronics and fashion should return different results",
    electronicsTags.pagination.records,
    fashionTags.pagination.records,
  );

  // Test 8: Test edge case with maximum limit
  const maxLimitResults = await api.functional.shoppingMall.articleTags.index(
    connection,
    {
      body: {
        channelCode: "electronics",
        page: 1,
        limit: 100, // Maximum allowed limit
      } satisfies IShoppingMallArticleTag.IRequest,
    },
  );
  typia.assert(maxLimitResults);

  TestValidator.predicate(
    "max limit should not exceed 100",
    maxLimitResults.pagination.limit <= 100,
  );

  TestValidator.predicate(
    "max limit result should match pagination limit",
    maxLimitResults.pagination.limit === 100 ||
      maxLimitResults.data.length <= maxLimitResults.pagination.limit,
  );

  // Test 9: Test with specific tag name filter within channel
  const specificNameResults =
    await api.functional.shoppingMall.articleTags.index(connection, {
      body: {
        channelCode: "electronics",
        name: "smartphones",
        page: 1,
        limit: 5,
      } satisfies IShoppingMallArticleTag.IRequest,
    });
  typia.assert(specificNameResults);

