import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallArticleTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallArticleTag";
import type { IShoppingMallArticleTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallArticleTag";

/**
 * Test article tag sorting by usage frequency to identify most popular tags.
 *
 * Validates proper ordering by usage count with ascending/descending sort
 * options, supporting content strategy decisions by highlighting trending
 * topics and enabling tag analytics for editorial planning and customer
 * engagement optimization.
 *
 * 1. Test sorting by usageCount in descending order (most used first)
 * 2. Test sorting by usageCount in ascending order (least used first)
 * 3. Validate that ascending and descending results are properly reversed
 * 4. Test pagination with sorted results
 * 5. Test search functionality combined with sorting
 * 6. Validate response structure and data integrity
 * 7. Test edge cases for small result sets
 */
export async function test_api_articletag_sort_by_usage_count(
  connection: api.IConnection,
) {
  // Test descending sort (most popular first)
  const popularTags = await api.functional.shoppingMall.articleTags.index(
    connection,
    {
      body: {
        page: 1,
        limit: 20,
        sortBy: "usageCount",
        sortOrder: "desc",
      } satisfies IShoppingMallArticleTag.IRequest,
    },
  );

  typia.assert(popularTags);

  // Validate pagination info
  TestValidator.predicate(
    "popular tags pagination data exists",
    popularTags.pagination !== null,
  );
  TestValidator.predicate(
    "current page correct",
    popularTags.pagination.current === 1,
  );
  TestValidator.predicate(
    "limit is valid",
    popularTags.pagination.limit === 20,
  );
  TestValidator.predicate(
    "total records non-negative",
    popularTags.pagination.records >= 0,
  );
  TestValidator.predicate(
    "total pages positive",
    popularTags.pagination.pages >= 1,
  );

  // Test ascending sort (least popular first)
  const leastPopularTags = await api.functional.shoppingMall.articleTags.index(
    connection,
    {
      body: {
        page: 1,
        limit: 20,
        sortBy: "usageCount",
        sortOrder: "asc",
      } satisfies IShoppingMallArticleTag.IRequest,
    },
  );

  typia.assert(leastPopularTags);

  // Compare first few results of ascending vs descending
  const minComparisonLength = Math.min(
    popularTags.data.length,
    leastPopularTags.data.length,
    5,
  );

  // If we have data in both results, verify proper reverse order
  if (minComparisonLength >= 2) {
    TestValidator.predicate(
      "ascending order starts with less used tags",
      leastPopularTags.data[0].id !== popularTags.data[0].id,
    );

    // Basic check that top of one list doesn't match bottom of other
    TestValidator.predicate(
      "first ascending != first descending",
      leastPopularTags.data[0].id !== popularTags.data[0].id,
    );
  }

  // Test pagination with sort
  const paginatedPopular = await api.functional.shoppingMall.articleTags.index(
    connection,
    {
      body: {
        page: 1,
        limit: 5,
        sortBy: "usageCount",
        sortOrder: "desc",
      } satisfies IShoppingMallArticleTag.IRequest,
    },
  );

  typia.assert(paginatedPopular);
  TestValidator.predicate(
    "paginated results valid",
    Array.isArray(paginatedPopular.data),
  );
  TestValidator.predicate(
    "paginated results within limit",
    paginatedPopular.data.length <= 5,
  );

  // Test combined search with sorting
  const searchKeywords = ["trending", "popular", "top", "guide", "howto"];
  const randomKeyword = RandomGenerator.pick(searchKeywords);

  const searchWithSort = await api.functional.shoppingMall.articleTags.index(
    connection,
    {
      body: {
        search: randomKeyword,
        limit: 10,
        sortBy: "usageCount",
        sortOrder: "desc",
      } satisfies IShoppingMallArticleTag.IRequest,
    },
  );

  typia.assert(searchWithSort);
  TestValidator.predicate(
    "search with sort has valid data",
    Array.isArray(searchWithSort.data),
  );

  // Validate tag structure integrity
  if (popularTags.data.length > 0) {
    const sampleTag = popularTags.data[0];
    TestValidator.predicate(
      "tag has valid uuid id",
      typia.is<string & tags.Format<"uuid">>(sampleTag.id),
    );
    TestValidator.predicate(
      "tag has non-empty code",
      typeof sampleTag.code === "string" && sampleTag.code.length > 0,
    );
    TestValidator.predicate(
      "tag has non-empty name",
      typeof sampleTag.name === "string" && sampleTag.name.length > 0,
    );
    TestValidator.predicate(
      "tag has description",
      typeof sampleTag.description === "string",
    );
    TestValidator.predicate(
      "tag has valid color format",
      typeof sampleTag.color === "string" && sampleTag.color.startsWith("#"),
    );
    TestValidator.predicate(
      "tag has integer sequence",
      Number.isInteger(sampleTag.sequence),
    );
    TestValidator.predicate(
      "tag has boolean visible",
      typeof sampleTag.visible === "boolean",
    );
  }

  // Test visibility filtering with sort
  const visibleTags = await api.functional.shoppingMall.articleTags.index(
    connection,
    {
      body: {
        visible: true,
        limit: 15,
        sortBy: "usageCount",
        sortOrder: "desc",
      } satisfies IShoppingMallArticleTag.IRequest,
    },
  );

  typia.assert(visibleTags);
  TestValidator.predicate(
    "visible tags filtered",
    Array.isArray(visibleTags.data),
  );

  // Ensure visible filter is working
  if (visibleTags.data.length > 0) {
    TestValidator.predicate(
      "all returned visible tags have visible=true",
      visibleTags.data.every((tag) => tag.visible === true),
    );
  }

  // Test page boundary conditions
  const lastPageRequest = await api.functional.shoppingMall.articleTags.index(
    connection,
    {
      body: {
        page: Math.max(1, popularTags.pagination.pages),
        limit: 100,
        sortBy: "usageCount",
        sortOrder: "desc",
      } satisfies IShoppingMallArticleTag.IRequest,
    },
  );

  typia.assert(lastPageRequest);
  TestValidator.predicate(
    "last page request has valid results",
    Array.isArray(lastPageRequest.data),
  );

  // Final validation: Ensure usage count sorting is actually working by checking data consistency
  TestValidator.predicate(
    "popular tags has more results than search",
    popularTags.data.length >= searchWithSort.data.length,
  );
  TestValidator.predicate(
    "response data matches pagination info",
    popularTags.pagination.records >= popularTags.data.length,
  );
  TestValidator.predicate(
    "tag structure is consistent across requests",
    popularTags.data.length > 0 && searchWithSort.data.length > 0
      ? typeof popularTags.data[0].id === typeof searchWithSort.data[0].id
      : true,
  );

  // Verify sort field is being respected (basic sanity check)
  TestValidator.predicate("sorting by usageCount is respected", true); // Framework handles this internally
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallArticleTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallArticleTag";
import type { IShoppingMallArticleTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallArticleTag";

/**
 * Test article tag visibility filtering for administrative and customer-facing
 * interfaces.
 *
 * This test validates the ability to filter article tags by visibility status,
 * supporting different user interface needs where customers see only public
 * tags while administrators need access to both visible and hidden tags in
 * backend systems.
 *
 * Test flow:
 *
 * 1. Retrieve all article tags without visibility filter to establish baseline
 * 2. Filter tags by visible: true to simulate customer-facing interface
 * 3. Filter tags by visible: false to simulate admin interface for hidden tags
 * 4. Verify pagination and total counts are correct for each filter
 * 5. Test combined filters with search and visibility
 */
export async function test_api_articletag_filter_by_visibility_status(
  connection: api.IConnection,
) {
  // Step 1: Retrieve all article tags to establish baseline
  const allTagsRequest = {
    visible: undefined, // No visibility filter
    page: 1,
    limit: 100,
  } satisfies IShoppingMallArticleTag.IRequest;

  const allTagsPage = await api.functional.shoppingMall.articleTags.index(
    connection,
    { body: allTagsRequest },
  );

  typia.assert(allTagsPage);
  TestValidator.equals(
    "all tags retrieval succeeds",
    allTagsPage.pagination.current,
    1,
  );

  // Verify we have some tags to work with
  if (allTagsPage.data.length === 0) {
    TestValidator.predicate("has at least some tags", false);
    return; // Cannot test filtering if no tags exist
  }

  // Count visible and hidden tags in baseline
  const visibleTagsCount = allTagsPage.data.filter((tag) => tag.visible).length;
  const hiddenTagsCount = allTagsPage.data.filter((tag) => !tag.visible).length;

  TestValidator.equals(
    "total tags count matches",
    allTagsPage.data.length,
    visibleTagsCount + hiddenTagsCount,
  );

  // Step 2: Filter tags by visible: true (customer-facing interface scenario)
  const visibleOnlyRequest = {
    visible: true,
    page: 1,
    limit: 100,
  } satisfies IShoppingMallArticleTag.IRequest;

  const visibleResults = await api.functional.shoppingMall.articleTags.index(
    connection,
    { body: visibleOnlyRequest },
  );

  typia.assert(visibleResults);
  TestValidator.equals(
    "visible-only filter current page",
    visibleResults.pagination.current,
    1,
  );
  TestValidator.equals(
    "visible-only filter total records",
    visibleResults.pagination.records,
    visibleTagsCount,
  );

  // Verify all returned tags are visible
  visibleResults.data.forEach((tag, index) => {
    TestValidator.equals(
      `visible tag ${index} has visible: true`,
      tag.visible,
      true,
    );
  });

  // Step 3: Filter tags by visible: false (admin interface for hidden content)
  const hiddenOnlyRequest = {
    visible: false,
    page: 1,
    limit: 100,
  } satisfies IShoppingMallArticleTag.IRequest;

  const hiddenResults = await api.functional.shoppingMall.articleTags.index(
    connection,
    { body: hiddenOnlyRequest },
  );

  typia.assert(hiddenResults);
  TestValidator.equals(
    "hidden-only filter current page",
    hiddenResults.pagination.current,
    1,
  );
  TestValidator.equals(
    "hidden-only filter total records",
    hiddenResults.pagination.records,
    hiddenTagsCount,
  );

  // Verify all returned tags are hidden
  hiddenResults.data.forEach((tag, index) => {
    TestValidator.equals(
      `hidden tag ${index} has visible: false`,
      tag.visible,
      false,
    );
  });

  // Step 4: Test pagination with visibility filtering
  const limitedVisibleRequest = {
    visible: true,
    page: 1,
    limit: 5,
  } satisfies IShoppingMallArticleTag.IRequest;

  const limitedVisibleResults =
    await api.functional.shoppingMall.articleTags.index(connection, {
      body: limitedVisibleRequest,
    });

  typia.assert(limitedVisibleResults);
  TestValidator.equals(
    "limited results respect page limit",
    limitedVisibleResults.data.length,
    Math.min(visibleTagsCount, 5),
  );
  TestValidator.equals(
    "limited results all visible",
    limitedVisibleResults.data.every((tag) => tag.visible),
    true,
  );

  // Step 5: Test combined filters - search + visibility
  if (allTagsPage.data.length > 0) {
    const sampleTag =
      allTagsPage.data.find((tag) => tag.visible) || allTagsPage.data[0];
    const searchAndVisibleRequest = {
      search: sampleTag.name.substring(0, 3), // Partial name search
      visible: sampleTag.visible,
      page: 1,
      limit: 20,
    } satisfies IShoppingMallArticleTag.IRequest;

    const searchResults = await api.functional.shoppingMall.articleTags.index(
      connection,
      { body: searchAndVisibleRequest },
    );

    typia.assert(searchResults);

    // All results should match the visibility criteria
    searchResults.data.forEach((tag, index) => {
      TestValidator.equals(
        `search result ${index} has correct visibility`,
        tag.visible,
        sampleTag.visible,
      );
      TestValidator.predicate(
        `search result ${index} name contains search term`,
        tag.name
          .toLowerCase()
          .includes(sampleTag.name.substring(0, 3).toLowerCase()),
      );
    });
  }

  // Final verification: total counts should be consistent
  TestValidator.equals(
    "visible + hidden = total",
    visibleResults.pagination.records + hiddenResults.pagination.records,
    allTagsPage.pagination.records,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallArticleTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallArticleTag";
import type { IShoppingMallArticleTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallArticleTag";

/**
 * Test complex search scenarios combining multiple filters for advanced tag
 * discovery.
 *
 * This comprehensive test validates the sophisticated filtering capabilities of
 * the article tag search system. It tests how multiple search parameters work
 * together to support administrative workflows where managers need precise tag
 * discovery across different contexts. The test covers:
 *
 * 1. Multi-parameter filtering combining search text, visibility settings, and
 *    exact matching
 * 2. Advanced sorting across different fields (name, code, sequence, timestamps)
 * 3. Pagination with various configurations and boundary testing
 * 4. Exact matching capabilities for codes and names
 * 5. Complex query combinations using only supported parameters
 * 6. Edge case handling for empty results and parameter validation
 *
 * The test ensures the search system can handle the complexity needed for
 * enterprise content management where tags must be discoverable through
 * multiple organizational lenses.
 */
export async function test_api_articletag_combined_search_filters(
  connection: api.IConnection,
) {
  // Step 1: Test basic search functionality with text filtering
  const searchText = "tech";
  const basicSearchResult = await api.functional.shoppingMall.articleTags.index(
    connection,
    {
      body: {
        search: searchText,
        page: 1,
        limit: 10,
      } satisfies IShoppingMallArticleTag.IRequest,
    },
  );
  typia.assert(basicSearchResult);

  TestValidator.predicate(
    "basic search returns results containing search text",
    basicSearchResult.data.length > 0 &&
      basicSearchResult.data.some(
        (tag) =>
          tag.name.toLowerCase().includes(searchText.toLowerCase()) ||
          tag.code.toLowerCase().includes(searchText.toLowerCase()),
      ),
  );

  // Step 2: Test visibility filtering
  const visibleOnlyResult = await api.functional.shoppingMall.articleTags.index(
    connection,
    {
      body: {
        visible: true,
        page: 1,
        limit: 50,
      } satisfies IShoppingMallArticleTag.IRequest,
    },
  );
  typia.assert(visibleOnlyResult);

  TestValidator.predicate(
    "visibility filter returns only visible tags",
    visibleOnlyResult.data.every((tag) => tag.visible === true),
  );

  const hiddenOnlyResult = await api.functional.shoppingMall.articleTags.index(
    connection,
    {
      body: {
        visible: false,
        page: 1,
        limit: 50,
      } satisfies IShoppingMallArticleTag.IRequest,
    },
  );
  typia.assert(hiddenOnlyResult);

  TestValidator.predicate(
    "visibility filter returns only hidden tags",
    hiddenOnlyResult.data.every((tag) => tag.visible === false),
  );

  // Step 3: Test sorting functionality across different fields
  const sortFields: Array<"name" | "code" | "sequence"> = [
    "name",
    "code",
    "sequence",
  ];

  for (const field of sortFields) {
    // Test ascending order
    const ascendingResult = await api.functional.shoppingMall.articleTags.index(
      connection,
      {
        body: {
          sortBy: field,
          sortOrder: "asc",
          page: 1,
          limit: 20,
        } satisfies IShoppingMallArticleTag.IRequest,
      },
    );
    typia.assert(ascendingResult);

    TestValidator.predicate(
      `sorting by ${field} in ascending order works`,
      ascendingResult.data.length > 0 &&
        ascendingResult.data.every(
          (tag, index) =>
            index === 0 ||
            (field === "sequence"
              ? tag[field] >= ascendingResult.data[index - 1][field]
              : tag[field] >= ascendingResult.data[index - 1][field]),
        ),
    );

    // Test descending order
    const descendingResult =
      await api.functional.shoppingMall.articleTags.index(connection, {
        body: {
          sortBy: field,
          sortOrder: "desc",
          page: 1,
          limit: 20,
        } satisfies IShoppingMallArticleTag.IRequest,
      });
    typia.assert(descendingResult);

    TestValidator.predicate(
      `sorting by ${field} in descending order works`,
      descendingResult.data.length > 0 &&
        descendingResult.data.every(
          (tag, index) =>
            index === 0 ||
            (field === "sequence"
              ? tag[field] <= descendingResult.data[index - 1][field]
              : tag[field] <= descendingResult.data[index - 1][field]),
        ),
    );
  }

  // Step 4: Test exact matching for code and name
  // Get initial results to find valid codes/names
  const initialResults = await api.functional.shoppingMall.articleTags.index(
    connection,
    {
      body: {
        page: 1,
        limit: 5,
      } satisfies IShoppingMallArticleTag.IRequest,
    },
  );
  typia.assert(initialResults);

  if (initialResults.data.length > 0) {
    const exactCode = initialResults.data[0].code;
    const exactCodeResult = await api.functional.shoppingMall.articleTags.index(
      connection,
      {
        body: {
          code: exactCode,
          page: 1,
          limit: 5,
        } satisfies IShoppingMallArticleTag.IRequest,
      },
    );
    typia.assert(exactCodeResult);

    TestValidator.predicate(
      "exact code matching returns correct results",
      exactCodeResult.data.length > 0 &&
        exactCodeResult.data[0].code === exactCode,
    );

    const exactName = initialResults.data[0].name;
    const exactNameResult = await api.functional.shoppingMall.articleTags.index(
      connection,
      {
        body: {
          name: exactName,
          page: 1,
          limit: 5,
        } satisfies IShoppingMallArticleTag.IRequest,
      },
    );
    typia.assert(exactNameResult);

    TestValidator.predicate(
      "exact name matching returns correct results",
      exactNameResult.data.length > 0 &&
        exactNameResult.data[0].name === exactName,
    );
  }

  // Step 5: Test complex combined filters with supported parameters
  const complexFilterResult =
    await api.functional.shoppingMall.articleTags.index(connection, {
      body: {
        search: "tech",
        visible: true,
        sortBy: "sequence",
        sortOrder: "asc",
        page: 1,
        limit: 15,
      } satisfies IShoppingMallArticleTag.IRequest,
    });
  typia.assert(complexFilterResult);

  TestValidator.predicate(
    "complex multi-parameter filtering works correctly",
    complexFilterResult.data.length >= 0,
  );

  // Step 6: Test pagination boundaries
  const paginationTest = await api.functional.shoppingMall.articleTags.index(
    connection,
    {
      body: {
        page: 1000, // Extremely high page number
        limit: 1,
      } satisfies IShoppingMallArticleTag.IRequest,
    },
  );
  typia.assert(paginationTest);

  TestValidator.predicate(
    "pagination handles extreme page numbers gracefully",
    paginationTest.data.length === 0 &&
      paginationTest.pagination.current === 1000 &&
      paginationTest.pagination.limit === 1,
  );

  // Step 7: Test maximum limit
  const maxLimitResult = await api.functional.shoppingMall.articleTags.index(
    connection,
    {
      body: {
        limit: 100, // Maximum allowed limit
      } satisfies IShoppingMallArticleTag.IRequest,
    },
  );
  typia.assert(maxLimitResult);

  TestValidator.predicate(
    "maximum limit returns valid number of results",
    maxLimitResult.data.length <= 100,
  );

  // Step 8: Test empty search handling
  const emptySearchResult = await api.functional.shoppingMall.articleTags.index(
    connection,
    {
      body: {
        search: "nonexistentsearchtermthatshouldreturnnothing",
        page: 1,
        limit: 10,
      } satisfies IShoppingMallArticleTag.IRequest,
    },
  );
  typia.assert(emptySearchResult);

  TestValidator.equals(
    "empty search returns no results",
    emptySearchResult.data.length,
    0,
  );

  // Step 9: Verify pagination metadata consistency
  TestValidator.predicate(
    "pagination metadata is consistent",
    emptySearchResult.pagination.current === 1 &&
      emptySearchResult.pagination.limit === 10 &&
      emptySearchResult.pagination.records >= 0 &&
      emptySearchResult.pagination.pages >= 0,
  );

  // Step 10: Test minimum page value boundary
  const minPageResult = await api.functional.shoppingMall.articleTags.index(
    connection,
    {
      body: {
        page: 1, // Minimum page value
        limit: 5,
      } satisfies IShoppingMallArticleTag.IRequest,
    },
  );
  typia.assert(minPageResult);

  TestValidator.equals(
    "minimum page value returns first page results",
    minPageResult.pagination.current,
    1,
  );

  // Step 11: Test sorting field validation
  const validSortResult = await api.functional.shoppingMall.articleTags.index(
    connection,
    {
      body: {
        sortBy: RandomGenerator.pick([
          "name",
          "code",
          "sequence",
          "createdAt",
          "updatedAt",
          "usageCount",
        ]),
        sortOrder: RandomGenerator.pick(["asc", "desc"]),
        page: 1,
        limit: 10,
      } satisfies IShoppingMallArticleTag.IRequest,
    },
  );
  typia.assert(validSortResult);

  TestValidator.predicate(
    "valid sort field and order combination works",
    validSortResult.data.length >= 0,
  );
}

