import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallChannel";

/**
 * Test channel timezone specification updates including regional timezone
 * selection and time-sensitive operation scheduling. Validates proper regional
 * time handling for customer interactions and administrative operations
 * coordination.
 *
 * Test flow:
 *
 * 1. Create a new channel with initial timezone configuration
 * 2. Update the channel to use different regional timezones
 * 3. Validate timezone changes are properly reflected
 * 4. Test timezone updates for various geographic regions
 * 5. Ensure proper time-sensitive operation scheduling validation
 */
export async function test_api_channel_timezone_modification(
  connection: api.IConnection,
) {
  // Step 1: Create initial channel with timezone configuration
  const timezone = "America/New_York";
  const initialChannel = await api.functional.shoppingMall.channels.create(
    connection,
    {
      body: {
        code: typia.random<string & tags.MinLength<1> & tags.MaxLength<255>>(),
        name: RandomGenerator.name(),
        currency_code: "USD",
        language: "en",
        commission_rate: typia.random<
          number & tags.Minimum<0> & tags.Maximum<100>
        >(),
        time_zone: timezone,
      } satisfies IShoppingMallChannel.ICreate,
    },
  );
  typia.assert(initialChannel);

  TestValidator.equals(
    "initial channel timezone",
    initialChannel.time_zone,
    timezone,
  );

  // Step 2: Update to European timezone
  const europeTimezone = "Europe/London";
  const updatedChannel = await api.functional.shoppingMall.channels.update(
    connection,
    {
      channelCode: initialChannel.code,
      body: {
        id: initialChannel.id,
        time_zone: europeTimezone,
      } satisfies IShoppingMallChannel.IUpdate,
    },
  );
  typia.assert(updatedChannel);

  TestValidator.equals(
    "updated channel timezone to Europe",
    updatedChannel.time_zone,
    europeTimezone,
  );
  TestValidator.notEquals(
    "timezone field changed",
    initialChannel.time_zone,
    updatedChannel.time_zone,
  );

  // Step 3: Test timezone update to Asia region
  const asiaTimezone = "Asia/Tokyo";
  const asiaChannel = await api.functional.shoppingMall.channels.update(
    connection,
    {
      channelCode: initialChannel.code,
      body: {
        id: initialChannel.id,
        time_zone: asiaTimezone,
      } satisfies IShoppingMallChannel.IUpdate,
    },
  );
  typia.assert(asiaChannel);

  TestValidator.equals(
    "updated channel timezone to Asia",
    asiaChannel.time_zone,
    asiaTimezone,
  );

  // Step 4: Test timezone reset (null value)
  const nullTimezoneChannel = await api.functional.shoppingMall.channels.update(
    connection,
    {
      channelCode: initialChannel.code,
      body: {
        id: initialChannel.id,
        time_zone: null,
      } satisfies IShoppingMallChannel.IUpdate,
    },
  );
  typia.assert(nullTimezoneChannel);

  TestValidator.equals(
    "channel timezone set to null",
    nullTimezoneChannel.time_zone,
    null,
  );

  // Step 5: Test timezone update back to original timezone
  const finalChannel = await api.functional.shoppingMall.channels.update(
    connection,
    {
      channelCode: initialChannel.code,
      body: {
        id: initialChannel.id,
        time_zone: timezone,
      } satisfies IShoppingMallChannel.IUpdate,
    },
  );
  typia.assert(finalChannel);

  TestValidator.equals(
    "channel timezone restored",
    finalChannel.time_zone,
    timezone,
  );
  TestValidator.predicate(
    "channel update timestamp incremented",
    finalChannel.updated_at >= initialChannel.updated_at,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallChannel";

export async function test_api_channel_code_change_impact(
  connection: api.IConnection,
) {
  // Step 1: Create initial channel with business identifier code
  const initialChannel = await api.functional.shoppingMall.channels.create(
    connection,
    {
      body: {
        code: "primary-marketplace",
        name: "Primary Marketplace Channel",
        description: "Main selling environment for general merchandise",
        currency_code: "USD",
        language: "en",
        time_zone: "America/New_York",
        commission_rate: 5.5,
      } satisfies IShoppingMallChannel.ICreate,
    },
  );
  typia.assert(initialChannel);

  // Step 2: Update channel code to new URL-safe identifier
  const updatedChannel = await api.functional.shoppingMall.channels.update(
    connection,
    {
      channelCode: initialChannel.code,
      body: {
        id: initialChannel.id,
        code: "updated-primary-channel",
        name: "Updated Primary Channel",
        description: "Modernized marketplace with enhanced features",
      } satisfies IShoppingMallChannel.IUpdate,
    },
  );
  typia.assert(updatedChannel);

  // Step 3: Verify updated channel maintains properties
  TestValidator.equals(
    "channel ID unchanged",
    updatedChannel.id,
    initialChannel.id,
  );
  TestValidator.equals(
    "channel code updated",
    updatedChannel.code,
    "updated-primary-channel",
  );
  TestValidator.equals(
    "channel name updated",
    updatedChannel.name,
    "Updated Primary Channel",
  );
  TestValidator.equals(
    "currency preserved",
    updatedChannel.currency_code,
    initialChannel.currency_code,
  );
  TestValidator.equals(
    "language preserved",
    updatedChannel.language,
    initialChannel.language,
  );

  // Step 4: Test with URL-safe character patterns
  const urlSafeChannel = await api.functional.shoppingMall.channels.create(
    connection,
    {
      body: {
        code: "channel-123_test.env",
        name: "URL-Safe Test Channel",
        description: "Testing URL-safe characters in code",
        currency_code: "EUR",
        language: "de",
        commission_rate: 7.8,
      } satisfies IShoppingMallChannel.ICreate,
    },
  );
  typia.assert(urlSafeChannel);

  // Step 5: Update with complex URL-safe pattern
  const complexUpdated = await api.functional.shoppingMall.channels.update(
    connection,
    {
      channelCode: urlSafeChannel.code,
      body: {
        id: urlSafeChannel.id,
        code: "premium-channel_2024-v2",
        commission_rate: 8.2,
      } satisfies IShoppingMallChannel.IUpdate,
    },
  );
  typia.assert(complexUpdated);

  TestValidator.equals(
    "complex code updated",
    complexUpdated.code,
    "premium-channel_2024-v2",
  );
  TestValidator.equals(
    "commission rate updated",
    complexUpdated.commission_rate,
    8.2,
  );

  // Step 6: Validate integration compatibility
  TestValidator.predicate(
    "code length within limits",
    urlSafeChannel.code.length <= 255 && urlSafeChannel.code.length >= 1,
  );
  TestValidator.predicate(
    "updated channel active status correct",
    updatedChannel.is_active === true,
  );

  // Step 7: Verify system consistency across updates
  TestValidator.predicate(
    "timestamps updated correctly",
    updatedChannel.updated_at >= initialChannel.updated_at,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallChannel";

/**
 * Test attempt to delete non-existent channel.
 *
 * This test validates proper error handling when attempting to delete a channel
 * that does not exist, ensuring clear feedback and system stability.
 *
 * Test Steps:
 *
 * 1. Create an admin account for authentication
 * 2. Attempt to delete a non-existent channel using a random channel code
 * 3. Validate that the API returns an appropriate error response
 * 4. Ensure no system instability occurs from the invalid deletion attempt
 */
export async function test_api_channel_deletion_nonexistent_channel(
  connection: api.IConnection,
) {
  // Step 1: Create an admin account for authentication
  const adminEmail = RandomGenerator.alphabets(10) + "@test.com";
  const adminData = {
    email: adminEmail,
    firstname: RandomGenerator.name(),
    lastname: RandomGenerator.name(),
    adminlevel: "department_admin" as const,
    department: "Test Department",
  } satisfies IShoppingMallAdmin.ICreate;

  const admin = await api.functional.auth.admin.join(connection, {
    body: adminData,
  });
  typia.assert<IShoppingMallAdmin.IAuthorized>(admin);

  // Step 2: Attempt to delete a non-existent channel
  const nonExistentChannelCode = RandomGenerator.alphabets(20);

  // Step 3: Validate that the API returns an appropriate error response
  await TestValidator.error(
    "should reject deletion of non-existent channel",
    async () => {
      return await api.functional.shoppingMall.admin.channels.erase(
        connection,
        {
          channelCode: nonExistentChannelCode,
        },
      );
    },
  );

  // Step 4: Ensure no system instability - admin account should still be valid
  TestValidator.predicate(
    "admin account remains valid after failed deletion",
    admin.is_active === true,
  );
  TestValidator.predicate(
    "admin ID remains UUID format",
    typeof admin.id === "string" && admin.id.length === 36,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallChannel";

/**
 * Test channel creation with null timezone configuration.
 *
 * This test validates that marketplace channels can be successfully created
 * without explicitly specifying a timezone, testing the optional parameter
 * handling and ensuring system defaults are applied properly. The test follows
 * a complete channel creation workflow: 1) Create a channel with null timezone,
 * 2) Create a channel with undefined timezone, 3) Create a channel with
 * specified timezone for comparison, 4) Validate all channels were created
 * successfully with proper time_zone values.
 */
export async function test_api_channel_creation_default_timezone(
  connection: api.IConnection,
) {
  // Step 1: Create channel with null timezone
  const nullTimezoneChannel = await api.functional.shoppingMall.channels.create(
    connection,
    {
      body: {
        code: "test-channel-null",
        name: "Test Channel with Null Timezone",
        description: "Channel created with explicit null timezone",
        currency_code: "USD",
        language: "en",
        time_zone: null,
        commission_rate: 5.0,
      } satisfies IShoppingMallChannel.ICreate,
    },
  );
  typia.assert(nullTimezoneChannel);

  // Step 2: Create channel with undefined timezone (property omitted)
  const undefinedTimezoneChannel =
    await api.functional.shoppingMall.channels.create(connection, {
      body: {
        code: "test-channel-undefined",
        name: "Test Channel with Undefined Timezone",
        description: "Channel created without timezone property",
        currency_code: "EUR",
        language: "de",
        commission_rate: 7.5,
      } satisfies IShoppingMallChannel.ICreate,
    });
  typia.assert(undefinedTimezoneChannel);

  // Step 3: Create channel with specified timezone for comparison
  const specifiedTimezoneChannel =
    await api.functional.shoppingMall.channels.create(connection, {
      body: {
        code: "test-channel-specified",
        name: "Test Channel with Specified Timezone",
        description: "Channel created with explicit timezone",
        currency_code: "KRW",
        language: "ko",
        time_zone: "Asia/Seoul",
        commission_rate: 3.0,
      } satisfies IShoppingMallChannel.ICreate,
    });
  typia.assert(specifiedTimezoneChannel);

  // Step 4: Validate all channels were created successfully
  TestValidator.predicate(
    "null timezone channel created successfully",
    nullTimezoneChannel.id !== null,
  );
  TestValidator.equals(
    "null timezone channel has correct time_zone",
    nullTimezoneChannel.time_zone,
    null,
  );

  TestValidator.predicate(
    "undefined timezone channel created successfully",
    undefinedTimezoneChannel.id !== null,
  );
  TestValidator.equals(
    "undefined timezone channel has correct time_zone",
    undefinedTimezoneChannel.time_zone,
    undefined,
  );

  TestValidator.predicate(
    "specified timezone channel created successfully",
    specifiedTimezoneChannel.id !== null,
  );
  TestValidator.equals(
    "specified timezone channel has correct time_zone",
    specifiedTimezoneChannel.time_zone,
    "Asia/Seoul",
  );

  // Step 5: Validate other properties remain consistent
  TestValidator.equals(
    "null timezone channel name",
    nullTimezoneChannel.name,
    "Test Channel with Null Timezone",
  );
  TestValidator.equals(
    "undefined timezone channel name",
    undefinedTimezoneChannel.name,
    "Test Channel with Undefined Timezone",
  );
  TestValidator.equals(
    "specified timezone channel name",
    specifiedTimezoneChannel.name,
    "Test Channel with Specified Timezone",
  );

  TestValidator.equals(
    "null timezone channel currency",
    nullTimezoneChannel.currency_code,
    "USD",
  );
  TestValidator.equals(
    "undefined timezone channel currency",
    undefinedTimezoneChannel.currency_code,
    "EUR",
  );
  TestValidator.equals(
    "specified timezone channel currency",
    specifiedTimezoneChannel.currency_code,
    "KRW",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallChannel";

/**
 * Test channel creation with duplicate channel code validation.
 *
 * This test validates that the marketplace channel creation system enforces
 * uniqueness constraints on channel codes, preventing duplicate identifiers
 * within the platform. Channel codes serve as unique identifiers for
 * marketplace environments and must be unique across the entire system.
 *
 * The test demonstrates proper error handling and business rule validation for
 * channel management, ensuring data integrity and preventing conflicts in
 * multi-marketplace scenarios.
 *
 * Test steps:
 *
 * 1. Create initial channel with specific code
 * 2. Attempt to create duplicate channel with same code
 * 3. Validate that duplicate creation fails with appropriate error
 */
export async function test_api_channel_creation_duplicate_code_validation(
  connection: api.IConnection,
) {
  // Step 1: Create initial channel with specific code
  const channelData = {
    code: "test-channel-" + RandomGenerator.alphaNumeric(8),
    name: "Test Channel for Duplicate Validation",
    currency_code: "USD",
    language: "en",
    commission_rate: 5.0,
    description: "Channel created for testing duplicate code validation",
  } satisfies IShoppingMallChannel.ICreate;

  const firstChannel = await api.functional.shoppingMall.channels.create(
    connection,
    {
      body: channelData,
    },
  );
  typia.assert(firstChannel);

  // Step 2: Attempt to create duplicate channel with same code
  await TestValidator.error(
    "duplicate channel code creation should fail",
    async () => {
      await api.functional.shoppingMall.channels.create(connection, {
        body: {
          ...channelData,
          name: "Duplicate Channel Name",
        } satisfies IShoppingMallChannel.ICreate,
      });
    },
  );

  // Step 3: Verify that initial channel still exists and is valid
  TestValidator.predicate(
    "original channel creation was successful",
    firstChannel.code === channelData.code &&
      firstChannel.name === channelData.name &&
      ArrayUtil.repeat(3, () => firstChannel.commission_rate).every(
        (rate) => rate === channelData.commission_rate,
      ),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallChannel";

/**
 * Test channel creation with boundary commission rate values.
 *
 * Validates percentage-based constraints with minimum and maximum commission
 * rate boundaries, ensuring business rule compliance across the platform. This
 * test examines extreme values at both ends of the valid range (0% and 100%)
 * and carefully approaches boundary conditions to ensure the commission_rate
 * field properly enforces the Minimum<0> and Maximum<100> constraints as
 * defined in IShoppingMallChannel.ICreate.
 *
 * Test scenarios include:
 *
 * 1. Minimum commission rate (0%) - should succeed
 * 2. Maximum commission rate (100%) - should succeed
 * 3. Rates near boundaries to ensure proper enforcement
 *
 * The test ensures that the commission_rate field in
 * IShoppingMallChannel.ICreate correctly validates the number type with
 * tags.Minimum<0> and tags.Maximum<100> constraints, maintaining business rule
 * compliance for marketplace operations.
 */
export async function test_api_channel_creation_boundary_commission(
  connection: api.IConnection,
) {
  // Test minimum commission rate (0%)
  const minCommissionBody = {
    code: RandomGenerator.alphaNumeric(10),
    name: RandomGenerator.name(),
    currency_code: "USD",
    language: "en",
    commission_rate: 0, // Minimum boundary value
  } satisfies IShoppingMallChannel.ICreate;

  const minCommissionChannel =
    await api.functional.shoppingMall.channels.create(connection, {
      body: minCommissionBody,
    });
  typia.assert(minCommissionChannel);

  TestValidator.equals(
    "minimum commission rate creation",
    minCommissionChannel.commission_rate,
    0,
  );

  // Test maximum commission rate (100%)
  const maxCommissionBody = {
    code: RandomGenerator.alphaNumeric(10),
    name: RandomGenerator.name(),
    currency_code: "USD",
    language: "en",
    commission_rate: 100, // Maximum boundary value
  } satisfies IShoppingMallChannel.ICreate;

  const maxCommissionChannel =
    await api.functional.shoppingMall.channels.create(connection, {
      body: maxCommissionBody,
    });
  typia.assert(maxCommissionChannel);

  TestValidator.equals(
    "maximum commission rate creation",
    maxCommissionChannel.commission_rate,
    100,
  );

  // Test fractional commission rate near maximum boundary
  const nearMaxCommissionBody = {
    code: RandomGenerator.alphaNumeric(10),
    name: RandomGenerator.name(),
    currency_code: "USD",
    language: "en",
    commission_rate: 99.99, // Near maximum boundary
  } satisfies IShoppingMallChannel.ICreate;

  const nearMaxCommissionChannel =
    await api.functional.shoppingMall.channels.create(connection, {
      body: nearMaxCommissionBody,
    });
  typia.assert(nearMaxCommissionChannel);

  TestValidator.equals(
    "near-maximum commission rate creation",
    nearMaxCommissionChannel.commission_rate,
    99.99,
  );

  // Test fractional commission rate near minimum boundary
  const nearMinCommissionBody = {
    code: RandomGenerator.alphaNumeric(10),
    name: RandomGenerator.name(),
    currency_code: "USD",
    language: "en",
    commission_rate: 0.01, // Near minimum boundary
  } satisfies IShoppingMallChannel.ICreate;

  const nearMinCommissionChannel =
    await api.functional.shoppingMall.channels.create(connection, {
      body: nearMinCommissionBody,
    });
  typia.assert(nearMinCommissionChannel);

  TestValidator.equals(
    "near-minimum commission rate creation",
    nearMinCommissionChannel.commission_rate,
    0.01,
  );

  // Test with description and timezone
  const detailedCommissionBody = {
    code: RandomGenerator.alphaNumeric(10),
    name: RandomGenerator.name(),
    description: RandomGenerator.paragraph({ sentences: 3 }),
    currency_code: "EUR",
    language: "de",
    time_zone: "Europe/Berlin",
    commission_rate: 15.5, // Mid-range commission rate
  } satisfies IShoppingMallChannel.ICreate;

  const detailedCommissionChannel =
    await api.functional.shoppingMall.channels.create(connection, {
      body: detailedCommissionBody,
    });
  typia.assert(detailedCommissionChannel);

  TestValidator.predicate(
    "detailed commission rate within range",
    detailedCommissionChannel.commission_rate >= 0 &&
      detailedCommissionChannel.commission_rate <= 100,
  );
}

