        body: duplicateChannelData,
      });
    },
  );

  // Step 3: Verify initial channel remains intact
  TestValidator.equals(
    "initial channel code preserved",
    initialChannel.code,
    initialChannelCode,
  );
  TestValidator.predicate(
    "initial channel is active",
    initialChannel.is_active,
  );
