  // Create EU marketplace channel for European operations
  const euChannelBody = {
    code: "eu-market",
    name: "EU Market",
    description:
      "European marketplace with EUR currency and multiple language support",
    currency_code: "EUR",
    language: "en-GB",
    time_zone: "Europe/London",
