  typia.assert(premiumChannel);

  // Create Asia-Pacific channel for multiple regions
  const apacChannelBody = {
    code: "apac-market",
    name: "APAC Market",
    description:
      "Asia-Pacific marketplace supporting multiple currencies and timezones",
    currency_code: "JPY",
    language: "ja-JP",
    time_zone: "Asia/Tokyo",
    commission_rate: 6.5,
