  // Test maximum commission rate
  const maxCommissionBody = {
    code: "maximum-commission",
    name: "Maximum Commission Channel",
    description: "Channel with maximum allowable commission rate",
    currency_code: "USD",
    language: "en-US",
    time_zone: "UTC",
