  const adminEmail = `admin_${RandomGenerator.alphabets(8)}@shoppingmall.com`;
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        firstname: RandomGenerator.name(),
        lastname: RandomGenerator.name(),
        adminlevel: "super_admin",
        department: "seller_management",
      } satisfies IShoppingMallAdmin.ICreate,
    });
  typia.assert(admin);

  // Step 2: Create multiple test sellers with varying characteristics
  const businessTypes = [
    "corporation",
    "partnership",
    "sole_proprietorship",
  ] as const;
  const verificationStatuses = [
    "pending",
    "verified",
    "suspended",
    "rejected",
  ] as const;
  const sellers = ArrayUtil.repeat(20, (index) => {
    return {
      email: `seller${index + 1}_${RandomGenerator.alphabets(6)}@business.com`,
      business_name: RandomGenerator.name(2),
      phone: RandomGenerator.mobile(),
      business_type: businessTypes[index % businessTypes.length],
      verification_status:
        verificationStatuses[index % verificationStatuses.length],
      commission_rate: typia.random<
        number & tags.Minimum<0> & tags.Maximum<100>
      >(),
      is_verified: index % 3 === 0,
      created_at: new Date(
        Date.now() - index * 24 * 60 * 60 * 1000,
      ).toISOString(),
      updated_at: new Date(
        Date.now() - (index / 2) * 24 * 60 * 60 * 1000,
      ).toISOString(),
    };
  });

  // Step 3: Test basic multi-criteria search with search term + verification status
  const basicSearch = sellers.find(
    (s) => s.verification_status === "verified" && s.business_name.length > 0,
  );

  const basicSearchResult =
    await api.functional.shoppingMall.admin.sellers.index(connection, {
      body: {
        search: basicSearch?.business_name,
        verification_status: "verified",
        sort_by: "business_name",
        sort_order: "asc",
        page: 1,
        limit: 10,
      } satisfies IShoppingMallSeller.IRequest,
    });
  typia.assert(basicSearchResult);

  TestValidator.predicate(
    "basic search returns results matching both criteria",
    basicSearchResult.data.length > 0 &&
      basicSearchResult.data.every(
        (seller) =>
          seller.verification_status === "verified" &&
          (basicSearch?.business_name
            ? seller.business_name.includes(basicSearch.business_name)
            : true),
      ),
  );

  // Step 4: Test commission rate range filtering combined with business type
  const verificationSellers = sellers.filter(
    (s) =>
      s.commission_rate >= 10 &&
      s.commission_rate <= 50 &&
      s.business_type === "corporation",
  );

  if (verificationSellers.length > 0) {
    const commissionSearchResult =
      await api.functional.shoppingMall.admin.sellers.index(connection, {
        body: {
          commission_rate_min: 10,
          commission_rate_max: 50,
          business_type: "corporation",
          sort_by: "commission_rate",
          sort_order: "desc",
          page: 1,
          limit: 5,
        } satisfies IShoppingMallSeller.IRequest,
      });
    typia.assert(commissionSearchResult);

    TestValidator.predicate(
      "commission rate filtering works with business type",
      commissionSearchResult.data.length > 0 &&
        commissionSearchResult.data.every(
          (seller) =>
            seller.commission_rate >= 10 &&
            seller.commission_rate <= 50 &&
            seller.business_type === "corporation",
        ),
    );
  }

  // Step 5: Test date range filtering with verification status
  const dateSellers = sellers.filter(
    (s) =>
      s.verification_status === "pending" &&
      !s.is_verified &&
      s.created_at >=
        new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString(),
  );

  if (dateSellers.length > 0) {
    const dateRange = {
      start: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString(),
      end: new Date().toISOString(),
    };

    const dateSearchResult =
      await api.functional.shoppingMall.admin.sellers.index(connection, {
        body: {
          created_after: dateRange.start,
          created_before: dateRange.end,
          verification_status: "pending",
          is_verified: false,
          sort_by: "created_at",
          sort_order: "desc",
          page: 1,
          limit: 15,
        } satisfies IShoppingMallSeller.IRequest,
      });
    typia.assert(dateSearchResult);

    TestValidator.predicate(
      "date range filtering works with verification status",
      dateSearchResult.data.length > 0 &&
        dateSearchResult.data.every(
          (seller) =>
            seller.created_at >= dateRange.start &&
            seller.created_at <= dateRange.end &&
            seller.verification_status === "pending" &&
            !seller.is_verified,
        ),
    );
  }

  // Step 6: Test complex combination of all filters
  const complexSellers = sellers.filter(
    (s) =>
      s.verification_status === "verified" &&
      s.commission_rate >= 5 &&
      s.commission_rate <= 95 &&
      s.business_type ===
        businessTypes[Math.floor(Math.random() * businessTypes.length)] &&
      s.created_at >=
        new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString() &&
      s.is_verified === true,
  );

  if (complexSellers.length > 0) {
    const selectedBusiness =
      complexSellers[0]?.business_type || businessTypes[0];
    const complexSearchResult =
      await api.functional.shoppingMall.admin.sellers.index(connection, {
        body: {
          search: complexSellers[0]?.business_name.split(" ")[0],
          verification_status: "verified",
          commission_rate_min: 5,
          commission_rate_max: 95,
          business_type: selectedBusiness,
          created_after: new Date(
            Date.now() - 30 * 24 * 60 * 60 * 1000,
          ).toISOString(),
          is_verified: true,
          sort_by: "commission_rate",
          sort_order: "asc",
          page: 1,
          limit: 20,
        } satisfies IShoppingMallSeller.IRequest,
      });
    typia.assert(complexSearchResult);

    TestValidator.predicate(
      "complex multi-filter search returns sellers matching all criteria",
      complexSearchResult.data.length > 0 &&
        complexSearchResult.data.every((seller) => {
          const searchMatch = complexSellers[0]?.business_name
            ? seller.business_name.includes(
                complexSellers[0].business_name.split(" ")[0],
              )
            : true;
          const statusMatch = seller.verification_status === "verified";
          const commissionMatch =
            seller.commission_rate >= 5 && seller.commission_rate <= 95;
          const businessMatch = seller.business_type === selectedBusiness;
          const dateMatch =
            seller.created_at >=
            new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString();
          const verifiedMatch = seller.is_verified === true;

          return (
            searchMatch &&
            statusMatch &&
            commissionMatch &&
            businessMatch &&
            dateMatch &&
            verifiedMatch
          );
        }),
    );
  }

  // Step 7: Test pagination with realistic expectation
  const page1Result = await api.functional.shoppingMall.admin.sellers.index(
    connection,
    {
      body: {
        commission_rate_min: 0,
        commission_rate_max: 100,
        sort_by: "created_at",
        sort_order: "desc",
        page: 1,
        limit: 5,
      } satisfies IShoppingMallSeller.IRequest,
    },
  );
  typia.assert(page1Result);

  if (page1Result.pagination.records > page1Result.pagination.limit) {
    const page2Result = await api.functional.shoppingMall.admin.sellers.index(
      connection,
      {
        body: {
          commission_rate_min: 0,
          commission_rate_max: 100,
          sort_by: "created_at",
          sort_order: "desc",
          page: 2,
          limit: page1Result.pagination.limit,
        } satisfies IShoppingMallSeller.IRequest,
      },
    );
    typia.assert(page2Result);

    TestValidator.predicate(
      "page 2 returns different results when enough records exist",
      page2Result.data.length > 0,
    );
  }

  // Step 8: Test sorting variations
  const sortByNameAscResult =
    await api.functional.shoppingMall.admin.sellers.index(connection, {
      body: {
        sort_by: "business_name",
        sort_order: "asc",
        page: 1,
        limit: 10,
      } satisfies IShoppingMallSeller.IRequest,
    });
  typia.assert(sortByNameAscResult);

  const sortByNameDescResult =
    await api.functional.shoppingMall.admin.sellers.index(connection, {
      body: {
        sort_by: "business_name",
        sort_order: "desc",
        page: 1,
        limit: 10,
      } satisfies IShoppingMallSeller.IRequest,
    });
  typia.assert(sortByNameDescResult);

  TestValidator.predicate(
    "ascending and descending order return results",
    sortByNameAscResult.data.length > 0 && sortByNameDescResult.data.length > 0,
  );

  // Step 9: Test verification of pagination metadata
  TestValidator.predicate(
    "pagination info is consistent",
    basicSearchResult.pagination.current === 1 &&
      basicSearchResult.pagination.records >= basicSearchResult.data.length,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallGlobalSearchResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallGlobalSearchResult";
import type { IShoppingMallAnalyticsSummary } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAnalyticsSummary";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallGlobalSearch } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallGlobalSearch";
import type { IShoppingMallGlobalSearchResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallGlobalSearchResult";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductCategory";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Test basic product search functionality where customers search for products
 * using simple keywords. Validates that the search returns relevant product
 * results with proper categorization, pricing information, and seller details.
 * Tests the core search algorithm's ability to match product names,
 * descriptions, and specifications against user queries.
 */
export async function test_api_global_search_basic_product_discovery(
  connection: api.IConnection,
) {
  // Generate realistic product search queries
  const searchQueries = [
    "smartphone",
    "laptop computer",
    "wireless headphones",
    "gaming console",
    "kitchen appliance",
    "fashion clothing",
    "home furniture",
  ];

  // Test search with different queries
  for (const query of searchQueries) {
    const searchRequest = {
      query: query,
      sort_order: "relevance" as const,
      page: 1,
      limit: 20,
    } satisfies IShoppingMallGlobalSearch.IRequest;

    const searchResults = await api.functional.shoppingMall.search.global(
      connection,
      {
        body: searchRequest,
      },
    );

    // Validate response structure
    typia.assert(searchResults);
    TestValidator.predicate(
      "search results have valid pagination",
      searchResults.pagination !== undefined,
    );
    TestValidator.predicate(
      "search results have data array",
      Array.isArray(searchResults.data),
    );
    TestValidator.predicate(
      "search results pagination current page is 1",
      searchResults.pagination.current === 1,
    );
    TestValidator.predicate(
      "search results pagination limit is 20",
      searchResults.pagination.limit === 20,
    );

    if (searchResults.data.length > 0) {
      const firstResult = searchResults.data[0];
      TestValidator.predicate(
        "search result has categories array",
        Array.isArray(firstResult.categories),
      );
      TestValidator.predicate(
        "search result has products array",
        Array.isArray(firstResult.products),
      );
      TestValidator.predicate(
        "search result has sellers array",
        Array.isArray(firstResult.sellers),
      );
      TestValidator.predicate(
        "search result has customers array",
        Array.isArray(firstResult.customers),
      );
      TestValidator.predicate(
        "search result has analytics array",
        Array.isArray(firstResult.analytics),
      );
      TestValidator.predicate(
        "search result has total results count",
        typeof firstResult.total_results === "number",
      );
      TestValidator.predicate(
        "search result has search query",
        typeof firstResult.search_query === "string",
      );

      // Validate product information if products exist
      if (firstResult.products.length > 0) {
        const product = firstResult.products[0];
        TestValidator.predicate(
          "product has valid ID format",
          product.id !== undefined,
        );
        TestValidator.predicate("product has name", product.name !== undefined);
        TestValidator.predicate(
          "product has description",
          product.description !== undefined,
        );
        TestValidator.predicate(
          "product has price",
          product.price !== undefined,
        );
        TestValidator.predicate(
          "product has seller",
          product.seller !== undefined,
        );
        TestValidator.predicate(
          "product has category",
          product.category !== undefined,
        );
        TestValidator.predicate(
          "product has images array",
          Array.isArray(product.images),
        );
        TestValidator.predicate(
          "product price is non-negative",
          product.price >= 0,
        );

        // Validate seller information
        const seller = product.seller;
        TestValidator.predicate(
          "seller has valid ID format",
          seller.id !== undefined,
        );
        TestValidator.predicate("seller has email", seller.email !== undefined);
        TestValidator.predicate(
          "seller has business name",
          seller.business_name !== undefined,
        );
        TestValidator.predicate(
          "seller has verification status",
          seller.verification_status !== undefined,
        );
        TestValidator.predicate(
          "seller has verification flag",
          typeof seller.is_verified === "boolean",
        );

        // Validate category information
        const category = product.category;
        TestValidator.predicate(
          "category has valid ID format",
          category.id !== undefined,
        );
        TestValidator.predicate(
          "category has name",
          category.name !== undefined,
        );
        TestValidator.predicate(
          "category has path",
          category.path !== undefined,
        );
        TestValidator.predicate(
          "category has level",
          typeof category.level === "number",
        );
        TestValidator.predicate(
          "category has product count",
          typeof category.product_count === "number",
        );
        TestValidator.predicate(
          "category has active status",
          typeof category.is_active === "boolean",
        );
      }
    }
  }

  // Test with category filter
  const categorySearchRequest = {
    query: RandomGenerator.name(2),
    sort_order: "relevance" as const,
    page: 1,
    limit: 10,
    content_types: ["products"] as const,
    category_filter: "electronics",
  } satisfies IShoppingMallGlobalSearch.IRequest;

  const categoryResults = await api.functional.shoppingMall.search.global(
    connection,
    {
      body: categorySearchRequest,
    },
  );

  typia.assert(categoryResults);
  TestValidator.predicate(
    "category search returns valid results",
    categoryResults.data.length >= 0,
  );

  if (
    categoryResults.data.length > 0 &&
    categoryResults.data[0].products.length > 0
  ) {
    const product = categoryResults.data[0].products[0];
    TestValidator.predicate(
      "category filtered product has valid structure",
      product.category !== undefined,
    );
  }

  // Test price range filtering
  const priceRangeRequest = {
    query: RandomGenerator.name(1),
    sort_order: "price_asc" as const,
    page: 1,
    limit: 15,
    content_types: ["products"] as const,
    min_price: 100,
    max_price: 1000,
  } satisfies IShoppingMallGlobalSearch.IRequest;

  const priceResults = await api.functional.shoppingMall.search.global(
    connection,
    {
      body: priceRangeRequest,
    },
  );

  typia.assert(priceResults);
  TestValidator.predicate(
    "price range search returns valid results",
    priceResults.data.length >= 0,
  );

  if (priceResults.data.length > 0) {
    const products = priceResults.data[0].products;
    products.forEach((product) => {
      TestValidator.predicate(
        "product price is within min range",
        product.price >= 100,
      );
      TestValidator.predicate(
        "product price is within max range",
        product.price <= 1000,
      );
    });
  }

  // Test empty search query edge case
  const emptyQueryRequest = {
    query: "",
    sort_order: "relevance" as const,
    page: 1,
    limit: 10,
    content_types: ["products"] as const,
  } satisfies IShoppingMallGlobalSearch.IRequest;

  const emptyResults = await api.functional.shoppingMall.search.global(
    connection,
    {
      body: emptyQueryRequest,
    },
  );

  typia.assert(emptyResults);
  TestValidator.predicate(
    "empty query returns valid structure",
    Array.isArray(emptyResults.data),
  );
  TestValidator.predicate(
    "empty query returns valid pagination",
    emptyResults.pagination !== undefined,
  );

  // Test different result ordering
  const orderTypes = [
    "relevance",
    "date",
    "price_asc",
    "price_desc",
    "popularity",
  ] as const;
  for (const orderType of orderTypes) {
    const orderRequest = {
      query: RandomGenerator.name(1),
      sort_order: orderType,
      page: 1,
      limit: 10,
      content_types: ["products"] as const,
    } satisfies IShoppingMallGlobalSearch.IRequest;

    const orderResults = await api.functional.shoppingMall.search.global(
      connection,
      {
        body: orderRequest,
      },
    );

    typia.assert(orderResults);
    TestValidator.predicate(
      `order type ${orderType} returns valid results`,
      orderResults.data.length >= 0,
    );
  }

  // Test page pagination
  const paginationRequests = [
    { page: 1, limit: 5 },
    { page: 2, limit: 10 },
    { page: 3, limit: 15 },
  ];

  for (const pagReq of paginationRequests) {
    const pagRequest = {
      query: RandomGenerator.name(1),
      sort_order: "relevance" as const,
      page: pagReq.page,
      limit: pagReq.limit,
      content_types: ["products"] as const,
    } satisfies IShoppingMallGlobalSearch.IRequest;

    const pagResults = await api.functional.shoppingMall.search.global(
      connection,
      {
        body: pagRequest,
      },
    );

    typia.assert(pagResults);
    TestValidator.predicate(
      `pagination page ${pagReq.page} returns valid structure`,
      pagResults.pagination.current === pagReq.page,
    );
    TestValidator.predicate(
      `pagination limit ${pagReq.limit} matches request`,
      pagResults.pagination.limit === pagReq.limit,
    );
  }

  // Test content type combinations
  const contentTypeTests = [
    ["products", "articles"],
    ["products", "faq"],
    ["articles", "help"],
    ["products", "articles", "faq", "help"],
  ];

  for (const contentTypes of contentTypeTests) {
    const multiTypeRequest = {
      query: RandomGenerator.name(1),
      sort_order: "relevance" as const,
      page: 1,
      limit: 20,
      content_types: contentTypes as (
        | "products"
        | "articles"
        | "faq"
        | "help"
      )[],
    } satisfies IShoppingMallGlobalSearch.IRequest;

    const multiResults = await api.functional.shoppingMall.search.global(
      connection,
      {
        body: multiTypeRequest,
      },
    );

    typia.assert(multiResults);
    if (multiResults.data.length > 0) {
      const result = multiResults.data[0];
      if (contentTypes.includes("products")) {
        TestValidator.predicate(
          "multi-type search includes products",
          Array.isArray(result.products),
        );
      }
      if (contentTypes.includes("articles")) {
        TestValidator.predicate(
          "multi-type search includes articles structure",
          Array.isArray(result.categories),
        );
      }
    }
  }

  // Test with user preferences
  const prefRequest = {
    query: RandomGenerator.name(1),
    sort_order: "relevance" as const,
    page: 1,
    limit: 15,
    content_types: ["products"] as const,
    user_preferences: ["electronics", "gadgets", "mobile"],
  } satisfies IShoppingMallGlobalSearch.IRequest;

  const prefResults = await api.functional.shoppingMall.search.global(
    connection,
    {
      body: prefRequest,
    },
  );

  typia.assert(prefResults);
  TestValidator.predicate(
    "search with user preferences returns valid results",
    prefResults.data.length >= 0,
  );

  // Test date range filtering
  const dateRange = `${new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString().split("T")[0]}..${new Date().toISOString().split("T")[0]}`;

  const dateRangeRequest = {
    query: RandomGenerator.name(1),
    sort_order: "date" as const,
    page: 1,
    limit: 10,
    content_types: ["products"] as const,
    date_range: dateRange,
  } satisfies IShoppingMallGlobalSearch.IRequest;

  const dateResults = await api.functional.shoppingMall.search.global(
    connection,
    {
      body: dateRangeRequest,
    },
  );

  typia.assert(dateResults);
  TestValidator.predicate(
    "date range search returns valid results",
    dateResults.data.length >= 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallGlobalSearchResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallGlobalSearchResult";
import type { IShoppingMallAnalyticsSummary } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAnalyticsSummary";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallGlobalSearch } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallGlobalSearch";
import type { IShoppingMallGlobalSearchResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallGlobalSearchResult";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductCategory";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Test category-based search filtering where customers search within specific
 * product categories. Validates hierarchical category filtering, breadcrumb
 * navigation support, and proper category-specific result ranking. Tests both
 * top-level and subcategory filtering scenarios.
 */
export async function test_api_global_search_category_restriction(
  connection: api.IConnection,
): Promise<void> {
  // Step 1: Create comprehensive test data structure with hierarchical categories
  let categories: ReturnType<typeof createTestDataStructure> | undefined;

  // Create reusable test data structure
  categories = createTestDataStructure();

  // Step 2: Test global search with category restrictions
  await testBasicCategoryRestriction(connection, categories);

  // Step 3: Test hierarchical category filtering
  await testHierarchicalCategoryFiltering(connection, categories);

  // Step 4: Test breadcrumb navigation support
  await testBreadcrumbNavigation(connection, categories);

  // Step 5: Test content type filtering
  await testContentTypeFiltering(connection);

  // Step 6: Test comprehensive category-specific result ranking
  await testComprehensiveCategoryFiltering(connection, categories);
}

/** Create comprehensive test data structure with hierarchical categories */
function createTestDataStructure() {
  // Create top-level category: Electronics
  const electronics = {
    id: typia.random<string & tags.Format<"uuid">>(),
    code: "electronics",
    name: "Electronics",
    description: "Electronic devices and gadgets",
    path: "Electronics",
    level: 0,
    parent: undefined,
    is_active: true,
    is_featured: true,
    product_count: 0,
    updated_at: new Date().toISOString(),
  } satisfies IShoppingMallProductCategory.ISummary;

  // Create subcategory: Computers
  const computers = {
    id: typia.random<string & tags.Format<"uuid">>(),
    code: "computers",
    name: "Computers",
    description: "Personal computers and laptops",
    path: "Electronics/Computers",
    level: 1,
    parent: electronics,
    is_active: true,
    is_featured: false,
    product_count: 0,
    updated_at: new Date().toISOString(),
  } satisfies IShoppingMallProductCategory.ISummary;

  // Create sub-subcategory: Laptops
  const laptops = {
    id: typia.random<string & tags.Format<"uuid">>(),
    code: "laptops",
    name: "Laptops",
    description: "Notebook and gaming laptops",
    path: "Electronics/Computers/Laptops",
    level: 2,
    parent: computers,
