    channel1.language,
    "en",
  );
  TestValidator.equals(
    "second channel has FR language",
    channel2.language,
    "fr",
  );
  TestValidator.predicate(
    "commission rates are within valid range",
    channel1.commission_rate >= 0 &&
      channel1.commission_rate <= 100 &&
      channel2.commission_rate >= 0 &&
      channel2.commission_rate <= 100,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallChannel";

export async function test_api_channel_currency_language_compliance(
  connection: api.IConnection,
) {
  // List of common ISO 4217 currency codes for testing
  const iso4217Currencies = [
    "USD", // US Dollar
    "EUR", // Euro
    "JPY", // Japanese Yen
    "GBP", // British Pound
    "CNY", // Chinese Yuan
    "KRW", // Korean Won
    "AUD", // Australian Dollar
    "CAD", // Canadian Dollar
    "CHF", // Swiss Franc
    "MXN", // Mexican Peso
  ] as const;

  // List of common language codes for international support
  const languageCodes = [
    "en",
    "ko",
    "ja",
    "zh",
    "es",
    "fr",
    "de",
    "pt",
    "ru",
    "ar",
  ] as const;

  // List of common timezones for regional operations
  const timezones = [
    "America/New_York",
    "Europe/London",
    "Asia/Tokyo",
    "Asia/Seoul",
    "Asia/Shanghai",
    "Australia/Sydney",
    "America/Los_Angeles",
    "America/Mexico_City",
    "Europe/Berlin",
    "Asia/Dubai",
  ] as const;

  // Create multiple channels testing different international configurations
  const channels = await ArrayUtil.asyncRepeat(5, async (index) => {
    const currency = RandomGenerator.pick(iso4217Currencies);
    const language = RandomGenerator.pick(languageCodes);
    const timezone = RandomGenerator.pick(timezones);
